/* Acuerdo (ver Acuerdo.tsx). Badges con la forma de BadgeStatus (9 px, píldora, 80 de ancho mín.); el color dice la etapa:
   teal = en negociación (el mismo de NEGOCIABLE), magenta = SubasChat (con acuerdo), verde = vendida, gris = no concretada. */
.ac-badge { gap:4px; padding:3px 8px; }
.ac-badge svg { flex:none; }
.badgestatus.ac-badge--negociacion { background-image:linear-gradient(135deg, #30E8EC 0%, #00CACE 45%, #008688 100%); box-shadow:rgba(0,134,136,.4) 0 2px 10px, rgba(255,255,255,.14) 0 1px 0 inset; }
/* SubasChat: el magenta del lab (#CC00FF → #FF0066), como «te toca» en las negociaciones. */
.badgestatus.ac-badge--aceptada { background-image:linear-gradient(135deg, #CC00FF 0%, #E6007E 55%, #FF0066 100%); box-shadow:rgba(204,0,255,.35) 0 2px 10px, rgba(255,255,255,.14) 0 1px 0 inset; }
.badgestatus.ac-badge--vendida { background-image:linear-gradient(135deg, #4ADE80 0%, #16A34A 55%, #15803D 100%); box-shadow:rgba(22,163,74,.35) 0 2px 10px, rgba(255,255,255,.14) 0 1px 0 inset; }
.badgestatus.ac-badge--no { color:#4A4855; background:#ECECEE; border-color:#DCDCE0; backdrop-filter:none; -webkit-backdrop-filter:none; }
.fr--publication .fr__deal-note { color:#191C1C; font-weight:400; }

/* Cabecera del panel de la negociación con el chat abierto: la tarjeta del auto lleva al detalle de la oferta. */
.g-qv__go-link { display:inline-flex; align-items:center; gap:4px; font-size:.8125rem; font-weight:600; color:#5A35C2; text-decoration:underline; text-underline-offset:3px; text-decoration-color:rgba(90,53,194,.35); }
.g-qv__go-link:hover { color:#3B1782; text-decoration-color:currentColor; }
.g-qv__go-link:focus-visible { outline:2px solid #8460E5; outline-offset:2px; border-radius:4px; }
.g-qv__go-link svg { transition:transform .15s; } .g-qv__go-link:hover svg { transform:translate(1px,-1px); }
/* Toda la tarjeta: foto y ficha forman un solo enlace (ocupa las dos primeras columnas de la cabecera) con su estado al pasar. */
a.g-qv__go { grid-column:1 / 3; display:grid; grid-template-columns:auto 1fr; align-items:center; column-gap:16px; margin:-8px; padding:8px; border-radius:16px; color:inherit; text-decoration:none; transition:background .15s, box-shadow .15s; }
a.g-qv__go:hover { background:#F8F5FF; box-shadow:inset 0 0 0 1px #E0D4FF; }
a.g-qv__go:focus-visible { outline:2px solid #8460E5; outline-offset:2px; }
a.g-qv__go .g-qv__pic { position:relative; }
/* Con enlace y tarjeta a la vez, el enlace es texto dentro del enlace mayor: se ve, pero no es otro destino. */
a.g-qv__go .g-qv__go-link { text-decoration-color:rgba(90,53,194,.35); }
a.g-qv__go:hover .g-qv__go-link { color:#3B1782; text-decoration-color:currentColor; }
a.g-qv__go:hover .g-qv__go-link svg { transform:translate(1px,-1px); }
@media (prefers-reduced-motion:reduce) { a.g-qv__go, .g-qv__go-link svg { transition:none; } }
#lab-dock .lab-dock__col > .f-sw--acuerdo:not(.f-sw--closed) { order:-2; flex:none; overflow:visible; }

"use client";

/**
 * Acuerdo (29/10): lo que pasa con la publicación y el detalle después de que se acepta una propuesta.
 * 1) Mis publicaciones: En revisión → Publicada → En negociación (con propuestas, cian) → SubasChat (aceptada, magenta): la venta
 *    sigue en SubasChat.
 *    Dos semanas después ambas partes confirman en el chat si se dio la transferencia y el recojo: «Vendido» o «No concretada».
 * 2) Panel de la negociación: la tarjeta del auto lleva al detalle de la oferta (/m/oferta), donde el chat reemplaza al
 *    DetailCard. Solo para el comprador y el vendedor del acuerdo, y solo con el chat abierto.
 * El panel «Acuerdo» compara los textos de cada badge (?acpub=…); ?acuerdo=chat abre el chat.
 * Ir al detalle (02/11, Julio): queda «Tarjeta + enlace»: se ve «Ir a detalle» y toda la cabecera es clicable con su hover.
 */
import { useEffect, useSyncExternalStore } from "react";
import type { JSX } from "react";
import { LabPanel } from "./LabPanel";
import "./acuerdo.css";

export type Deal = "aceptada" | "vendida" | "no";
export type DealSim = "flujo" | Deal;
export type DetailGo = "tarjeta" | "enlace" | "ambos";
type Opt<T extends string> = { id: T; label: string; hint: string };

export const ACCEPTED: Opt<string>[] = [
  { id: "subaschat", label: "SubasChat", hint: "Dice dónde sigue la venta: se coordina en el chat. En magenta, para distinguirlo de «En negociación» (cian)." },
  { id: "aceptada", label: "Negociación aceptada", hint: "Dice qué pasó. Es el texto más largo: ocupa casi el doble que «Publicada»." },
  { id: "acuerdo", label: "Con acuerdo", hint: "Corto y neutro: hay precio pactado, falta concretar." },
  { id: "coordinando", label: "Coordinando", hint: "Dice qué hacen ahora comprador y vendedor: la visita, la transferencia y el recojo." },
];
export const SOLD: Opt<string>[] = [
  { id: "vendido", label: "Vendido", hint: "Ambas partes confirmaron en SubasChat la transferencia y el recojo." },
  { id: "concretada", label: "Venta concretada", hint: "Mismo caso; empareja con «No concretada»." },
];
export const LOST: Opt<string>[] = [
  { id: "noconcretada", label: "No concretada", hint: "Una de las partes indicó que no se dio la transferencia o el recojo." },
  { id: "sinventa", label: "Sin venta", hint: "Más corto; no dice por qué." },
  { id: "cancelada", label: "Venta cancelada", hint: "Suena a que alguien la canceló; úsalo solo si VMC registra quién." },
];
export const SIMS: Opt<DealSim>[] = [
  { id: "flujo", label: "Según el flujo", hint: "La publicación cambia cuando aceptas una propuesta del Volkswagen Nivus (o el comprador acepta la tuya)." },
  { id: "aceptada", label: "Aceptada", hint: "Propuesta aceptada: la venta sigue en SubasChat." },
  { id: "vendida", label: "Vendida", hint: "A las 2 semanas, ambas partes confirmaron la venta en SubasChat." },
  { id: "no", label: "No concretada", hint: "A las 2 semanas, una de las partes indicó que no se concretó." },
];

let state = { sim: "flujo" as DealSim, accepted: "subaschat", sold: "vendido", lost: "noconcretada", go: "ambos" as DetailGo };
const subs = new Set<() => void>();
const set = (x: Partial<typeof state>) => { state = { ...state, ...x }; subs.forEach((f) => f()); };
export const useAcuerdo = () => useSyncExternalStore((f) => { subs.add(f); return () => subs.delete(f); }, () => state, () => state);

const labelOf = (opts: Opt<string>[], id: string) => (opts.find((o) => o.id === id) ?? opts[0]).label;
/** Badge de la publicación según el acuerdo (mismo tamaño y forma que BadgeStatus). */
export function DealBadge({ deal }: { deal: Deal }): JSX.Element {
  const a = useAcuerdo();
  const label = deal === "aceptada" ? labelOf(ACCEPTED, a.accepted) : deal === "vendida" ? labelOf(SOLD, a.sold) : labelOf(LOST, a.lost);
  return <span className={`badgestatus ac-badge ac-badge--${deal}`} role="status" aria-label={label}>
    {deal === "vendida" ? <svg width="10" height="10" viewBox="0 0 20 20" aria-hidden><path d="m4.5 10.5 3.5 3.5 7.5-8" fill="none" stroke="currentColor" strokeWidth="2.8" strokeLinecap="round" strokeLinejoin="round" /></svg> : null}
    <span>{label}</span></span>;
}
/** 30/10 (Aaron): la publicación con propuestas y sin acuerdo. Ciclo: En revisión → Publicada → En negociación → SubasChat. */
export function NegotiatingBadge(): JSX.Element {
  return <span className="badgestatus ac-badge ac-badge--negociacion" role="status" aria-label="En negociación"><span>En negociación</span></span>;
}

/** Panel del lab. */
export function AcuerdoLab({ onTry }: { onTry?: () => void }): JSX.Element {
  const a = useAcuerdo();
  const toUrl = (k: string, v: string) => { const u = new URL(location.href); u.searchParams.set(k, v); history.replaceState(null, "", u); };
  // Al simular un estado se abre «Mis publicaciones» y la página baja hasta ella.
  const show = () => { const sec = document.getElementById("sec-publicaciones"); if (!sec) return;
    if (!sec.classList.contains("is-open")) sec.querySelector<HTMLButtonElement>(".fs__toggle")?.click();
    setTimeout(() => scrollTo({ top: sec.getBoundingClientRect().top + scrollY - 16, behavior: "smooth" }), 300); };
  useEffect(() => { const q = new URLSearchParams(location.search), p = q.get("acpub");
    if (SIMS.some((x) => x.id === p)) { set({ sim: p as DealSim }); setTimeout(show, 600); }
    // ?acuerdo=chat: abre directo el chat del acuerdo (vendedor del Nivus) para probar «Ir a detalle».
    if (q.get("acuerdo") === "chat" && onTry) setTimeout(onTry, 800); }, []); // eslint-disable-line react-hooks/exhaustive-deps
  const group = <T extends string>(k: keyof typeof state, title: string, sub: string, opts: Opt<T>[], url?: string, after?: () => void) =>
    <div className="f-sw__g" role="group" aria-label={title}><span className="f-sw__k"><b>{title}</b>{sub ? ` · ${sub}` : ""}</span>
      {opts.map((o) => <button key={o.id} type="button" aria-pressed={a[k] === o.id} title={o.hint} onClick={() => { set({ [k]: o.id } as Partial<typeof state>); if (url) toUrl(url, o.id); after?.(); }}>{o.label}</button>)}
      <small className="f-sw__hint">{opts.find((o) => o.id === a[k])?.hint}</small></div>;
  return <LabPanel title="Acuerdo" store="mg-acuerdo" className="f-sw--acuerdo" side="right" defaultOpen>
    {onTry ? <div className="f-sw__g" role="group" aria-label="Probar ir al detalle" data-acts><span className="f-sw__k"><b>Probar</b> · ir al detalle</span>
      <button type="button" onClick={onTry}>Abrir el chat del acuerdo<small>vendedor · Nivus</small></button>
      <small className="f-sw__hint">Abre el panel con el chat ya habilitado. Ahí haz clic en la foto del auto o en «Ir a detalle».</small></div> : null}
    {group("sim", "Estado", "publicación del Volkswagen Nivus", SIMS, "acpub", show)}
    {group("accepted", "Badge", "propuesta aceptada", ACCEPTED, undefined, show)}
    {group("sold", "Badge", "venta confirmada", SOLD, undefined, show)}
    {group("lost", "Badge", "venta no concretada", LOST, undefined, show)}
  </LabPanel>;
}

// @ts-nocheck — copia literal del motor AVT (mi-garaje-lab/models/avt), no editar. Único cambio: asOfDate? (opcional, solo tipos).
// Copia literal de avt-ai-main.zip · src/App.jsx «AVT Engine» (DEPR … projectForward; rama main, sin commit). 19/10/2026.
// Sin los dos bloques que sobrescriben las tablas desde Firestore (avt_config): el lab usa los valores por defecto del código.
// No editar: si AVT cambia, se vuelve a copiar.
let DEPR = {
  A:[11.84998426,9.620117405,9.024499417,8.183624904,7.675830258,7.152388927,6.781470261,6.576109121,6.353784407,6.161284845,5.992176861,5.841849488,5.706894294,5.584726391,5.473342679],
  B:[16.01966852,9.940116031,9.518819117,8.995756936,8.855476379,8.412727331,7.29849659,7.072619659,6.789384094,6.545646228,6.332705147,6.14435977,5.9760495,5.824331708,5.686550004],
  C:[18.57031588,9.484511435,9.376339915,9.19284781,8.737713135,8.070578195,7.574290436,7.308037809,7.017027286,6.766542767,6.547663542,6.354030588,6.180966283,6.024939063,5.883223492],
  D:[20.00000000,10.51580242,10.35974181,9.953969691,9.292034048,8.691313646,8.185034664,7.783188685,7.445143245,7.155211641,6.902675253,6.679918355,6.481355459,6.302780964,6.140957326],
  E:[21.39620384,10.42649383,10.06357557,9.258043018,8.68712918,8.139424746,7.670781546,7.19854745,6.845461695,6.544316521,6.283326385,6.054160136,5.850735766,5.668493134,5.503935408],
  F:[24.25089464,11.65367853,10.18346423,9.792865782,9.312111672,8.699537571,8.06998414,7.483975955,7.08510777,6.746355575,6.453891038,6.197976825,5.971529315,5.769254412,5.587104469],
  G:[27.90241621,12.70605904,11.05914677,9.74531167,9.543520465,9.195926943,8.638936639,7.900958451,7.463146333,7.092107856,6.772379276,6.49309278,6.24635624,6.026280776,5.828370647],
};
let SEASONAL = {1:0.131,2:0.131,3:0.081,4:0.081,5:0.081,6:-0.051,7:-0.051,8:0.081,9:0.131,10:0.081,11:-0.051,12:-0.051};
let SEG_EXTRA = {
  A:{X:0.0255,Y:0.0175,Z:0.0045},B:{X:0.020,Y:0.012,Z:0.000},
  C:{X:0.015,Y:0.010,Z:0.002},D:{X:0.012,Y:0.008,Z:0.001},
  E:{X:0.010,Y:0.006,Z:0.000},F:{X:0.008,Y:0.004,Z:0.000},
  G:{X:0.005,Y:0.002,Z:0.000},
};
let KM_ADJ_UNDER = 0.0213, KM_ADJ_OVER = -0.0132, AVG_ANNUAL_KM = 15000;
// Category floor — byte-equal mirror of server CLASS_DEFAULTS (functions/index.js cfRunAVT).
// Deliberately NOT Firestore-synced: the server's floor is a hardcoded const too, so keeping
// this a plain const preserves client/server parity for the floor clamp.
const CLASS_FLOORS = { A: 0.08, B: 0.12, C: 0.18, D: 0.22, E: 0.28, F: 0.35, G: 0.40 };
function kmSeg(km) { return km<=30000?"X":km<=80000?"Y":"Z"; }



function runAVT(msrp, cat, year, km, asOfDate?) {
  // ═══ INPUT GUARDS ═══
  if (!msrp || typeof msrp !== 'number' || msrp <= 0 || !isFinite(msrp)) {
    return { baseValue: 0, msrp: msrp || 0, category: cat || 'C', yearsUsed: 0, hist: [] };
  }
  const currentYear = new Date().getFullYear();
  const safeYear = Math.max(2000, Math.min(currentYear, Math.round(year || currentYear)));
  const safeCat = cat && DEPR[cat] ? cat : 'C';
  const safeKm = Math.max(0, Math.min(999999, Math.round(km || 0)));
  const now = asOfDate instanceof Date && !isNaN(asOfDate) ? asOfDate : new Date();

  const fabDate = new Date(safeYear, 0, 1);
  const totalDays = Math.max(1, Math.floor((now - fabDate) / 86400000) + 1);
  const yearsUsed = Math.max(1, now.getFullYear() - safeYear);
  const expected = AVG_ANNUAL_KM * yearsUsed;
  const basePct = safeKm <= expected ? KM_ADJ_UNDER : KM_ADJ_OVER;
  const seg = kmSeg(safeKm);
  const extra = (SEG_EXTRA[safeCat]||SEG_EXTRA.C)[seg]||0;
  const dailyAdj = (basePct + extra) / 365;
  const deprArr = DEPR[safeCat]||DEPR.C;
  let mv = msrp;
  const hist = [];
  for (let d = 1; d < totalDays; d++) {
    const yrIdx = Math.min(Math.floor(d/365), deprArr.length-1);
    const dailyDepr = (deprArr[yrIdx]/100)/365;
    const dt = new Date(fabDate.getTime()+d*86400000);
    const seas = (SEASONAL[dt.getMonth()+1]||0)/365;
    mv = mv * (1 + dailyAdj - dailyDepr*(1-seas));
    // ═══ PER-ITERATION GUARD ═══
    if (!isFinite(mv) || mv < 0) { mv = 0; break; }
    if (d % 30 === 0 || d === totalDays-1) {
      hist.push({ date: dt, value: Math.round(mv/10)*10 });
    }
  }
  // ═══ OUTPUT CLAMPING + CATEGORY FLOOR (mirrors server cfRunAVT) ═══
  // Without the floor, old vehicles in any category decay toward $0. The server clamps to a
  // per-category fraction of MSRP; apply the same here so the (provisional) client preview
  // never shows a number the server would never compute.
  const clamped = Math.round(Math.max(0, Math.min(msrp, mv)) / 10) * 10;
  const floorValue = Math.round(((CLASS_FLOORS[safeCat] ?? CLASS_FLOORS.C) * msrp) / 10) * 10;
  const finalValue = Math.max(clamped, floorValue);
  return { baseValue: finalValue, msrp, category: safeCat, yearsUsed, hist };
}

// Project forward from a given value — organic curve
// Weekly resolution with real seasonal demand cycles + micro-noise + km tracking
function projectForward(currentValue, cat, monthsAhead, currentKm) {
  // ═══ INPUT GUARD ═══
  if (!currentValue || !isFinite(currentValue) || currentValue <= 0) {
    return [{ week: 0, month: 0, date: new Date(), value: 0, km: currentKm || 0, label: "Hoy" }];
  }
  const safeCat = cat && DEPR[cat] ? cat : 'C';
  const deprArr = DEPR[safeCat]||DEPR.C;
  const lastRate = deprArr[deprArr.length-1];
  const dailyDecay = (lastRate / 100) / 365;
  const now = new Date();
  const weeklyKm = AVG_ANNUAL_KM / 52; // ~288 km/week

  // Seeded pseudo-random for deterministic noise
  let seed = Math.round(currentValue) % 9973;
  const seededRandom = () => { seed = (seed * 16807 + 7) % 2147483647; return (seed % 1000) / 1000; };

  // Seasonal demand multipliers — amplified for visible movement
  const DEMAND = {
    1: 0.035, 2: 0.028, 3: 0.012, 4: 0.005, 5: -0.008,
    6: -0.025, 7: -0.030, 8: 0.010, 9: 0.032,
    10: 0.008, 11: -0.022, 12: -0.028
  };

  const totalWeeks = Math.round(monthsAhead * 4.33);
  const rawPoints = [{ week: 0, month: 0, date: now, value: currentValue, km: currentKm || 0 }];

  let v = currentValue;
  for (let w = 1; w <= totalWeeks; w++) {
    const dt = new Date(now.getTime() + w * 7 * 86400000);
    const mo = dt.getMonth() + 1;
    const monthFrac = w / 4.33;
    const weekDepr = dailyDecay * 7;
    const demandEffect = (DEMAND[mo] || 0) / 4.33;
    const noise = (seededRandom() - 0.48) * 0.003;
    const momentum = w > 1
      ? (rawPoints[w-1].value - rawPoints[Math.max(0, w-2)].value) / rawPoints[w-1].value * 0.08
      : 0;
    const weekChange = -weekDepr + demandEffect + noise + momentum;
    v = v * (1 + weekChange);
    if (!isFinite(v) || v < 0) { v = 0; }

    rawPoints.push({
      week: w,
      month: monthFrac,
      date: dt,
      value: Math.round(v / 10) * 10,
      km: Math.round((currentKm || 0) + w * weeklyKm),
    });
  }

  // Post-hoc: assign milestone labels to the closest week for each target
  const targets = [
    { month: 0, label: "Hoy" },
    { month: 1, label: "1M" },
    { month: 3, label: "3M" },
    { month: 6, label: "6M" },
    { month: 12, label: "12M" },
  ];
  // Mark all as null first
  for (const p of rawPoints) p.label = null;
  for (const t of targets) {
    let bestIdx = 0;
    let bestDist = Infinity;
    for (let i = 0; i < rawPoints.length; i++) {
      const dist = Math.abs(rawPoints[i].month - t.month);
      if (dist < bestDist) { bestDist = dist; bestIdx = i; }
    }
    rawPoints[bestIdx].label = t.label;
  }

  return rawPoints;
}

export { runAVT, projectForward, AVG_ANNUAL_KM };

// @ts-nocheck — copia literal del motor AVT (mi-garaje-lab/models/avt), no editar.
// Copia literal de avt-ai-main.zip · src/sellingSignal.js (rama main, sin commit; 9/10/2026). No editar: si AVT cambia, se vuelve a copiar.
// ══════════════════════════════════════════════════════════════
// AVT Dynamic Selling Signal
// ══════════════════════════════════════════════════════════════
//
// Computes a live selling signal based on:
// 1. Current position in seasonal cycle
// 2. Forward projection of value over next 12 months
// 3. Depreciation curve slope (category A-G)
// 4. Optimal sell window identification
//
// Returns a signal object for the UI to render dynamically.
// This runs CLIENT-SIDE using the same constants as avt_core.
// ══════════════════════════════════════════════════════════════

// ── Constants (mirrored from avt_core) ───────────────────────

const SEASONAL_ANNUAL = {
  1: 13.14, 2: 13.14, 3: 8.05, 4: 8.05, 5: 8.05,
  6: -5.08, 7: -5.08, 8: 8.05, 9: 13.14,
  10: 8.05, 11: -5.08, 12: -5.08,
};

const DEPR_TABLES = {
  A: [11.85, 9.62, 9.02, 8.18, 7.68, 7.15, 6.78, 6.58, 6.35, 6.16, 5.99, 5.84, 5.71, 5.58, 5.47],
  B: [16.02, 9.94, 9.52, 9.00, 8.86, 8.41, 7.30, 7.07, 6.79, 6.55, 6.33, 6.14, 5.98, 5.82, 5.69],
  C: [18.57, 9.48, 9.38, 9.19, 8.74, 8.07, 7.57, 7.31, 7.02, 6.77, 6.55, 6.35, 6.18, 6.02, 5.88],
  D: [20.00, 10.52, 10.36, 9.95, 9.29, 8.69, 8.19, 7.78, 7.45, 7.16, 6.90, 6.68, 6.48, 6.30, 6.14],
  E: [21.40, 10.43, 10.06, 9.26, 8.69, 8.14, 7.67, 7.20, 6.85, 6.54, 6.28, 6.05, 5.85, 5.67, 5.50],
  F: [24.25, 11.65, 10.18, 9.79, 9.31, 8.70, 8.07, 7.48, 7.09, 6.75, 6.45, 6.20, 5.97, 5.77, 5.59],
  G: [27.90, 12.71, 11.06, 9.75, 9.54, 9.20, 8.64, 7.90, 7.46, 7.09, 6.77, 6.49, 6.25, 6.03, 5.83],
};

const SEGMENT_EXTRA = {
  A: { X: 0.0255, Y: 0.0175, Z: 0.0045 },
  B: { X: 0.0200, Y: 0.0120, Z: 0.0000 },
  C: { X: 0.0150, Y: 0.0100, Z: 0.0020 },
  D: { X: 0.0120, Y: 0.0080, Z: 0.0010 },
  E: { X: 0.0100, Y: 0.0060, Z: 0.0000 },
  F: { X: 0.0080, Y: 0.0040, Z: 0.0000 },
  G: { X: 0.0050, Y: 0.0020, Z: 0.0000 },
};

const MONTH_NAMES_ES = [
  '', 'Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio',
  'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre',
];

// ── Helpers ──────────────────────────────────────────────────

function kmSegment(km) {
  if (km <= 30000) return 'X';
  if (km <= 80000) return 'Y';
  return 'Z';
}

function getSeasonalFactor(month) {
  return SEASONAL_ANNUAL[month] || 0;
}

function getMonthLabel(month) {
  return MONTH_NAMES_ES[month] || '';
}

// ── Seasonal Momentum ────────────────────────────────────────

function getSeasonalMomentum(currentMonth) {
  const current = getSeasonalFactor(currentMonth);
  const next = getSeasonalFactor(currentMonth === 12 ? 1 : currentMonth + 1);
  const nextNext = getSeasonalFactor(currentMonth >= 11 ? currentMonth - 10 : currentMonth + 2);

  const trend = next - current;
  const acceleration = nextNext - next;

  return { current, next, nextNext, trend, acceleration };
}

// ── Forward Value Projection ─────────────────────────────────

function projectForward(currentValue, category, yearOfFab, km, consultDate) {
  if (!currentValue || !isFinite(currentValue) || currentValue <= 0) return [];
  const cat = (category || 'C').toUpperCase();
  const deprTable = DEPR_TABLES[cat] || DEPR_TABLES.A;
  const seg = kmSegment(Math.max(0, km || 0));
  const yearsUsed = Math.max(1, consultDate.getFullYear() - (yearOfFab || consultDate.getFullYear()));
  const expectedKm = 15000 * Math.max(yearsUsed, 1);
  const basePct = km <= expectedKm ? 0.0213 : -0.0132;
  const extraPct = (SEGMENT_EXTRA[cat] || SEGMENT_EXTRA.A)[seg] || 0;
  const dailyKmAdj = (basePct + extraPct) / 365;

  const projections = [];
  let value = currentValue;

  for (let day = 0; day < 365; day++) {
    const projDate = new Date(consultDate);
    projDate.setDate(projDate.getDate() + day);
    const month = projDate.getMonth() + 1;
    const yearIndex = Math.min(
      consultDate.getFullYear() - yearOfFab + Math.floor(day / 365),
      deprTable.length - 1
    );

    const dailyDepr = (deprTable[yearIndex] / 100) / 365;
    const seasonal = (getSeasonalFactor(month) / 100) / 365;
    const effectiveDepr = dailyDepr * (1 - seasonal);

    value = value * (1 + dailyKmAdj - effectiveDepr);
    if (!isFinite(value) || value < 0) { value = 0; }

    if (day === 0 || projDate.getDate() === 1) {
      projections.push({
        date: new Date(projDate),
        month,
        monthLabel: getMonthLabel(month),
        value: Math.round(value / 10) * 10,
        dayIndex: day,
        dailyLoss: currentValue > 0 ? ((currentValue - value) / day || 0) : 0,
        totalLoss: Math.round(currentValue - value),
        totalLossPct: currentValue > 0
          ? Math.round(((currentValue - value) / currentValue) * 1000) / 10
          : 0,
        seasonalFactor: getSeasonalFactor(month),
      });
    }
  }

  return projections;
}

// ── Find Optimal Sell Windows ────────────────────────────────

function findSellWindows(projections) {
  if (projections.length < 3) return [];

  const scored = projections.slice(1).map((p) => {
    const seasonalBoost = p.seasonalFactor > 0 ? p.seasonalFactor : 0;
    const dailyLossRate = p.dayIndex > 0 ? p.totalLoss / p.dayIndex : 0;
    const score = seasonalBoost * 10 - dailyLossRate;

    return {
      ...p,
      score,
      dailyLossRate: Math.round(dailyLossRate * 100) / 100,
      isHighDemand: p.seasonalFactor > 8,
      isPeakDemand: p.seasonalFactor > 12,
      isLowDemand: p.seasonalFactor < 0,
    };
  });

  const ranked = [...scored].sort((a, b) => b.score - a.score);
  return ranked;
}

// ── Compute Sell Signal Level ────────────────────────────────

function computeSignalLevel(momentum) {
  const { current, trend } = momentum;

  if (current >= 13 && trend < -5) return 5;
  if (current >= 8 && trend <= 0) return 4;
  if (current >= 8 && trend > 0) return 3;
  if (current < 0 && trend > 0) return 2;
  return 1;
}

// ── Signal Labels ────────────────────────────────────────────

const SIGNAL_LABELS = {
  5: { label: 'Vender ahora', sublabel: 'Demanda máxima. Ventana cerrándose.', color: '#FF4444', urgency: 'critical' },
  4: { label: 'Buen momento', sublabel: 'Demanda alta. Condiciones favorables.', color: '#FF8800', urgency: 'high' },
  3: { label: 'Momento favorable', sublabel: 'Demanda activa. Mercado estable.', color: '#FFBB00', urgency: 'moderate' },
  2: { label: 'Esperar', sublabel: 'Demanda baja, pero mejorando.', color: '#44AAFF', urgency: 'low' },
  1: { label: 'No es momento', sublabel: 'Demanda baja. Mejor esperar.', color: '#8899AA', urgency: 'none' },
};

// ── Dynamic Copy Generator ───────────────────────────────────

function generateDynamicCopy(level, momentum, currentMonth, dailyLoss, nextPeak, daysUntilPeak) {
  const monthName = getMonthLabel(currentMonth);
  const SELL_URL = 'https://www.subascars.com/como-vender-mi-auto-en-peru';

  switch (level) {
    case 5:
      return {
        headline: `${monthName}: ventana de venta cerrándose`,
        body: `Estás en el pico de demanda estacional. Tu auto pierde $${dailyLoss}/día. ` +
              `Después de este mes, la demanda cae y tu valor baja más rápido.`,
        ctaText: 'Vender ahora →',
        ctaUrl: SELL_URL,
      };
    case 4:
      return {
        headline: `${monthName}: buen momento para vender`,
        body: `La demanda del mercado está alta (${momentum.current > 0 ? '+' : ''}${momentum.current}%). ` +
              `Cada día que pasa pierdes ~$${dailyLoss} en valor.`,
        ctaText: 'Vender mi auto →',
        ctaUrl: SELL_URL,
      };
    case 3:
      return {
        headline: `Mercado activo en ${monthName}`,
        body: `Condiciones favorables con demanda de +${momentum.current}%. ` +
              `Si planeas vender este año, este es un momento razonable.`,
        ctaText: 'Ver opciones de venta →',
        ctaUrl: SELL_URL,
      };
    case 2:
      return {
        headline: `${monthName}: demanda recuperándose`,
        body: `El mercado está en ciclo bajo pero mejorando. ` +
              `La próxima ventana fuerte es ${nextPeak} (en ${daysUntilPeak} días).`,
        ctaText: `Preparar venta para ${nextPeak} →`,
        ctaUrl: SELL_URL,
      };
    case 1:
      return {
        headline: `${monthName}: mejor esperar`,
        body: `Demanda estacional baja (${momentum.current}%). ` +
              `Vender ahora significa menor precio. Próximo pico: ${nextPeak} en ${daysUntilPeak} días.`,
        ctaText: 'Activar alerta de venta →',
        ctaUrl: SELL_URL,
      };
    default:
      return {
        headline: 'Señal de mercado',
        body: 'Calculando condiciones de mercado...',
        ctaText: 'Vender mi auto →',
        ctaUrl: SELL_URL,
      };
  }
}

// ══════════════════════════════════════════════════════════════
// MAIN EXPORT: computeSellingSignal()
// ══════════════════════════════════════════════════════════════

export function computeSellingSignal(currentValue, category, yearOfFab, km, consultDate = new Date(), marketContext = null) {
  // ═══ INPUT GUARD ═══
  if (!currentValue || !isFinite(currentValue) || currentValue <= 0) {
    const neutral = SIGNAL_LABELS[1];
    return {
      signal: { level: 1, ...neutral },
      seasonal: { currentMonth: '', currentFactor: 0, currentFactorLabel: '0% demanda', trend: 'estable', trendArrow: '→', nextMonth: '', nextFactor: 0 },
      timing: { bestMonths: [], worstMonths: [], nextPeakMonth: null, daysUntilPeak: 0, dailyValueLoss: 0, monthlyValueLoss: 0 },
      projection: { currentValue: 0, value30d: 0, value90d: 0, value180d: 0, value365d: 0, loss30d: 0, loss90d: 0, loss180d: 0, loss365d: 0, monthlyProjections: [] },
      copy: { headline: '', body: '', ctaText: '', ctaUrl: '' },
    };
  }
  const safeDate = consultDate instanceof Date && !isNaN(consultDate) ? consultDate : new Date();
  const currentMonth = safeDate.getMonth() + 1;
  const momentum = getSeasonalMomentum(currentMonth);
  const projections = projectForward(currentValue, category, yearOfFab, km, safeDate);
  const sellWindows = findSellWindows(projections);

  // Adjust signal level using live market data when available
  let signalLevel = computeSignalLevel(momentum);
  if (marketContext) {
    const trend = marketContext.trend;
    const demand = marketContext.demand;
    // Boost signal if live demand is high
    if (demand && demand.buyer_searches_7d >= 5 && signalLevel < 4) signalLevel = Math.min(signalLevel + 1, 4);
    // Boost signal if price trend is rising
    if (trend && trend.change_30d_pct > 3 && signalLevel < 4) signalLevel = Math.min(signalLevel + 1, 4);
    // Lower signal if price is crashing and demand is zero
    if (trend && trend.change_30d_pct < -5 && (!demand || demand.buyer_searches_7d === 0) && signalLevel > 1) signalLevel = Math.max(signalLevel - 1, 1);
  }
  const signalInfo = SIGNAL_LABELS[signalLevel];

  // Seasonal info
  const trendDirection = momentum.trend > 2 ? 'subiendo' : momentum.trend < -2 ? 'bajando' : 'estable';
  const trendArrow = momentum.trend > 2 ? '↗' : momentum.trend < -2 ? '↘' : '→';
  const nextMonth = currentMonth === 12 ? 1 : currentMonth + 1;

  // Timing info
  const bestMonths = sellWindows.slice(0, 3).map(w => ({
    monthLabel: w.monthLabel,
    value: w.value,
    totalLoss: w.totalLoss,
    totalLossPct: w.totalLossPct,
    isPeakDemand: w.isPeakDemand,
    isHighDemand: w.isHighDemand,
  }));

  const worstMonths = sellWindows.slice(-2).map(w => ({
    monthLabel: w.monthLabel,
    totalLoss: w.totalLoss,
    totalLossPct: w.totalLossPct,
  }));

  // Find next peak month (>12% seasonal)
  const peakMonths = [1, 2, 9];
  let nextPeakMonth = null;
  let daysUntilPeak = 0;
  for (const pm of peakMonths) {
    const pmDate = new Date(safeDate.getFullYear(), pm - 1, 1);
    if (pmDate <= safeDate) pmDate.setFullYear(pmDate.getFullYear() + 1);
    const diff = Math.ceil((pmDate - safeDate) / (1000 * 60 * 60 * 24));
    if (!nextPeakMonth || diff < daysUntilPeak) {
      nextPeakMonth = getMonthLabel(pm);
      daysUntilPeak = diff;
    }
  }

  // Daily/monthly loss at current rate
  const proj30 = projections.find(p => p.dayIndex >= 28) || projections[projections.length - 1];
  const dailyValueLoss = proj30 ? Math.round(proj30.totalLoss / proj30.dayIndex) : 0;
  const monthlyValueLoss = dailyValueLoss * 30;

  // Projection snapshots
  const findNearest = (targetDay) => {
    let closest = projections[0];
    for (const p of projections) {
      if (Math.abs(p.dayIndex - targetDay) < Math.abs(closest.dayIndex - targetDay)) closest = p;
    }
    return closest;
  };

  const p30 = findNearest(30);
  const p90 = findNearest(90);
  const p180 = findNearest(180);
  const p365 = findNearest(365);

  // Dynamic copy
  const copy = generateDynamicCopy(signalLevel, momentum, currentMonth, dailyValueLoss, nextPeakMonth, daysUntilPeak);

  return {
    signal: {
      level: signalLevel,
      ...signalInfo,
    },
    seasonal: {
      currentMonth: getMonthLabel(currentMonth),
      currentFactor: momentum.current,
      currentFactorLabel: `${momentum.current > 0 ? '+' : ''}${momentum.current}% demanda`,
      trend: trendDirection,
      trendArrow,
      nextMonth: getMonthLabel(nextMonth),
      nextFactor: momentum.next,
    },
    timing: {
      bestMonths,
      worstMonths,
      nextPeakMonth,
      daysUntilPeak,
      dailyValueLoss,
      monthlyValueLoss,
    },
    projection: {
      currentValue,
      value30d: p30?.value || currentValue,
      value90d: p90?.value || currentValue,
      value180d: p180?.value || currentValue,
      value365d: p365?.value || currentValue,
      loss30d: p30?.totalLoss || 0,
      loss90d: p90?.totalLoss || 0,
      loss180d: p180?.totalLoss || 0,
      loss365d: p365?.totalLoss || 0,
      monthlyProjections: projections,
    },
    copy,
  };
}

