  // Tamaños del index (vmc-index-lab, medidos a 1440 y 390 px de ancho): solo para las piezas 14–19.
  { f: "ixhero", w: 600, h: 300, where: "Hero del index", solo: "hero" },
  { f: "ixheroM", w: 366, h: 300, where: "Hero del index · móvil", solo: "hero" },
  { f: "ixcamp", w: 916, h: 204, where: "Banner secundario del index", solo: "camp" },
  { f: "ixcampM", w: 366, h: 340, where: "Banner secundario · móvil", solo: "camp" },
] as { f: string; w: number; h: number; where: string; solo?: string }[];
export type Fmt = (typeof FORMATOS)[number];
/** Vistas del banner secundario del index (BANNER_VIEWS de HomeIndexBlock.tsx); h = alto en el móvil (366 px), medido. */
export const VISTAS = [
  { id: "fondo", label: "Foto de fondo", h: 340 }, { id: "panel", label: "Panel · Arco", h: 550 }, { id: "recorte", label: "A · Recorte", h: 566 },
  { id: "forma", label: "B · Forma", h: 570 }, { id: "hero", label: "C · Protagonista", h: 576 }, { id: "glass", label: "D · Anillos", h: 562 }, { id: "claro", label: "E · Vidrio claro", h: 560 },
];
export const formatosDe = (p: Pieza) => FORMATOS.filter((x) => x.solo ? x.solo === (p.ix ?? p.src) : !p.ix);

/** Cada imagen descargable de una pieza (versión vigente): la plantilla, su tamaño y el nombre del JPG en public/banners/descargas/
 *  (`<file>.jpg` a 1x y `<file>@2x.jpg` a 2x). Las genera scripts/render-banners.mjs; correrlo de nuevo si cambia una plantilla. */
export type Archivo = { key: string; label: string; w: number; h: number; url: string; file: string };
export const archivosDe = (p: Pieza): Archivo[] => {
  const base = `${p.src}-${p.id}`;
  if (p.ix === "camp") return VISTAS.flatMap((vs) => {
    const url = `/mi-garaje/banners/index-campana.html?v=${p.id}&vista=${vs.id}`;
    return [{ key: `${vs.id}`, label: `${vs.label} · escritorio`, w: 916, h: 204, url, file: `${base}-${vs.id}` },
      { key: `${vs.id}M`, label: `${vs.label} · móvil`, w: 366, h: vs.h, url, file: `${base}-${vs.id}-movil` }];
  });
  return formatosDe(p).map((fm) => ({ key: fm.f, label: fm.where, w: fm.w, h: fm.h, url: bannerSrc(p, fm.f), file: `${base}-${fm.f}` }));
};

/* Mi billetera · letras (22/10, comentario de Silvana): «Mi billetera» y «Transacciones» se notaban poco sobre el degradado.
