.g--vmc.g-page:is([data-billetera="subrayado"], [data-billetera="brillo"]) .f-wallet header a { text-decoration:underline; text-underline-offset:3px; text-decoration-thickness:1px; }
/* Hover: blanco y subrayado (en las blancas el color ya no puede subir). */
