/* ── SubasCoins: el signo >S< delante del monto (Concorde) ───────────── */
.f-wallet__sign { margin-right:5px; font-size:.62em; font-weight:700; letter-spacing:0; color:#E8DEFF; vertical-align:.1em; }


/* ── Tarjeta ─────────────────────────────────────────────────── */
/* Las variantes de tarjeta llevan el título fuerte; Transacciones según cada una. */
.g--vmc.g-page:is([data-billetera="esmerilado"], [data-billetera="halo"], [data-billetera="brillo"], [data-billetera="primary"], [data-billetera="live"], [data-billetera="pildora"]) .f-wallet h2 { font-size:1.125rem; font-weight:800; }
.g--vmc.g-page:is([data-billetera="halo"], [data-billetera="brillo"], [data-billetera="primary"], [data-billetera="live"]) .f-wallet header a { color:#fff; font-size:.8125rem; font-weight:700; }

/* Píldora (y Borde esmerilado): Transacciones como botón de vidrio. */
.g--vmc.g-page:is([data-billetera="pildora"], [data-billetera="esmerilado"]) .f-wallet header a { gap:4px; min-height:28px; padding:0 8px 0 12px; border-radius:9999px; background:rgba(255,255,255,.12);
  box-shadow:inset 0 0 0 1px rgba(255,255,255,.34); color:#fff; font-size:.8125rem; font-weight:700; transition:background .15s; }
.g--vmc.g-page:is([data-billetera="pildora"], [data-billetera="esmerilado"]) .f-wallet header a:hover { background:rgba(255,255,255,.22); text-decoration:none; }
.g--vmc.g-page[data-billetera="esmerilado"] .f-wallet header a { box-shadow:inset 0 0 0 1px rgba(207,186,255,.75), 0 0 12px rgba(174,142,255,.35); }

/* Borde esmerilado: marco degradado (el del botón secundario) y halo violeta alrededor. */
.g--vmc.g-page[data-billetera="esmerilado"] .f-src .f-wallet { box-shadow:0 0 0 4px rgba(174,142,255,.16), 0 0 28px rgba(132,96,229,.45), 0 12px 32px rgba(34,0,92,.28); }
.g--vmc.g-page[data-billetera="esmerilado"] .f-wallet::after { content:""; position:absolute; inset:0; z-index:1; border-radius:inherit; padding:1.5px; pointer-events:none;
  background:linear-gradient(135deg, #CFBAFF 0%, #fff 35%, #AE8EFF 65%, #CFBAFF 100%);
  -webkit-mask:linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0); -webkit-mask-composite:xor; mask:linear-gradient(#000 0 0) content-box exclude, linear-gradient(#000 0 0); }

/* Halo: una luz recorre el borde de la billetera sin parar (conic-gradient que gira, enmascarado a un marco de 2 px), con un
   resplandor que la sigue. El barrido diagonal anterior (.f-wallet__shine) queda apagado. */
.f-wallet__shine, .f-wallet__beam { display:none; }
@property --fw-ang { syntax:"<angle>"; inherits:false; initial-value:0deg; }
.g--vmc.g-page[data-billetera="halo"] .f-wallet__beam { display:block; position:absolute; inset:0; z-index:2; border-radius:inherit; padding:2.5px; pointer-events:none;
  background:conic-gradient(from var(--fw-ang), transparent 0deg, transparent 200deg, rgba(174,142,255,.55) 270deg, #CFBAFF 315deg, #fff 345deg, #FBC47D 356deg, transparent 360deg);
  -webkit-mask:linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0); -webkit-mask-composite:xor; mask:linear-gradient(#000 0 0) content-box exclude, linear-gradient(#000 0 0);
  animation:f-wallet-beam 4s linear infinite; }
.g--vmc.g-page[data-billetera="halo"] .f-src .f-wallet { box-shadow:0 0 0 1px rgba(207,186,255,.3), 0 0 26px rgba(132,96,229,.4), 0 12px 32px rgba(34,0,92,.28); }
@keyframes f-wallet-beam { to { --fw-ang:360deg; } }
/* En producción, con prefers-reduced-motion: reduce, la luz no debe girar. En el lab no se aplica: Windows con las
   animaciones apagadas lo activa en Chrome y el halo se vería quieto. */

/* Fondo primary (degradado del botón primary) y Fondo live (naranja de EN VIVO), con el borde degradado de cada uno. */
.g--vmc.g-page:is([data-billetera="primary"], [data-billetera="live"]) .f-src .f-wallet { border:1.5px solid transparent; background-origin:padding-box, border-box; background-clip:padding-box, border-box; }
.g--vmc.g-page[data-billetera="primary"] .f-src .f-wallet { background-image:linear-gradient(135deg, #ED8936 0%, #C76F5E 34%, #8460E5 72%, #5A35C2 100%), linear-gradient(135deg, #fff 0%, #FBC47D 25%, #AE8EFF 75%, #fff 100%);
