.g--vmc.g-page[data-billetera="live"] .f-src .f-wallet { background-image:linear-gradient(135deg, #F4AC59 0%, #ED8936 40%, #B25614 100%), linear-gradient(135deg, #FBC47D 0%, rgba(255,255,255,.45) 40%, #D46E20 75%, #FBC47D 100%);
  box-shadow:0 12px 32px rgba(237,137,54,.4); }
.g--vmc.g-page:is([data-billetera="primary"], [data-billetera="live"]) .f-wallet { text-shadow:0 1px 2px rgba(60,20,0,.22); }
