.g--vmc.g-page:is([data-billetera="primary"], [data-billetera="live"]) .f-wallet__bal div + div { border-left-color:rgba(255,255,255,.35); }
.g--vmc.g-page:is([data-billetera="primary"], [data-billetera="live"]) .f-wallet .psec { text-shadow:rgba(0,0,0,.3) 0 1px 3px; }

/* Panel más ancho: tres grupos sin que los botones se partan en muchas filas. */
