.fl-check { display:flex; align-items:center; gap:8px; flex-wrap:wrap; padding:10px 12px; border-radius:12px; font-size:.875rem; color:var(--ink); cursor:pointer; box-shadow:inset 0 0 0 1px #E1E3E2; }
.fl-check.is-on { background:#FBF9FF; box-shadow:inset 0 0 0 1px #CFBAFF; }
.fl-check small { flex-basis:100%; padding-left:24px; font-size:.6875rem; font-weight:700; color:#006466; }
.fl-inline { all:unset; cursor:pointer; font-weight:700; color:#5A35C2; text-decoration:underline; text-underline-offset:2px; }
.fl-inline:focus-visible { outline:2px solid #8460E5; outline-offset:2px; }
@media (max-width:767px) { .fl-grid--3, .fl-checks { grid-template-columns:1fr; } }
/* Vista previa = ficha real de la oferta (AuctionStatus + CardViewer + DetailCard) */
.fl-prev { display:grid; gap:16px; }
.fl-prev__bar { position:sticky; top:8px; z-index:3; display:flex; justify-content:space-between; align-items:center; gap:16px; flex-wrap:wrap; padding:16px 20px; border-radius:20px; background:#fff; box-shadow:0 10px 30px rgba(34,0,92,.12); }
.fl-prev__tag { display:inline-block; padding:2px 10px; border-radius:9999px; font-size:.6875rem; font-weight:800; text-transform:uppercase; letter-spacing:.04em; color:#fff; background:linear-gradient(120deg,#ED8936,#D46E20); }
.fl-prev__bar h1 { margin:6px 0 0; font-size:1.25rem; font-weight:800; color:var(--ink); }
.fl-prev__bar p { margin:2px 0 0; font-size:.8125rem; color:var(--muted); }
.fl-prev__actions { display:flex; align-items:center; gap:12px; }
.fl-prev__page { display:grid; grid-template-columns:443px 1fr; gap:20px; align-items:start; padding:20px; border-radius:24px; background:#F7F7FB; box-shadow:inset 0 0 0 1px var(--line); }
.fl-prev__main { display:grid; grid-template-columns:minmax(0,1fr); gap:12px; min-width:0; } /* pista explícita: la implícita se estira a los 443px fijos de Concorde */
.fl-prev__info { display:grid; gap:10px; padding:16px 18px; border-radius:16px; background:#fff; box-shadow:0 1px 3px rgba(34,0,92,.05); }
.fl-prev__info h2 { margin:0; font-size:.8125rem; font-weight:800; text-transform:uppercase; letter-spacing:.04em; color:var(--ink); }
.fl-prev__list { margin:0; font-size:.8125rem; line-height:1.5; color:color-mix(in srgb,#191C1C 82%,#fff); }
.fl-prev__side { display:grid; gap:12px; justify-items:center; align-content:start; }
.fl-prev__pills { display:flex; gap:8px; flex-wrap:wrap; justify-content:center; }
.fl { max-width:1000px; }
@media (max-width:900px) { .fl-prev__page { grid-template-columns:1fr; justify-items:center; padding:12px; } .fl-prev__status, .fl-prev__viewer { max-width:100%; } }

/* Revisión mobile 9/10: sin desborde en la vista previa, CTA en una línea, nota larga bajo el subtítulo, checks en 2 columnas. */
.fl-stepper__label { white-space:nowrap; }
/* El texto ocupa el resto de la fila (base 0): no salta debajo de la casilla. */

@media (max-width:767px) {
  .fl-sub .fl-sub__note { display:block; margin:2px 0 0; }
  .fl-checks { grid-template-columns:1fr 1fr; }
  .fl-prev__bar { padding:12px 16px; gap:10px; }
  .fl-prev__tag, .fl-prev__bar p { display:none; }
  .fl-prev__bar h1 { margin:0; font-size:1.0625rem; }
  .fl-prev__bar > div:first-child, .fl-prev__actions { width:100%; }
  .fl-prev__actions > :last-child { flex:1; white-space:nowrap; }
}

/* ── Mejoras UX 9/10 (07-mejoras-ux-valorizar-publicar.md) ─────────────── */
/* Error: borde #EF4444 como el Input de Concorde; texto #DC2626 para contraste AA. */
.fl-err { font-size:.75rem; font-weight:600; color:#DC2626; }
.fl-select.is-error, .fl-textarea.is-error { border-color:#EF4444; }
.fl-card h1:focus, .fl-result h1:focus, .fl-done h1:focus, .fl-prev h1:focus, .fl-sub:focus { outline:none; }

/* Borrador */
.fl-resume { display:flex; justify-content:space-between; align-items:center; gap:16px; flex-wrap:wrap; padding:14px 16px; border-radius:16px; background:#F5F0FF; box-shadow:inset 0 0 0 1px #D9CCFA; }
.fl-resume > div:first-child { display:grid; gap:2px; } .fl-resume b { color:var(--ink); } .fl-resume span { font-size:.8125rem; color:var(--muted); }
.fl-resume__btns { display:flex; align-items:center; gap:16px; }

/* Expectativas al inicio */
.fl-expect { list-style:none; margin:16px 0 0; padding:0; display:grid; gap:10px; }
.fl-expect li { display:flex; align-items:flex-start; gap:8px; font-size:.875rem; font-weight:600; color:#5A35C2; } .fl-expect svg { flex:none; margin-top:1px; }

/* Detalles: mecánica necesaria para publicar */
.fl-need { margin-left:8px; padding:2px 8px; border-radius:9999px; font-size:.625rem; letter-spacing:.02em; color:#9A4A0F; background:#FFF1E3; }
.fl-skipnote { display:flex; gap:6px; align-items:flex-start; margin:-4px 0 0; }

/* Resultado: qué puede cambiar el valor */

/* Resumen de errores (GOV.UK) */
.fl-errsum { padding:14px 16px; border-radius:16px; border-left:4px solid #EF4444; background:#FEF2F2; outline:none; }
.fl-errsum:focus { box-shadow:0 0 0 2px #EF4444; }
.fl-errsum b { color:#991B1B; } .fl-errsum ul { margin:6px 0 0; padding-left:18px; display:grid; gap:4px; } .fl-errsum .fl-inline { color:#B91C1C; }

/* Fotos guiadas */
.fl-photos.is-error .fl-shot:not(.is-full) { border-color:#EF4444; }
.fl-shots { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:12px; margin-top:8px; }
.fl-shot { position:relative; display:grid; place-items:center; align-content:center; gap:6px; aspect-ratio:4/3; margin:0; padding:8px; border-radius:14px; border:2px dashed #CDBDF5; background:#FBF9FF; color:#5A35C2; font-size:.75rem; font-weight:700; text-align:center; cursor:pointer; overflow:hidden; }
.fl-shot:hover, .fl-shot:focus-within { border-color:#8460E5; background:#F5F0FF; }
.fl-shot:focus-within { outline:2px solid #8460E5; outline-offset:2px; }
.fl-shot.is-full { padding:0; border:0; cursor:default; }
.fl-shot.is-full img { position:absolute; inset:0; width:100%; height:100%; object-fit:cover; }
.fl-shot.is-cover { box-shadow:0 0 0 3px #ED8936; }
.fl-shot figcaption { position:absolute; inset:auto 0 0 0; display:flex; justify-content:space-between; align-items:center; gap:4px; padding:18px 8px 6px; font-size:.6875rem; color:#fff; background:linear-gradient(transparent,rgba(16,0,48,.75)); }
.fl-shot figcaption button { all:unset; cursor:pointer; min-height:24px; padding:0 8px; border-radius:9999px; font-weight:700; background:rgba(255,255,255,.22); }
.fl-shot figcaption button:focus-visible { outline:2px solid #fff; }
.fl-shot__cover { padding:2px 8px; border-radius:9999px; font-weight:800; background:#ED8936; }
.fl-shot__x { all:unset; cursor:pointer; position:absolute; top:6px; right:6px; display:grid; place-items:center; width:28px; height:28px; border-radius:9999px; font-size:1.125rem; line-height:1; color:#fff; background:rgba(16,0,48,.6); }
.fl-shot__x:focus-visible { outline:2px solid #fff; }
.fl-shot__plus { font-size:1.5rem; line-height:1; }
.fl-shot--more { border-style:solid; border-color:#E1E3E2; color:var(--muted); background:#fff; }

/* Expectativa: semáforo frente al rango AVT */
.fl-gauge { display:flex; gap:6px; align-items:center; font-size:.75rem; font-weight:700; }
.fl-gauge::before { content:""; flex:none; width:8px; height:8px; border-radius:9999px; background:currentColor; }
.fl-gauge--ok { color:#006466; } .fl-gauge--high, .fl-gauge--low { color:#9A4A0F; }

.fl-terms { display:grid; gap:4px; }

/* Barra fija con lo que falta */
.fl-foot--sticky { position:sticky; bottom:0; z-index:2; margin:0 -28px -28px; padding:14px 28px; border-radius:0 0 24px 24px; background:rgba(255,255,255,.96); backdrop-filter:blur(6px); box-shadow:0 -8px 20px -12px rgba(34,0,92,.25); }
.fl-left { all:unset; cursor:pointer; display:inline-flex; align-items:center; gap:6px; font-size:.8125rem; font-weight:700; color:#9A4A0F; white-space:nowrap; }
.fl-left:focus-visible { outline:2px solid #8460E5; outline-offset:2px; border-radius:4px; }
.fl-left.is-ok { cursor:default; color:#006466; }

/* Vista previa: «Cambiar» por bloque */
.fl-change { all:unset; cursor:pointer; justify-self:end; min-height:24px; font-size:.8125rem; font-weight:700; color:#5A35C2; text-decoration:underline; text-underline-offset:2px; }
.fl-change:focus-visible { outline:2px solid #8460E5; outline-offset:2px; border-radius:4px; }
.fl-prev__h { display:flex; justify-content:space-between; align-items:center; gap:12px; }

@media (max-width:767px) {
  .fl-shots { grid-template-columns:repeat(2,minmax(0,1fr)); }
  .fl-foot--sticky { margin:0 -16px -20px; padding:12px 16px; border-radius:0 0 20px 20px; }
  .fl-resume__btns { width:100%; justify-content:space-between; }
}
.fl-prev__side .fl-change { justify-self:center; }
.fl-need, .fl-typical { white-space:nowrap; }

/* Resultado a 390 px: rango y confianza apilados, mismo ancho */
@media (max-width:480px) { .fl .vz-pair { grid-template-columns:1fr; } }

/* ── Resultado completo AVT (recompra · Subastop · proyección · señal · momento óptimo · factores) ── */
.fl-two dd { font-size:1.375rem; }
.fl-avt { display:grid; grid-template-columns:1fr 1fr; gap:12px; }
.fl-avt__card { display:grid; gap:8px; align-content:start; padding:16px 18px; border-radius:16px; background:#fff; box-shadow:inset 0 0 0 1px var(--line); font-size:.8125rem; color:var(--ink); }
.fl-avt__card h2 { margin:0; font-size:.9375rem; font-weight:800; color:var(--ink); }
.fl-avt__card h2 small { margin-left:8px; font-weight:500; font-size:.75rem; color:var(--muted); }
.fl-avt__card p { margin:0; }
.fl-spark { width:100%; height:56px; color:#8460E5; }
.fl-miles { margin:0; display:grid; grid-template-columns:repeat(4,1fr); gap:6px; }
.fl-miles div { display:grid; gap:1px; padding:8px; border-radius:10px; background:#F5F0FF; text-align:center; }
.fl-miles dt { font-size:.6875rem; font-weight:700; color:#5A35C2; }
.fl-miles dd { margin:0; font-weight:800; font-variant-numeric:tabular-nums; }
.fl-miles small { font-size:.6875rem; color:#C0392B; }
.fl-sig { display:flex; align-items:center; gap:8px; font-size:.9375rem; }
.fl-muted { color:var(--muted); }
.fl-loss { font-weight:700; color:#B25614; }
.fl-pills { display:flex; flex-wrap:wrap; align-items:center; gap:6px; }
.fl-pills span { font-size:.6875rem; text-transform:uppercase; letter-spacing:.05em; color:var(--muted); }
.fl-pills em { font-style:normal; font-weight:700; font-size:.75rem; padding:3px 10px; border-radius:999px; background:#F5F0FF; color:#5A35C2; }
.fl-season { list-style:none; margin:0 0 8px; padding:0; height:96px; display:grid; grid-template-columns:repeat(12,1fr); gap:4px; align-items:end; }
.fl-season li { height:100%; display:grid; grid-template-rows:1fr auto; align-items:end; justify-items:center; gap:4px; }
.fl-season i { width:100%; border-radius:4px 4px 0 0; background:#CFBAFF; }
.fl-season li.is-neg i { background:#E1E3E2; }
.fl-season li.is-now i { background:#EE7A1F; }
.fl-season span { font-size:.625rem; color:var(--muted); }
.fl-season li.is-now span { font-weight:800; color:var(--ink); }
@media (max-width:720px) { .fl-avt { grid-template-columns:1fr; } .fl-miles { grid-template-columns:repeat(2,1fr); } }

/* ── Valorizar en una página (Fernando): detalles dentro del mismo formulario y resultado debajo, sin foto ── */
.fl-result--ds { margin-top:24px; scroll-margin-top:16px; }
.fl-result--ds .fl-decide { position:sticky; bottom:12px; z-index:2; } /* Guardar · Publicar siempre a mano mientras se lee el resultado, también en mobile */
/* Precio de lista: edición dentro de la misma banda (13/10). */
.fl-msrp { flex-wrap:wrap; }
.fl-msrp__input { flex:1; min-width:160px; }
.fl-msrp__note { flex-basis:100%; margin:0; }

/* Mobile: barra sticky compacta, solo los dos botones en una fila (~68 px). La pregunta se oculta: los botones ya dicen la acción. */
@media (max-width:767px) {
  .fl-result--ds .fl-decide { bottom:8px; padding:10px; gap:0; border-radius:20px; box-shadow:0 -2px 0 rgba(34,0,92,.04), 0 8px 28px rgba(34,0,92,.22); }
  .fl-result--ds .fl-decide > div:first-child { display:none; }
  .fl-result--ds .fl-decide__btns { grid-template-columns:1fr 1.4fr; gap:8px; }
  .fl-result--ds .fl-decide__btns > :last-child { order:0; }
}
@media (max-width:767px) { .fl-result--ds .fl-decide__btns > * { white-space:nowrap; font-size:.9375rem; } }
@media (max-width:767px) { .fl-result--ds .fl-decide__btns { grid-template-columns:auto 1fr; } .fl-result--ds .fl-decide__btns > .fl-save { padding-inline:16px; } }

/* ══ Formularios (13/10): una columna (Baymard), ancho según el dato, rótulos en tipo oración 14/600 (Concorde label-md),
   campos a 16 px para que iOS no haga zoom y áreas táctiles de 44 px en los botones chicos. La dirección sigue en 3 columnas (excepción válida). */
.fl-grid { grid-template-columns:minmax(0,480px); }
.fl-grid.fl-grid--3 { grid-template-columns:repeat(3,minmax(0,1fr)); }
.fl-grid > .fl-msrp { grid-column:1 / -1; }
#f-placa { max-width:200px; }
.fl-label { font-size:.875rem; font-weight:600; letter-spacing:0; text-transform:none; }
.fl-select select, .fl-textarea { font-size:1rem; }
.fl-inline, .fl-ai, .fl-left, .fl-shot__x, .fl-shot figcaption button, .fl-demo { position:relative; }
.fl-inline::after, .fl-ai::after, .fl-left::after, .fl-shot figcaption button::after, .fl-demo::after { content:""; position:absolute; left:-4px; right:-4px; top:50%; height:44px; transform:translateY(-50%); }
.fl-shot__x::after { content:""; position:absolute; inset:-8px; }
@media (max-width:767px) { .fl-grid.fl-grid--3 { grid-template-columns:1fr; } .fl-grid { grid-template-columns:1fr; } }
.fl-photos legend, .fl-opts legend, .fl-pay__methods legend { font-size:.875rem; font-weight:600; letter-spacing:0; text-transform:none; } /* tipo oración, como los rótulos */

/* ══ Pasos de formulario (Vehículo, Detalles): el contenedor se ajusta al formulario, una columna centrada
   (como AVT, Stripe Checkout, Kavak). Sin media tarjeta vacía a la derecha; los campos ocupan todo el ancho. */
.fl.fl--form { max-width:600px; }
.fl--form .fl-grid { grid-template-columns:minmax(0,1fr); }

/* ══ Escritorio ancho: dos paneles (Kavak, Carvana, checkouts). Izquierda: contexto (título, promesas y en Detalles
   el valor en vivo, fijo al hacer scroll). Derecha: el formulario, que sigue en una columna. En móvil los paneles no existen. */
.fl-card__aside, .fl-card__main { display:contents; }
@media (min-width:1100px) {
  .fl.fl--form { max-width:1080px; }
  .fl--form .fl-card { grid-template-columns:minmax(0,380px) minmax(0,1fr); column-gap:48px; align-items:start; padding:28px 40px; }
  .fl--form .fl-card > .fl-resume { grid-column:1 / -1; }
  .fl--form .fl-card__aside, .fl--form .fl-card__main { display:grid; gap:20px; grid-template-columns:minmax(0,1fr); }
  .fl--form .fl-card__aside { position:sticky; top:16px; }
  .fl--form .fl-card__aside .fl-live { position:static; }
  .fl--form .fl-card__aside header h1 { font-size:2rem; }
}

/* ══ Resultado en Concorde (14/10): héroe oscuro de la familia Wallet / valor en vivo, con el rango como escala y la
   confianza con Signal. Secciones con CardTitle, tablas con Table, plegables con Accordion. Sin edición del valor. */
.fl-hero { display:grid; gap:10px; padding:28px; border-radius:24px; color:#fff;
  background:linear-gradient(116deg,#5A35C2 0%,#2E0F70 55%,#100030 100%); box-shadow:0 14px 34px rgba(34,0,92,.25); }
.fl-hero__top { display:flex; justify-content:space-between; align-items:center; gap:12px; flex-wrap:wrap; }
.fl-hero__top small { font-size:.8125rem; color:#CFBAFF; }
.fl-hero__conf { display:inline-flex; align-items:center; gap:8px; padding:4px 12px 4px 10px; border-radius:999px; font-size:.75rem; font-weight:700; background:rgba(255,255,255,.1); }
.fl-result .fl-hero h1 { margin:6px 0 0; font-size:.9375rem; font-weight:700; color:#E8DEFF; }
.fl-hero__big { font-size:3.5rem; line-height:1; font-weight:800; letter-spacing:-0.03em; font-variant-numeric:tabular-nums; }
.fl-hero__range { display:grid; grid-template-columns:auto 1fr auto; align-items:center; gap:12px; margin-top:6px; font-size:.8125rem; font-weight:700; font-variant-numeric:tabular-nums; color:#E8DEFF; }
.fl-hero__range i { position:relative; height:6px; border-radius:3px; background:linear-gradient(90deg,#F4AC59,#ED8936 40%,#8460E5); }
.fl-hero__range em { position:absolute; top:50%; width:16px; height:16px; margin-left:-8px; border-radius:50%; background:#fff; transform:translateY(-50%); box-shadow:0 0 0 4px rgba(255,255,255,.25); }
.fl-hero > p { margin:4px 0 0; max-width:62ch; font-size:.8125rem; line-height:1.5; color:#CFBAFF; }
.fl-sigchip { display:inline-flex; padding:6px 10px; border-radius:10px; background:#2E0F70; }
.fl-avt__card .cardtitle { margin-bottom:4px; justify-self:start; width:fit-content; max-width:100%; }
.fl-acc .fl-season, .fl-acc > * { margin-top:0; }
.fl-result .is-neg { color:#C0392B; font-weight:700; } .fl-result .is-pos { color:#1E8E5A; font-weight:700; }
@media (max-width:767px) { .fl-hero { padding:22px 18px; } .fl-hero__big { font-size:2.75rem; } }
.fl-hero .fl-hero__sub { margin:0; font-size:.875rem; font-weight:600; color:#E8DEFF; }
.fl-prec { margin:12px 0 0; font-size:.8125rem; color:var(--muted); }

/* ══ Concorde en el flujo (14/10): Button outline para las acciones secundarias, TermsSelector en los checks,
   ProgressBar en la precisión, Accordion en los grupos de Detalles y CardTitle en las secciones de Información. */
.fl-save svg { margin-right:8px; }
.fl-group__t { display:inline-flex; flex-wrap:wrap; align-items:center; gap:6px 10px; }
.fl-group__t small { font-size:.75rem; font-weight:600; color:var(--muted); white-space:nowrap; }
.fl-group__t .fl-group__done { font-size:.75rem; }
.fl-group__body { padding:4px 16px 16px; }
.fl-check { display:grid; align-content:center; padding:0; }
.fl-check__lbl { box-sizing:border-box; width:100%; padding:10px 12px; cursor:pointer; }
.fl-check small { padding:0 12px 10px 36px; }

/* ══ Jerarquía (14/10): un solo CTA por pantalla, a todo el ancho de la columna del formulario; Atrás / Saltar /
   Empezar de nuevo / Cambiar son enlaces de texto (propuesta para Julio: Concorde no tiene botón terciario). */
.fl-foot--stack { display:grid; gap:12px; justify-content:stretch; }
.fl-foot--stack > button { width:100%; }
.fl-foot__links { display:flex; justify-content:space-between; align-items:center; gap:12px; }
.fl-foot__links:has(> :only-child) { justify-content:center; }
.fl-tlink { text-decoration:underline; text-underline-offset:3px; text-decoration-color:#CFBAFF; }
.fl-tlink::after { content:""; position:absolute; left:-4px; right:-4px; top:50%; height:44px; transform:translateY(-50%); } .fl-tlink { position:relative; }
.fl-group__done { color:#006466; }

/* ══ Ficha viva (propuesta 14/10): la columna izquierda deja de ser marketing y muestra el vehículo que se arma.
   Misma familia oscura que el valor en vivo de Detalles. */
.fl-ficha { display:grid; gap:4px; padding:20px; border-radius:18px; color:#fff; background:linear-gradient(116deg,#5A35C2 0%,#2E0F70 55%,#100030 100%); box-shadow:0 14px 34px rgba(34,0,92,.2); }
.fl-ficha > small:first-child { font-size:.75rem; font-weight:700; letter-spacing:.04em; text-transform:uppercase; color:#CFBAFF; }
.fl-ficha > b { font-size:1.5rem; font-weight:800; letter-spacing:-0.02em; line-height:1.2; }
.fl-ficha > b.is-empty { font-size:1.125rem; font-weight:600; color:#CFBAFF; }
.fl-ficha dl { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:12px; margin:12px 0 0; }
.fl-ficha dt { font-size:.75rem; color:#CFBAFF; }
.fl-ficha dd { margin:2px 0 0; font-size:.9375rem; font-weight:700; font-variant-numeric:tabular-nums; overflow-wrap:anywhere; }
.fl-ficha dd.is-empty { color:rgba(255,255,255,.35); }
.fl-ficha__tag { justify-self:start; margin-top:10px; padding:4px 10px; border-radius:999px; font-size:.75rem; font-weight:700; background:rgba(255,255,255,.12); cursor:help; }
.fl-ficha__tag.is-good { color:#0B3B2A; background:#70F3B8; } .fl-ficha__tag.is-warn { color:#4A2200; background:#FDD8A4; }
.fl-ficha__count { font-size:.75rem; color:#CFBAFF; }
.fl-trust { display:flex; align-items:flex-start; gap:8px; margin:0; font-size:.875rem; font-weight:600; color:#5A35C2; } .fl-trust svg { flex:none; margin-top:1px; }
.fl-restored { display:flex; justify-content:space-between; align-items:center; gap:12px; flex-wrap:wrap; margin:0; padding:10px 14px; border-radius:12px; font-size:.875rem; color:var(--ink); background:#F5F0FF; }
.fl-restored .fl-tlink { padding:4px 2px; }
@media (min-width:1100px) { .fl--form .fl-card--ficha .fl-card__aside header h1 { font-size:1.75rem; } }
@media (max-width:767px) { .fl-ficha > b { font-size:1.25rem; } }

/* ══ Resultado «Ficha viva» (propuesta 14/10): decisión primero. Aviso legal fuera del héroe; confianza explicada. */
.fl-hero__conf2 { display:flex; align-items:center; gap:10px; flex-wrap:wrap; margin:6px 0 0 !important; font-size:.8125rem; color:#CFBAFF; }
.fl-where { display:grid; gap:14px; padding:24px; border-radius:20px; background:#fff; box-shadow:0 1px 3px rgba(34,0,92,.05), 0 10px 30px rgba(34,0,92,.07); }
.fl-where h2 { margin:0; font-size:1.125rem; font-weight:800; color:var(--ink); }
.fl-where__row { display:grid; grid-template-columns:minmax(0,220px) 1fr auto; align-items:center; gap:16px; }
.fl-where__row > div { display:grid; gap:2px; } .fl-where__row b { font-size:.9375rem; color:var(--ink); } .fl-where__row small { font-size:.75rem; color:var(--muted); }
.fl-where__bar { height:10px; border-radius:999px; background:#F1EEF8; overflow:hidden; }
.fl-where__bar i { display:block; height:100%; border-radius:999px; background:#CFBAFF; }
.fl-where__row:last-of-type .fl-where__bar i { background:linear-gradient(90deg,#F4AC59,#ED8936); }
.fl-where__row strong { min-width:96px; text-align:right; font-size:1.25rem; font-weight:800; color:var(--ink); font-variant-numeric:tabular-nums; }
.fl-where__diff { margin:0; padding:10px 14px; border-radius:12px; font-size:.875rem; color:var(--ink); background:#FFF4E8; } .fl-where__diff b { color:#B25614; }
.fl-moved { list-style:none; margin:0; padding:0; display:grid; gap:8px; }
.fl-moved li { display:flex; justify-content:space-between; gap:12px; font-size:.875rem; padding-bottom:8px; border-bottom:1px solid var(--line); }
.fl-moved li:last-child { border-bottom:0; padding-bottom:0; }
.fl-moved .is-neg { color:#C0392B; } .fl-moved .is-pos { color:#1E8E5A; }
.fl-when { display:grid; grid-template-columns:1fr 1fr; gap:12px; margin:0; }
.fl-when > div { padding:12px; border-radius:12px; background:#F5F0FF; } .fl-when dt { font-size:.75rem; color:var(--muted); }
.fl-when dd { margin:2px 0 0; font-size:1.125rem; font-weight:800; color:var(--ink); font-variant-numeric:tabular-nums; } .fl-when small { font-size:.75rem; color:#C0392B; font-weight:700; }
.fl-legal { margin:0; font-size:.75rem; line-height:1.5; color:var(--muted); max-width:72ch; }
@media (max-width:767px) {
  .fl-where { padding:18px 16px; }
  .fl-where__row { grid-template-columns:1fr auto; gap:6px 12px; }
  .fl-where__bar { grid-column:1 / -1; grid-row:2; }
}
.fl-result--ficha td b { white-space:nowrap; }
.fl-result--ficha .fl-avt__card > .fl-inline { justify-self:start; margin-top:4px; }


/* ── Valorizar (14/10): campos deshabilitados con menos peso (no parecen errores ni bloquean la vista) y «km» fijo. */
.fl-select.is-disabled { background:transparent; border-style:dashed; border-color:#DAD8E0; }
.fl-select.is-disabled select { color:#A3A1AA; }
.fl-select.is-disabled svg { color:#D4D2D9; }
.fl-km .pinput-root > div:first-child::after { content:"km"; flex:none; margin-left:8px; font-size:.9375rem; font-weight:600; color:var(--muted); }

/* ── Selector con búsqueda (PROPUESTA DS, 14/10): mismo marco que .fl-select; la lista cae debajo del campo. */
.fl-combo input { appearance:none; width:100%; height:100%; padding:0 40px 0 16px; border:0; background:transparent; font:inherit; font-size:1rem; color:var(--foreground); outline:none; border-radius:16px; }
.fl-combo input::placeholder { color:var(--muted); }
.fl-combo input:not(:disabled):not(:focus)::placeholder { color:var(--foreground); } /* con valor elegido, el valor se ve aunque el campo esté vacío para escribir */
.fl-combo.is-disabled input { cursor:not-allowed; }
.fl-combo.is-disabled input::placeholder { color:#A3A1AA; }
.fl-combo.is-open { border-color:#8460E5; }
.fl-combo.is-open svg { transform:rotate(180deg); }
.fl-combo svg { transition:transform .2s cubic-bezier(.25,.8,.25,1); }
.fl-combo__list { position:absolute; z-index:20; top:calc(100% + 6px); left:-2px; right:-2px; max-height:264px; overflow-y:auto; margin:0; padding:6px; list-style:none; border-radius:16px; background:#fff; box-shadow:0 12px 32px rgba(34,0,92,.16), inset 0 0 0 1px #E1E3E2; }
.fl-combo__list li { padding:10px 12px; border-radius:10px; font-size:.9375rem; color:var(--ink); cursor:pointer; }
.fl-combo__list li.is-act { background:#F5F0FF; }
.fl-combo__list li[aria-selected="true"] { font-weight:700; }
.fl-combo__list li.is-manual { margin-top:4px; border-top:1px solid #EEEDF0; border-radius:0 0 10px 10px; color:#5A35C2; font-weight:600; }
.fl-combo__none { color:var(--muted) !important; cursor:default !important; }
.fl-gone { display:flex; align-items:center; gap:8px; margin:0 0 16px; padding:10px 16px; border-radius:12px; font-size:.875rem; color:var(--ink); background:#F5F0FF; }
@media (prefers-reduced-motion:reduce) { .fl-combo svg { transition:none; } }
.fl-gone { grid-column:1 / -1; }
.fl-km .pinput-root:has(input:disabled) > div:first-child { border:2px dashed #DAD8E0; background:transparent; box-shadow:none; } /* igual que los selectores deshabilitados */

.fl-result--ds { padding-bottom:96px; } /* que la barra fija de Guardar · Publicar no tape lo último */

/* ── Maqueta VMC (16/10): Valorizar y Publicar dentro de /m/vmc. Las media queries de arriba miran el viewport; aquí el
   contenido mide ~770 px (1024 − barra lateral), así que todo se ajusta a esa columna.
   PROPUESTA DS para Julio · «Campo VMC»: un solo vocabulario de campo para select, combo, Input y textarea (antes había
   dos: borde gris de 2 px y el degradado de Concorde). Material = el de Mi Garaje VMC: tarjeta con anillo de 1 px, radio
   12 de las filas, sin sombras dentro de tarjetas. Borde del campo con 3.4:1 (WCAG 1.4.11; el gris anterior daba 1.3:1).
   Jerarquía = Mi Garaje VMC: 20/700 título · 16/700 sección · 14/600 etiqueta · 14/400 valor · 12/400 ayuda.
   Espacios: 4 título+bajado · 8 etiqueta→campo · 16 grilla · 24 bloques · 32 padding.
   Formulario (Baymard: una columna; en una fila solo campos dependientes): Marca · Año + Km · Modelo + Versión. */
.fl--vmc {
  --f-ink:#3B1782; --f-text:#191C1C; --f-muted:#6B6878; --f-accent:#ED8936; --f-focus:#8460E5; --f-error:#D92D20;
  --f-line:#8E89A0; --f-line-hover:#6B6878; --f-hair:#E1E3E2; --f-fill-off:#F4F3F8; --f-tint:#F5F0FF;
  --f-ring:0 0 0 3px rgba(132,96,229,.22);
  --f-r-card:16px; --f-r-field:12px; --f-h-field:44px;
}
@media (min-width:1024px) {
  .fl.fl--vmc { max-width:none; padding:24px 16px 64px; gap:16px; }
  .fl--vmc .vz-back a { font-size:.875rem; font-weight:600; }
  .fl--vmc .fl-stepper li { font-weight:600; }

  /* Tarjeta: el anillo de 1 px de las tarjetas de Mi Garaje en vez de la sombra difusa. */
  .fl.fl--vmc .fl-card { padding:32px; row-gap:24px; border-radius:var(--f-r-card); box-shadow:0 0 0 1px var(--f-hair), 0 1px 2px rgba(34,0,92,.06); }
  .fl--vmc .fl-foot--sticky { margin:0 -32px -32px; padding:16px 32px; border-radius:0 0 var(--f-r-card) var(--f-r-card); }
  .fl.fl--vmc.fl--form .fl-card { grid-template-columns:minmax(0,1fr); }
  .fl.fl--vmc.fl--form .fl-card__aside { position:static; gap:16px; }
  .fl.fl--vmc .fl-card__aside .fl-live { position:sticky; top:12px; }
  .fl--vmc .fl-card__main { gap:24px; }
  .fl--vmc .fl-card__main > .fl-grid { grid-template-columns:repeat(2,minmax(0,1fr)); gap:16px; }
  .fl--vmc .fl-card__main > .fl-grid > :first-child { grid-column:1 / -1; }
  .fl--vmc .fl-foot { padding-top:24px; border-top-color:var(--f-hair); }
  .fl--vmc .fl-foot--stack { gap:8px; }
  .fl--vmc .fl-src { margin:0; }

  /* Recuadros dentro de la tarjeta: tinte plano, radio del campo, sin sombra. */
  .fl--vmc .fl-msrp, .fl--vmc .fl-resume { border-radius:var(--f-r-field); }
  .fl--vmc .fl-msrp > span:first-child { font-size:.875rem; font-weight:600; color:var(--f-ink); }
  .fl--vmc .fl-resume { padding:12px 16px; flex-wrap:nowrap; background:var(--f-tint); box-shadow:none; }
  .fl--vmc .fl-resume > div:first-child { flex:1; min-width:0; }
  .fl--vmc .fl-resume b { display:block; font-size:.875rem; font-weight:700; }
  .fl--vmc .fl-resume span { font-size:.75rem; }
  .fl--vmc .fl-resume__btns { flex:none; gap:16px; }
  .fl--vmc .fl-resume .fl-tlink { white-space:nowrap; }
  .fl--vmc .fl-resume .pvbtn { height:40px; padding-inline:24px; font-size:.875rem; }

  /* Información: Placa · Cuánto esperas · Cilindrada en las 3 columnas de Ubicación; pago al nivel de fila. */
  .fl--vmc .fl-grid.fl-grid--datos { grid-template-columns:repeat(3,minmax(0,1fr)); }
  .fl--vmc #f-placa { max-width:none; }
  .fl--vmc .fl-check { border-radius:var(--f-r-field); }
  .fl--vmc .fl-pay { gap:24px; }
  .fl--vmc .fl-method { border-radius:var(--f-r-field); }
  .fl--vmc .fl-method b { font-size:.875rem; font-weight:700; }
  .fl--vmc .fl-method small { font-size:.75rem; }
}

/* 16/10 · Campo VMC, tipografía y Detalles también en mobile (antes solo ≥ 1024 px: en el celular quedaban
   los campos punteados y los pesos 800 del lab). Mismas reglas, sin media query. */
  /* Tipografía */
  .fl.fl--vmc .fl-card header h1, .fl--vmc .fl-done h1, .fl--vmc .fl-prev__bar h1 { font-size:1.25rem; font-weight:700; letter-spacing:-0.01em; }
  .fl--vmc .fl-card header p, .fl--vmc .fl-done > p { margin-top:4px; font-size:.875rem; color:var(--f-muted); }
  .fl--vmc .fl-field { gap:8px; }
  .fl--vmc .fl-label, .fl--vmc .fl-opts legend { font-size:.875rem; font-weight:600; letter-spacing:0; text-transform:none; color:var(--f-ink); }
  .fl--vmc .fl-hint { font-size:.75rem; color:var(--f-muted); text-wrap:pretty; }
  .fl--vmc .fl-saved { font-size:.75rem; color:var(--f-muted); }
  .fl--vmc .fl-error { margin:0; color:var(--f-error); }
  .fl--vmc .fl-errsum { border-left:0; border-radius:var(--f-r-field); box-shadow:inset 0 0 0 1px #F5B7B1; }
  .fl--vmc .fl-decide b { font-size:1rem; font-weight:700; }
  .fl--vmc .fl-decide span { font-size:.75rem; }
  .fl--vmc .fl-hero__big { font-size:2.5rem; font-weight:700; }
  .fl--vmc .fl-live > b { font-size:1.5rem; font-weight:700; }

  /* Campo VMC: default · hover · foco · error · deshabilitado, igual en los cuatro controles. */
  .fl--vmc .fl-select, .fl--vmc .pinput, .fl--vmc .fl-textarea { border:1px solid var(--f-line); border-radius:var(--f-r-field); background:#fff; box-shadow:none; transition:border-color .15s, box-shadow .15s, background-color .15s; }
  .fl--vmc .fl-select, .fl--vmc .pinput { height:var(--f-h-field); }
  .fl--vmc .pinput { padding:0 16px; background-image:none; }
  .fl--vmc .fl-select:hover:not(.is-disabled), .fl--vmc .pinput:hover:not(.pinput--disabled), .fl--vmc .fl-textarea:hover { border-color:var(--f-line-hover); }
  .fl--vmc .fl-select:focus-within, .fl--vmc .fl-combo.is-open, .fl--vmc .pinput:focus-within, .fl--vmc .fl-textarea:focus { border-color:var(--f-focus); box-shadow:var(--f-ring); padding-inline:16px; }
  .fl--vmc .fl-select:focus-within, .fl--vmc .fl-combo.is-open { padding-inline:0; }
  .fl--vmc .fl-select.is-error, .fl--vmc .pinput--error, .fl--vmc .pinput--error:focus-within, .fl--vmc .fl-textarea.is-error { border-color:var(--f-error); box-shadow:none; }
  .fl--vmc .fl-select.is-disabled, .fl--vmc .fl-select:has(select:disabled), .fl--vmc .pinput--disabled, .fl--vmc .fl-km .pinput-root:has(input:disabled) > div:first-child { border:1px solid transparent; background:var(--f-fill-off); opacity:1; }
  .fl--vmc .fl-select select, .fl--vmc .fl-combo input { border-radius:var(--f-r-field); font-size:.875rem; }
  .fl--vmc .pinput__field, .fl--vmc .fl-textarea { font-size:.875rem; }
  .fl--vmc .fl-select.is-disabled select, .fl--vmc .fl-combo.is-disabled input::placeholder, .fl--vmc .pinput--disabled .pinput__field::placeholder { color:#7D798A; }
  .fl--vmc .fl-km .pinput-root > div:first-child::after { font-size:.875rem; }
  /* El naranja es de lo accionable: el chevron va neutro y se enciende con el foco. */
  .fl--vmc .fl-select svg { color:var(--f-muted); }
  .fl--vmc .fl-select:focus-within svg, .fl--vmc .fl-combo.is-open svg { color:var(--f-accent); }
  .fl--vmc .fl-select.is-disabled svg { color:#B9B5C4; }

  /* Detalles: los grupos eran tarjetas con sombra dentro de la tarjeta; ahora son filas con divisor, como las secciones de Mi Garaje. */
  .fl--vmc .fl-groups { gap:0; border-top:1px solid var(--f-hair); }
  .fl--vmc .fl-group.pacc { border-radius:0; box-shadow:none; border-bottom:1px solid var(--f-hair); }
  .fl--vmc .fl-group .pacc__header { min-height:56px; padding:0; }
  .fl--vmc .fl-group.pacc--open .pacc__header { box-shadow:none; }
  .fl--vmc .fl-group .pacc__content-pad { padding:0 0 24px; }
  .fl--vmc .fl-group__body { padding:0; gap:16px; }
  .fl--vmc .fl-opts legend { margin-bottom:8px; }
  /* Pregunta ≠ respuesta: opción sin elegir 14/400 con borde de campo; elegida 14/600 en violeta. */
  .fl--vmc .fl-opts button { min-height:40px; font-weight:400; box-shadow:inset 0 0 0 1px var(--f-line); }
  .fl--vmc .fl-opts button:hover { box-shadow:inset 0 0 0 1px var(--f-line-hover); }
  .fl--vmc .fl-opts button.is-on { font-weight:600; box-shadow:none; }


/* 16/10 · Detalles (pedido de Abraham): la tarjeta de valor acompaña el scroll en desktop (antes quedaba arriba y el cambio no se veía),
   una sola nota de «típico» por grupo (antes la etiqueta se repetía en cada campo) y el impacto de cada opción legible (12 px, no 11). */
@media (min-width:1024px) {
  .fl.fl--vmc.fl--form .fl-card__aside { display:contents; }
  .fl.fl--vmc .fl-card > .fl-live, .fl.fl--vmc .fl-card__aside .fl-live { position:sticky; top:16px; }
}
.fl--vmc .fl-typnote { margin:0; display:flex; align-items:center; gap:8px; padding:8px 12px; border-radius:var(--f-r-field); font-size:.75rem; color:var(--f-ink); background:var(--f-tint); }
.fl--vmc .fl-typnote svg { flex:none; }
.fl--vmc .fl-opts button small { font-size:.75rem; }
.fl--vmc .fl-live > em { font-weight:600; }
/* Versión única como texto confirmado; resumen de lo elegido en el grupo plegado. */
.fl--vmc .fl-only { margin:0; display:flex; align-items:center; gap:8px; min-height:var(--f-h-field); padding:0 16px; border-radius:var(--f-r-field); font-size:.875rem; font-weight:600; color:var(--f-ink); background:var(--f-tint); }
.fl--vmc .fl-only small { font-weight:400; color:var(--f-muted); }
/* Mecánica precargada: se confirma (CarMax/KBB) en vez de elegir de cero; «Cambiar» abre las opciones. */
.fl--vmc .fl-confirm { display:flex; align-items:center; justify-content:space-between; gap:16px; flex-wrap:wrap; padding:16px; border-radius:var(--f-r-field); background:var(--f-tint); }
.fl--vmc .fl-confirm p { margin:0; display:grid; gap:4px; }
.fl--vmc .fl-confirm small { font-size:.75rem; color:var(--f-muted); }
.fl--vmc .fl-confirm b { font-size:1rem; font-weight:700; color:var(--f-ink); }
.fl--vmc .fl-confirm > div { display:flex; align-items:center; gap:16px; }
.fl--vmc .fl-confirm .pvbtn { height:40px; min-width:0; padding-inline:24px; font-size:.875rem; }
@media (max-width:1023px) { .fl--vmc .fl-confirm > div { width:100%; justify-content:space-between; } }
/* Detalles VMC (16/10): las 4 secciones abiertas, sin acordeón (todo libre y se ve cuánto falta; NN/g: el acordeón esconde lo que casi todos van a responder). */
.fl--vmc .fl-groups { gap:0; }
.fl--vmc .fl-sec { display:grid; gap:16px; padding:24px 0; border-bottom:1px solid var(--f-hair); }
.fl--vmc .fl-sec:last-child { border-bottom:0; }
.fl--vmc .fl-sec .fl-group__body { display:grid; gap:16px; }
/* Grilla del paso Vehículo: la nota del km no empuja la fila (se superpone al espacio entre filas). */
@media (min-width:1024px) { .fl--vmc .fl-card__main > .fl-grid { row-gap:32px; } }

/* 16/10 · Barra superior VMC: «‹ Mi Garaje» y los pasos en una sola fila (desktop). Hecho = violeta con check blanco y se
   puede tocar para volver; actual = naranja; pendiente = gris. Fuera de VMC la envoltura no existe para el layout. */
.fl-bar { display:contents; }
.fl--vmc .fl-bar { display:grid; gap:12px; }
@media (min-width:1024px) { .fl--vmc .fl-bar { grid-template-columns:auto minmax(0,1fr); align-items:end; column-gap:32px; } }
.fl--vmc .fl-bar .vz-back { margin:0; }
.fl--vmc .fl-stepper { gap:8px; }
.fl--vmc .fl-stepper li { gap:8px; font-size:.75rem; font-weight:600; color:var(--f-muted); }
.fl--vmc .fl-stepper li::before { height:4px; background:#ECEAF2; }
.fl--vmc .fl-stepper li.is-done { color:var(--f-ink); } .fl--vmc .fl-stepper li.is-done::before { background:#8460E5; }
.fl--vmc .fl-stepper li.is-now { color:var(--f-ink); font-weight:700; } .fl--vmc .fl-stepper li.is-now::before { background:linear-gradient(90deg,#F4AC59,#ED8936); }
.fl--vmc .fl-stepper__dot { width:20px; height:20px; font-size:.6875rem; font-weight:700; color:var(--f-muted); background:#ECEAF2; }
.fl--vmc .fl-stepper li.is-done .fl-stepper__dot { color:#fff; background:#8460E5; }
.fl--vmc .fl-stepper li.is-now .fl-stepper__dot { color:#fff; background:#ED8936; box-shadow:0 0 0 3px rgba(237,137,54,.2); }
.fl--vmc .fl-stepper__go { all:unset; cursor:pointer; display:inline-flex; align-items:center; gap:8px; margin:-4px -8px; padding:4px 8px; border-radius:8px; }
.fl--vmc .fl-stepper__go:hover { background:var(--f-tint); } .fl--vmc .fl-stepper__go:hover .fl-stepper__label { text-decoration:underline; text-underline-offset:3px; }
.fl--vmc .fl-stepper__go:focus-visible { outline:2px solid var(--f-focus); outline-offset:2px; }
.fl--vmc .fl-stepper li { grid-template-columns:1fr; } .fl--vmc .fl-stepper li > .fl-stepper__go, .fl--vmc .fl-stepper li > .fl-stepper__dot { justify-self:start; }
.fl--vmc .fl-stepper li:not(:has(.fl-stepper__go)) { grid-template-columns:auto 1fr; }

/* ══ 16/10 (tarde) · Valorizar VMC con piezas de Concorde ══ */
/* Opciones = ConditionPill (rellena = elegida · contorno = no). El botón solo da la interacción. */
.fl--vmc .fl-opts button.fl-pill { all:unset; cursor:pointer; border-radius:23px; }
.fl--vmc .fl-opts button.fl-pill:focus-visible { outline:2px solid var(--f-focus); outline-offset:2px; }
.fl--vmc .fl-opts button.fl-pill:hover .pcondpill--outline { filter:brightness(.97); }
.fl--vmc .fl-pill .pcondpill { padding:6px 20px; font-size:.875rem; }
.fl--vmc .fl-pill .pcondpill__text { display:inline-flex; align-items:baseline; gap:6px; }
.fl--vmc .fl-pill small { font-size:.75rem; font-weight:400; opacity:.85; }
/* Mecánica típica: texto, las tres respuestas en ConditionPill y «Cambiar» (ProfileButton) */
.fl--vmc .fl-confirm { display:grid; grid-template-columns:1fr auto; align-items:center; gap:8px 16px; padding:0; background:none; }
.fl--vmc .fl-confirm > small { grid-column:1 / -1; font-size:.75rem; color:var(--f-muted); }
.fl--vmc .fl-confirm__pills { display:flex; flex-wrap:wrap; gap:8px; }
.fl--vmc .fl-confirm__pills .pcondpill { padding:6px 20px; font-size:.875rem; }
/* Valor estimado: tarjeta blanca del DS (sombra 0 0 16px 4px), CardTitle y ProgressBar */
.fl--vmc .fl-live.fl-live--ds { display:grid; grid-template-columns:1fr auto; align-items:center; gap:12px 16px; padding:16px 20px; border-radius:16px; color:var(--f-ink); background:#fff; box-shadow:0 0 16px 4px rgba(0,0,0,.08); }
