@media (max-width:767px) { .fl--vmc .fl-steps li:not(.is-now) button { font-size:0; gap:0; } .fl--vmc .fl-steps li:not(.is-now) { font-size:0; gap:0; } }
/* La ConditionPill «outline» es gris (en el DS = «no incluida»): como opción disponible va en violeta con borde lila. */
