  .fl--vmc .fl-confirm__pills .pcondpill { padding:6px 16px; }
}
.fl--vmc .fl-confirm__pills { justify-content:flex-start; } .fl--vmc .fl-confirm__pills > * { flex:none; }

/* ── Pasos VMC · pulido 16/10 (noche): nombres arriba, barra abajo partida en 3 tramos alineados con cada paso
   (antes un solo riel gris oscuro y el borde blanco del gradiente difuminaba dónde terminaba). «Mi Garaje» centrado con el bloque. */
@media (min-width:1024px) { .fl--vmc .fl-bar { align-items:center; } }
.fl--vmc .fl-steps { gap:10px; }
.fl--vmc .fl-steps ol { order:-1; column-gap:6px; }
.fl--vmc .fl-steps li { font-size:.8125rem; }
.fl--vmc .fl-steps li > span { width:22px; height:22px; font-size:.75rem; color:var(--f-muted); }
.fl--vmc .fl-steps li.is-done button { color:#3B1782; }
