.fl--vmc .fl-steps .pprogbar { height:6px; border-radius:9999px; background:#E7E3F0; box-shadow:none;
  -webkit-mask:linear-gradient(90deg, #000 calc(33.333% - 3px), transparent 0 calc(33.333% + 3px), #000 0 calc(66.666% - 3px), transparent 0 calc(66.666% + 3px), #000 0);
          mask:linear-gradient(90deg, #000 calc(33.333% - 3px), transparent 0 calc(33.333% + 3px), #000 0 calc(66.666% - 3px), transparent 0 calc(66.666% + 3px), #000 0); }
.fl--vmc .fl-steps .pprogbar__fill { background:linear-gradient(90deg, #F4AC59 0%, #ED8936 30%, #8460E5 100%); }

/* ── Valor estimado en vivo · 16/10 (noche): sin corchetes; número protagonista; precisión en 12 tramos (uno por detalle)
   sobre un riel claro, sin la sombra interior oscura del ProgressBar. */
.fl--vmc .fl-live.fl-live--ds { gap:16px 24px; padding:20px 24px; box-shadow:0 1px 3px rgba(34,0,92,.05), 0 10px 30px rgba(34,0,92,.08); }
.fl--vmc .fl-live__id { min-width:0; display:grid; gap:4px; }
