.fl--vmc .fl-live__v b { font-size:1.75rem; font-weight:800; letter-spacing:-0.02em; line-height:1.1; }
.fl--vmc .fl-live__v em { display:inline-flex; align-items:center; height:22px; padding:0 8px; border-radius:9999px; background:#F5F0FF; }
.fl--vmc .fl-live__v em.is-down { background:#FFF1E2; }
.fl--vmc .fl-live__p { gap:8px; padding-top:16px; border-top:1px solid #F0EEF4; }
.fl--vmc .fl-live__p .pprogbar { height:6px; border-radius:2px; background:#E7E3F0; box-shadow:none;
  -webkit-mask:repeating-linear-gradient(90deg, #000 0 calc((100% - 44px) / 12), transparent calc((100% - 44px) / 12) calc((100% - 44px) / 12 + 4px));
          mask:repeating-linear-gradient(90deg, #000 0 calc((100% - 44px) / 12), transparent calc((100% - 44px) / 12) calc((100% - 44px) / 12 + 4px)); }
.fl--vmc .fl-live__p .pprogbar__fill { background:linear-gradient(90deg, #F4AC59 0%, #ED8936 30%, #8460E5 100%); }
