.fl--vmc .fl-live__p small b { font-weight:600; color:#3B1782; font-variant-numeric:tabular-nums; }
.fl--vmc .fl-live__p small span { color:#6B6878; }
@media (max-width:640px) {
  .fl--vmc .fl-live.fl-live--ds { grid-template-columns:1fr; gap:12px; padding:16px; }
  .fl--vmc .fl-live__v { justify-items:start; grid-auto-flow:column; align-items:center; justify-content:start; gap:12px; }
}
