/* ── Detalles VMC · movimiento (16/10 noche). Mismo flujo que AVT; solo microinteracciones.
   Curva ease-out exponencial; todo se apaga con «reducir movimiento». */
.fl--vmc .fl-pill .pcondpill { transition:background-color .2s, box-shadow .2s, color .2s, transform .16s cubic-bezier(.16,1,.3,1); }
.fl--vmc .fl-opts button.fl-pill:hover .pcondpill--outline { transform:translateY(-1px); box-shadow:inset 0 0 0 1px #AE8EFF, 0 6px 14px rgba(34,0,92,.10); filter:none; }
