  .fl--vmc .fl-opts button.fl-pill.is-on .pcondpill, .fl--vmc .fl-live__v em, .fl--vmc .fl-typical { animation:none; }
  .fl--vmc .fl-opts button.fl-pill:hover .pcondpill--outline, .fl--vmc .fl-opts button.fl-pill:active .pcondpill { transform:none; }
}

/* ── Pasos VMC · segunda vuelta (16/10 noche): «Mi Garaje» alineado con los nombres; paso actual = tramo a medias
   (en curso), con anillo naranja en su número; pendientes con número en contorno. El relleno avanza animado al cambiar de paso. */
@media (min-width:1024px) { .fl--vmc .fl-bar { align-items:start; } .fl--vmc .fl-bar .vz-back { min-height:24px; margin-top:-1px; } }
.fl--vmc .fl-steps ol { align-items:center; min-height:24px; }
.fl--vmc .fl-steps li > span { background:none; box-shadow:inset 0 0 0 1.5px #D9D4E5; color:#8A8797; }
.fl--vmc .fl-steps li.is-now > span { color:#fff; background:#ED8936; box-shadow:0 0 0 4px rgba(237,137,54,.18); }
.fl--vmc .fl-steps li { font-weight:500; }
.fl--vmc .fl-steps li.is-now { font-weight:700; color:#3B1782; }
.fl--vmc .fl-steps li.is-done button { font-weight:600; }
.fl--vmc .fl-steps .pprogbar__fill { transition:width .6s cubic-bezier(.16,1,.3,1); }
@media (prefers-reduced-motion:reduce) { .fl--vmc .fl-steps .pprogbar__fill { transition:none; } }
/* Pasos escalables (Valorizar 3 · Publicar 6): tramos según --n; con más de 3, «Mi Garaje» arriba y los pasos a todo el ancho. */
.fl--vmc .fl-steps .pprogbar { --seg:calc((100% - (var(--n, 3) - 1) * 6px) / var(--n, 3));
  -webkit-mask:repeating-linear-gradient(90deg, #000 0 var(--seg), transparent var(--seg) calc(var(--seg) + 6px));
          mask:repeating-linear-gradient(90deg, #000 0 var(--seg), transparent var(--seg) calc(var(--seg) + 6px)); }
.fl--vmc .fl-steps li { white-space:nowrap; min-width:0; }
@media (min-width:1024px) { .fl--vmc .fl-bar--long { grid-template-columns:1fr; row-gap:16px; } }
.fl--vmc .fl-steps--long li { font-size:.8125rem; }
.fl--vmc .fl-bar--long .vz-back { justify-content:flex-start; gap:16px; }
.fl-steps__of { display:none; }
/* Móvil con 6 pasos: solo el paso actual con «paso N de 6»; la barra de tramos muestra el resto. */
@media (max-width:767px) {
  .fl--vmc .fl-steps--long ol { grid-auto-flow:row; }
  .fl--vmc .fl-steps--long li:not(.is-now) { display:none; }
  .fl--vmc .fl-steps--long .fl-steps__of { display:inline; font-size:.75rem; font-weight:500; color:#6B6878; }
  .fl--vmc .fl-bar--long .vz-back { flex-wrap:wrap; row-gap:4px; }
}

/* ── Completa tu publicación · VMC (16/10 noche): títulos de bloque sin corchetes (como las secciones de Detalles) y
