.fl--vmc .fl-sub__t { margin:0; display:flex; align-items:baseline; gap:8px; font-size:1rem; font-weight:700; color:var(--f-ink); }
.fl--vmc .fl-sub__t small { font-size:.75rem; font-weight:400; color:var(--f-muted); }
.fl--vmc .fl-have--ds { grid-template-columns:auto minmax(0,1fr) auto; gap:14px; padding:14px 16px; border-radius:16px; background:#F5F0FF; box-shadow:inset 0 0 0 1px #E8DEFF; }
.fl--vmc .fl-have__ico { display:grid; place-items:center; width:40px; height:40px; border-radius:12px; background:#fff; box-shadow:0 2px 8px rgba(34,0,92,.08); }
.fl--vmc .fl-have--ds > div { min-width:0; display:grid; gap:2px; }
.fl--vmc .fl-have--ds small { font-size:.75rem; font-weight:600; color:#5A35C2; }
