.fl--vmc .fl-have--ds div > span { font-size:.8125rem; color:#6B6878; }
.fl--vmc .fl-have--ds > .pprofilebtn, .fl--vmc .fl-have--ds > button { grid-row:auto; grid-column:auto; }
.fl--vmc .fl-have--ds div > span { display:block; font-weight:400; }
