/* «De tu valorización» con áreas: desktop ícono | texto | Cambiar; móvil, Cambiar sube a la línea de la etiqueta y el nombre usa todo el ancho. */
.fl--vmc .fl-have--ds { grid-template-columns:40px minmax(0,1fr) auto; grid-template-areas:"ico k btn" "ico car btn" "ico m btn"; row-gap:2px; align-items:center; }
