}

/* Resumen de errores · VMC (16/10 noche): alerta compacta con los campos como píldoras tocables (antes lista con viñetas subrayadas). */
.fl--vmc .fl-errsum { display:grid; gap:10px; padding:14px 16px; border-radius:16px; background:#FEF2F2; box-shadow:inset 0 0 0 1px #FBD5D5; }
.fl--vmc .fl-errsum b { display:flex; align-items:center; gap:8px; font-size:.875rem; font-weight:700; color:#B91C1C; }
.fl--vmc .fl-errsum b::before { content:"!"; display:grid; place-items:center; width:20px; height:20px; border-radius:50%; font-size:.75rem; font-weight:800; color:#fff; background:#DC2626; flex:none; }
.fl--vmc .fl-errsum ul { list-style:none; margin:0; padding:0; display:flex; flex-wrap:wrap; gap:8px; }
.fl--vmc .fl-errsum .fl-inline { all:unset; cursor:pointer; display:inline-flex; align-items:center; min-height:32px; padding:0 12px; border-radius:9999px; font-size:.8125rem; font-weight:600; color:#B91C1C; background:#fff; box-shadow:inset 0 0 0 1px #F5B7B1; transition:background-color .15s, box-shadow .15s; }
.fl--vmc .fl-errsum .fl-inline:hover { background:#FFF7F7; box-shadow:inset 0 0 0 1px #EF4444; }
.fl--vmc .fl-errsum .fl-inline:focus-visible { outline:2px solid #DC2626; outline-offset:2px; }
/* 16/10: Valorizar igual que Publicar (aprobado): «Mi Garaje» arriba y los pasos a todo el ancho, con cualquier cantidad de pasos. */
@media (min-width:1024px) { .fl--vmc .fl-bar { grid-template-columns:1fr; row-gap:16px; } }
@media (max-width:767px) {
  .fl--vmc .fl-steps ol { grid-auto-flow:row; }
  .fl--vmc .fl-steps li:not(.is-now) { display:none; }
