}
/* Precio esperado (VMC): fila propia y atajos del rango AVT con las mismas píldoras de Detalles. */
.fl--vmc .fl-field--price { grid-column:1 / -1; }
.fl--vmc .fl-field--price .fl-input, .fl--vmc .fl-field--price .pinput { max-width:320px; }
.fl--vmc .fl-quick { display:flex; flex-wrap:wrap; gap:8px; margin-top:4px; }
.fl--vmc .fl-quick button.fl-pill { all:unset; cursor:pointer; border-radius:23px; }
.fl--vmc .fl-quick button.fl-pill:focus-visible { outline:2px solid var(--f-focus); outline-offset:2px; }
.fl--vmc .fl-quick .pcondpill { padding:6px 16px; font-size:.875rem; font-variant-numeric:tabular-nums; transition:background-color .2s, box-shadow .2s, transform .16s cubic-bezier(.16,1,.3,1); }
.fl--vmc .fl-quick .pcondpill__text { display:inline-flex; align-items:baseline; gap:6px; }
.fl--vmc .fl-quick small { font-size:.75rem; font-weight:400; opacity:.8; }
.fl--vmc .fl-quick .pcondpill--outline { color:#3B1782; box-shadow:inset 0 0 0 1px #CFBAFF, 0 2px 6px rgba(34,0,92,.06); }
.fl--vmc .fl-quick button:hover .pcondpill--outline { transform:translateY(-1px); box-shadow:inset 0 0 0 1px #AE8EFF, 0 6px 14px rgba(34,0,92,.10); }
.fl--vmc .fl-quick button:active .pcondpill { transform:scale(.96); }
@media (prefers-reduced-motion:reduce) { .fl--vmc .fl-quick .pcondpill { transition:none; transform:none !important; } }
.fl--vmc .fl-field--price { order:3; }
.fl--vmc .fl-field--price .fl-quick { order:1; } .fl--vmc .fl-field--price .fl-gauge { order:2; }
.fl--vmc .fl-quick { display:grid; grid-template-columns:repeat(3, minmax(0, 1fr)); max-width:520px; }
.fl--vmc .fl-quick button.fl-pill, .fl--vmc .fl-quick .pcondpill { display:block; width:100%; box-sizing:border-box; }
.fl--vmc .fl-quick .pcondpill, .fl--vmc .fl-quick button.fl-pill { border-radius:16px; }
.fl--vmc .fl-quick .pcondpill { padding:8px 10px; text-align:center; }
.fl--vmc .fl-quick .pcondpill__text { display:grid; gap:0; justify-items:center; }
.fl--vmc .fl-quick small { font-size:.6875rem; }
/* Nota Negociable (VMC): borde negociable de Concorde y etiqueta NEGOCIABLE con su degradado teal. */
.fl--vmc .fl-kindnote--neg { display:grid; grid-template-columns:auto minmax(0,1fr); align-items:center; gap:14px; padding:14px 16px; border-radius:16px; border:1.5px solid transparent;
  background-image:linear-gradient(#fff,#fff), linear-gradient(120deg, #fff 0%, #30E8EC 30%, #5A35C2 75%, #fff 100%); background-origin:border-box; background-clip:padding-box, border-box; box-shadow:0 6px 18px rgba(0,134,136,.10); }
.fl--vmc .fl-negtag { display:inline-flex; align-items:center; height:24px; padding:0 10px; border-radius:6px; font-size:.6875rem; font-weight:700; letter-spacing:.1em; text-transform:uppercase; color:#fff;
  background:linear-gradient(90deg, #30E8EC 0%, #00CACE 50%, #008688 100%); text-shadow:0 1px 2px rgba(0,0,0,.18); }
.fl--vmc .fl-kindnote--neg p { margin:0; font-size:.875rem; line-height:1.45; color:#6B6878; }
.fl--vmc .fl-kindnote--neg b { display:block; font-weight:700; color:#3B1782; }
@media (max-width:640px) { .fl--vmc .fl-kindnote--neg { grid-template-columns:1fr; gap:8px; } .fl--vmc .fl-negtag { justify-self:start; } }
/* Origen AVT de los atajos de precio */
.fl--vmc .fl-quick__src { order:1; display:inline-flex; align-items:center; gap:6px; margin-top:4px; font-size:.75rem; font-weight:600; color:#5A35C2; }
.fl--vmc .fl-field--price .fl-quick { order:1; } .fl--vmc .fl-field--price .fl-gauge { order:2; }

/* ── Vista previa VMC (16/10 noche): sin desborde. La columna mide ~766 y la ficha VMC necesita ~852 a dos columnas,
   así que la página de vista previa se apila cuando su contenedor no alcanza (container query). */
.fl--vmc .fl-prev { grid-template-columns:minmax(0,1fr); min-width:0; }
