  .fl--vmc .fl-prev__page { grid-template-columns:minmax(0,1fr); justify-items:center; }
  .fl--vmc .fl-prev__main, .fl--vmc .fl-prev__side { width:100%; max-width:443px; } /* el ancho fijo de AuctionStatus y CardViewer: todo alineado a esa columna */
}
