.fl--vmc .fl-prev > .fl-foot--sticky { margin:0; border-radius:16px; border-top:0; box-shadow:0 -4px 24px rgba(34,0,92,.10), 0 0 0 1px var(--f-hair); }
.fl--vmc .fl-prev__bar { position:static; }

