@media (max-width:640px) {
  .fl--vmc .fl-foot--sticky { display:grid; grid-template-columns:auto minmax(0,1fr); grid-template-areas:"st st" "back go"; align-items:center; gap:10px 16px; }
  .fl--vmc .fl-foot--sticky > .fl-tlink { grid-area:back; }
  .fl--vmc .fl-foot--sticky .fl-foot__right { display:contents; }
  .fl--vmc .fl-foot--sticky .fl-left { grid-area:st; justify-self:center; font-size:.75rem; }
  .fl--vmc .fl-foot--sticky .fl-foot__right > :last-child { grid-area:go; width:100%; max-width:none; }
}
/* Datos de la publicación: primero cuánto esperas recibir (la decisión), después placa y cilindrada; campo y atajos del mismo ancho. */
.fl--vmc .fl-field--price { order:-1; }
.fl--vmc .fl-field--price .fl-input, .fl--vmc .fl-field--price .pinput, .fl--vmc .fl-quick { max-width:520px; width:100%; }
/* Vista previa como la ficha real de VMC: sin marco gris, galería 443 + tarjeta 311 (DetailCard nativo) a dos columnas;
   la columna de 766 alcanza justo. Solo se apila si el contenedor es más angosto. */
.fl--vmc .fl-prev__page { gap:12px; padding:0; border-radius:0; background:none; box-shadow:none; }
@container (min-width:762px) { .fl--vmc .fl-prev__page { grid-template-columns:443px 311px; gap:8px; justify-content:space-between; } }
.fl--vmc .fl-prev__side { justify-items:stretch; }
.fl--vmc .fl-prev__side .fl-change, .fl--vmc .fl-prev__side .fl-prev__pills { justify-self:center; }

/* ── Cabeceras de bloque · Publicar VMC (16/10 noche): baldosa con ícono (como Tu actividad), título + ayuda y estado a la derecha. */
.fl--vmc .fl-sh { display:grid; grid-template-columns:36px minmax(0,1fr) auto; align-items:center; gap:12px; }
.fl--vmc .fl-sh__ico { display:grid; place-items:center; width:36px; height:36px; border-radius:12px; color:#5A35C2; background:linear-gradient(135deg,#F5F0FF,#EDE6FF); box-shadow:inset 0 1px 0 #fff, inset 0 0 0 1px rgba(132,96,229,.14); }
.fl--vmc .fl-sh__txt { min-width:0; display:grid; gap:2px; }
.fl--vmc .fl-sh__txt small { font-size:.875rem; color:var(--f-muted); }
.fl--vmc .fl-sh .fl-sub__t { font-size:1rem; }
.fl--vmc .fl-sh__st { display:inline-flex; align-items:center; gap:4px; height:24px; padding:0 10px; border-radius:9999px; font-size:.75rem; font-weight:700; white-space:nowrap; color:#9A4A0F; background:#FFF1E2; }
.fl--vmc .fl-sh__st.is-ok { color:#3B1782; background:#F5F0FF; animation:fl-pop .36s cubic-bezier(.16,1,.3,1); }
.fl--vmc .fl-sh__st.is-opt { font-weight:600; color:#6B6878; background:#F3F2F6; }
@media (prefers-reduced-motion:reduce) { .fl--vmc .fl-sh__st.is-ok { animation:none; } }

/* Datos de la publicación sin hueco: precio y atajos a todo el ancho; placa y cilindrada en dos columnas iguales. */
.fl--vmc .fl-grid--datos { grid-template-columns:repeat(2, minmax(0,1fr)); }
.fl--vmc .fl-field--price .fl-input, .fl--vmc .fl-field--price .pinput, .fl--vmc .fl-quick { max-width:none; }
@media (max-width:640px) { .fl--vmc .fl-grid--datos { grid-template-columns:minmax(0,1fr); } }
.fl.fl--vmc .fl-card .fl-grid.fl-grid--datos { grid-template-columns:repeat(2, minmax(0,1fr)); }
@media (max-width:640px) { .fl.fl--vmc .fl-card .fl-grid.fl-grid--datos { grid-template-columns:minmax(0,1fr); } }

/* ── Publicar VMC sin paso Pago (como vmcsubastas.com): costo junto a «¡Publica ahora!» y aviso de saldo insuficiente. */
.fl--vmc .fl-left.is-cost { cursor:default; color:#6B6878; font-weight:600; }
.fl-modal { position:fixed; inset:0; z-index:50; display:grid; place-items:center; padding:16px; background:rgba(16,0,48,.55); animation:fl-fade .2s ease-out; }
.fl-modal__box { position:relative; width:min(400px,100%); display:grid; justify-items:center; gap:12px; padding:32px 24px 24px; border-radius:24px; background:#fff; text-align:center; box-shadow:0 24px 60px rgba(16,0,48,.35); animation:fl-pop .32s cubic-bezier(.16,1,.3,1); }
.fl-modal__box h2 { margin:4px 0 0; font-size:1.0625rem; font-weight:800; text-transform:uppercase; letter-spacing:.02em; color:#3B1782; }
.fl-modal__box p { margin:0; font-size:.875rem; color:#3B1782; }
.fl-modal__box dl { width:100%; margin:4px 0; display:grid; }
.fl-modal__box dl div { display:flex; justify-content:space-between; padding:8px 0; font-size:.875rem; }
.fl-modal__box dt { color:#6B6878; } .fl-modal__box dd { margin:0; font-weight:700; color:#00A8AB; font-variant-numeric:tabular-nums; }
.fl-modal__box dl .is-total { margin-top:4px; border-top:1px solid #ECECEE; padding-top:12px; } .fl-modal__box dl .is-total dd { color:#ED8936; }
.fl-modal__box > button:not(.fl-modal__x) { width:100%; max-width:260px; }
.fl-modal__x { all:unset; cursor:pointer; position:absolute; top:14px; right:14px; display:grid; place-items:center; width:32px; height:32px; border-radius:50%; color:#ED8936; box-shadow:inset 0 0 0 1.5px #ED8936; }
.fl-modal__x:focus-visible { outline:2px solid #8460E5; outline-offset:2px; }
@media (max-width:640px) { .fl--vmc .fl-left.is-cost { font-size:.75rem; } }
@media (prefers-reduced-motion:reduce) { .fl-modal, .fl-modal__box { animation:none; } }
.fl-modal__box > button:not(.fl-modal__x) { max-width:300px; white-space:nowrap; }
/* Cabeceras de bloque con los íconos de vidrio esmerilado (Vidrio.tsx), sin baldosa: como las secciones de Tu actividad. */
.fl--vmc .fl-sh__ico { width:36px; height:36px; border-radius:0; background:none; box-shadow:none; }

/* Versión única y Precio de lista (VMC): superficie de Concorde (blanco, borde degradado y sombra de AmountOption) en vez del relleno lila */
.fl--vmc .fl-only, .fl--vmc .fl-msrp--ds { border:1px solid transparent; background:linear-gradient(#fff,#fff) padding-box, linear-gradient(335deg,#8460E5 0%,#FFF8F1 100%) border-box; box-shadow:0 0 16px 4px rgba(0,0,0,.06); }
.fl--vmc .fl-only { gap:12px; }
.fl--vmc .fl-only b { font-weight:600; color:var(--f-ink); }
.fl--vmc .fl-only small { margin-left:auto; font-size:.75rem; color:var(--f-muted); }
.fl--vmc .fl-msrp--ds { gap:12px; padding:12px 16px; }
.fl--vmc .fl-msrp__t { flex:1; display:grid; gap:2px; }
.fl--vmc .fl-msrp__t small { font-size:.75rem; color:var(--f-muted); }
.fl--vmc .fl-msrp__t b { font-size:1.25rem; font-weight:700; line-height:1.2; color:var(--f-ink); font-variant-numeric:tabular-nums; }
.fl--vmc .fl-msrp .fl-inline { font-size:.875rem; font-weight:600; color:var(--f-ink); }

/* Pista de km (AVT): promedio a la izquierda y la diferencia como etiqueta con el color de AVT (bajo = teal, sobre = naranja, ≈ = morado) */
.fl-kmh { display:flex; flex-wrap:wrap; align-items:center; justify-content:space-between; gap:4px 8px; }
.fl-kmh b { font-weight:600; }
.fl--vmc .fl-kmh b { color:var(--f-text); }
.fl--vmc .fl-kmh__f { color:#8E89A0; }
.fl--vmc .fl-kmh__d { display:inline-flex; align-items:center; height:20px; padding:0 8px; border-radius:9999px; font-size:.75rem; font-weight:600; white-space:nowrap; font-variant-numeric:tabular-nums; }
/* Upgrade DS: blanco con el borde degradado de los botones de Concorde (en vivo naranja→lila, negociable teal→lila); texto del mismo tono oscurecido a ≥ 4.5:1 */
.fl--vmc .fl-kmh__d { border:1px solid transparent; background:linear-gradient(#fff,#fff) padding-box, var(--kmh-g) border-box; }
.fl--vmc .fl-kmh__d.is-up { color:#B25614; --kmh-g:linear-gradient(90deg,#ED8936,#8460E5); }
.fl--vmc .fl-kmh__d.is-down { color:#006E70; --kmh-g:linear-gradient(90deg,#00A8AB,#8460E5); }
.fl--vmc .fl-kmh__d.is-avg { color:#5A35C2; --kmh-g:linear-gradient(90deg,#AE8EFF,#8460E5); }
.fl--vmc .fl-msrp__ico { display:grid; place-items:center; flex:none; }

/* Precio de lista (19/10): mismo fondo y paleta que el héroe del resultado (Revela .rva-hero / .rva-two) */
.fl--vmc .fl-msrp--ds { border:0; color:#fff; background:radial-gradient(90% 160% at 100% 0%, #5A35C2 0%, #3B1782 48%, #22005C 100%); box-shadow:0 8px 24px rgba(34,0,92,.2); }
.fl--vmc .fl-msrp--ds .fl-msrp__t small { color:#CFBAFF; }
.fl--vmc .fl-msrp--ds .fl-msrp__t b { color:#fff; }
.fl--vmc .fl-msrp--ds .fl-inline { color:#fff; }
.fl--vmc .fl-msrp--ds .fl-inline:focus-visible { outline-color:#CFBAFF; }
.fl--vmc .fl-msrp--ds .vd { --solid:#AE8EFF; --glass:#E8DEFF; }

/* Precio de compra (AVT, con 3+ dueños): bloque bajo Historial con la forma de Campo VMC */
.fl--vmc .fl-buy { display:grid; gap:8px; padding:24px 0; border-bottom:1px solid var(--f-hair); }
.fl--vmc .fl-buy h3 { margin:0; font-size:.875rem; font-weight:600; color:var(--f-ink); }
.fl--vmc .fl-buy .fl-hint { margin:0 0 8px; }
.fl--vmc .fl-buy__when { display:grid; grid-template-columns:1fr 1fr; gap:16px; margin-top:8px; }

/* Valor estimado (19/10): fondo y paleta del héroe del resultado (Revela .rva-hero), como el Precio de lista */
.fl--vmc .fl-live.fl-live--ds { color:#fff; background:radial-gradient(90% 140% at 100% 0%, #5A35C2 0%, #3B1782 48%, #22005C 100%); box-shadow:0 12px 32px rgba(34,0,92,.25); }
.fl--vmc .fl-live__id small { color:#CFBAFF; }
.fl--vmc .fl-live__id span { color:rgba(255,255,255,.8); }
.fl--vmc .fl-live__v b { color:#fff; }
.fl--vmc .fl-live__v em, .fl--vmc .fl-live__v em.is-down { color:#fff; background:rgba(255,255,255,.12); box-shadow:inset 0 0 0 1px rgba(255,255,255,.14); }
.fl--vmc .fl-live__p { border-top-color:rgba(255,255,255,.12); }
.fl--vmc .fl-live__p .pprogbar { background:rgba(255,255,255,.14); }
.fl--vmc .fl-live__p small span { color:#CFBAFF; }
.fl--vmc .fl-live__p small b { color:#fff; }
/* Jerarquía del héroe (.rva-car · .rva-meta · .rva-h · .rva-big) y contraste en todos los textos (≥ 4.5:1 sobre #3B1782) */
.fl--vmc .fl-live__id b { font-size:1rem; font-weight:700; color:#fff; }
.fl--vmc .fl-live__id span { font-size:.75rem; color:#CFBAFF; }
.fl--vmc .fl-live__v small { font-size:.75rem; font-weight:600; color:#E8DEFF; }
.fl--vmc .fl-live__v b { font-size:2rem; font-weight:700; letter-spacing:-0.03em; color:#fff; }
.fl--vmc .fl-live__v em.is-up, .fl--vmc .fl-live__v em.is-down { color:#fff; background:rgba(255,255,255,.12); box-shadow:inset 0 0 0 1px rgba(255,255,255,.2); }
.fl--vmc .fl-live__p small span { color:#CFBAFF; }

/* «✓ típico» (AVT): nota secundaria, no etiqueta — texto lila con el ✓ de AVT (el check naranja queda solo para «grupo completo»), sin borde ni relleno para no competir con las opciones */
.fl--vmc .fl-typical { display:inline-flex; align-items:center; gap:4px; margin-left:8px; padding:0; font-size:.75rem; font-weight:500; color:#5A35C2; background:none; vertical-align:middle; }
/* Grupo completo (AVT: check_circle junto al título, sin texto): check naranja de Concorde que entra con un pop */
.fl--vmc .fl-sub__t { display:inline-flex; align-items:center; gap:8px; }
.fl--vmc .fl-gdone { display:inline-grid; animation:fl-pop .35s cubic-bezier(.2,1.4,.4,1) both; }
@keyframes fl-pop { from { opacity:0; transform:scale(.5); } }
@media (prefers-reduced-motion:reduce) { .fl--vmc .fl-gdone { animation:none; } }
/* Valor estimado: ícono de vidrio de precio como en las tarjetas del resultado (.rva-two) */
.fl--vmc .fl-live__id { display:flex; align-items:center; gap:12px; }
.fl--vmc .fl-live__id > div { display:grid; gap:2px; min-width:0; }
.fl--vmc .fl-live__ico { display:grid; place-items:center; flex:none; }
.fl--vmc .fl-live__ico .vd { --solid:#AE8EFF; --glass:#E8DEFF; }

/* Valor estimado · precisión (19/10): ProgressBar de Concorde tal cual (riel hundido para fondo oscuro, gradiente primary),
   sin los 12 tramos; en una sola fila «Precisión ─── 3 de 12 detalles» para que la tarjeta sticky tape menos */
.fl--vmc .fl-live__p { grid-template-columns:auto 1fr auto; align-items:center; gap:12px; padding-top:16px; }
.fl--vmc .fl-live__p small { display:contents; }
.fl--vmc .fl-live__p small span { order:0; } .fl--vmc .fl-live__p .pprogbar { order:1; } .fl--vmc .fl-live__p small b { order:2; }
.fl--vmc .fl-live__p .pprogbar { height:8px; border-radius:9999px; -webkit-mask:none; mask:none; background:rgba(0,0,0,.22); box-shadow:inset 0 1px 0 rgba(255,255,255,.06), inset 0 2px 4px rgba(0,0,0,.35); }
.fl--vmc .fl-live__p .pprogbar__fill { border-radius:9999px; background:linear-gradient(135deg, #FFFFFF 0%, #F4AC59 22%, #8460E5 74.5%, #FFFFFF 100%); }
/* Borde de vidrio como .rva-two, para que la tarjeta no sea un bloque plano */
.fl--vmc .fl-live.fl-live--ds { box-shadow:inset 0 0 0 1px rgba(255,255,255,.1), 0 12px 32px rgba(34,0,92,.25); }

/* «✓ típico» (19/10): mini ConditionPill — mismo relleno lila, brillo y borde degradado que la opción elegida, a 20 px.
   Gradiente oscurecido (#7B58E0 → #4A26B0) para texto blanco ≥ 4.5:1 */
.fl--vmc .fl-typical { height:20px; padding:0 8px; gap:4px; border-radius:9999px; font-size:.6875rem; font-weight:600; color:#fff;
  border:1px solid transparent; background:linear-gradient(180deg,rgba(255,255,255,.18),rgba(255,255,255,0) 55%) padding-box, linear-gradient(135deg,#7B58E0,#4A26B0) padding-box, linear-gradient(135deg,#CFBAFF,#fff 40%,#AE8EFF) border-box;
  box-shadow:0 2px 4px rgba(59,23,130,.18); }

/* 19/10 · «típico» (AVT) con jerarquía calmada: el origen vive en la respuesta (marca de vidrio dentro de la opción elegida)
   y el texto de AVT aparece una sola vez por grupo, como nota secundaria a la derecha del título */
.fl--vmc .fl-sh { display:flex; align-items:center; gap:12px; }
.fl--vmc .fl-gtip { margin-left:auto; font-size:.75rem; font-weight:500; color:var(--f-muted); white-space:nowrap; }
.fl--vmc .fl-pill__tip { display:inline-flex; align-items:center; height:18px; margin-left:8px; padding:0 6px; border-radius:9999px; font-size:.6875rem; font-weight:600; color:#fff;
  background:rgba(255,255,255,.2); box-shadow:inset 0 0 0 1px rgba(255,255,255,.35); vertical-align:middle; }
@media (max-width:640px) { .fl--vmc .fl-sh { flex-wrap:wrap; } .fl--vmc .fl-gtip { flex-basis:100%; margin-left:48px; } }

/* Precisión por tramos (vuelve, pedido 19/10): 12 tramos sobre el riel hundido de Concorde */
.fl--vmc .fl-live__p .pprogbar, .fl--vmc .fl-live__p .pprogbar__fill { border-radius:2px; }
.fl--vmc .fl-live__p .pprogbar {
  -webkit-mask:repeating-linear-gradient(90deg, #000 0 calc((100% - 44px) / 12), transparent calc((100% - 44px) / 12) calc((100% - 44px) / 12 + 4px));
          mask:repeating-linear-gradient(90deg, #000 0 calc((100% - 44px) / 12), transparent calc((100% - 44px) / 12) calc((100% - 44px) / 12 + 4px)); }
.fl--vmc .fl-opts .fl-pill small.fl-pill__tip { font-size:.6875rem; font-weight:600; color:#fff; opacity:1; background:rgba(255,255,255,.22); box-shadow:inset 0 0 0 1px rgba(255,255,255,.4); }

/* 19/10 · DS: nota del grupo con la ⓘ de Concorde (InfoIcon, trazo naranja→lila) y texto en lila del DS */
.fl--vmc .fl-gtip { display:inline-flex; align-items:center; gap:6px; font-size:.75rem; font-weight:600; color:#5A35C2; }
/* Marca «TÍPICO» dentro de la opción: construcción de BadgeStatus (mayúsculas, relleno + borde degradado, anillo y blur),
   invertida en blanco→lila para que se lea sobre la ConditionPill rellena. 10 px en vez de 9 (caso DS pendiente) */
.fl--vmc .fl-opts .fl-pill small.fl-pill__tip { height:18px; margin-left:8px; padding:0 7px; border:1px solid transparent; border-radius:9999px;
  font-size:.625rem; font-weight:700; letter-spacing:.07em; text-transform:uppercase; color:#5A35C2; opacity:1;
  background:linear-gradient(135deg,#FFFFFF 0%,#F5F0FF 100%) padding-box, linear-gradient(135deg,#FFFFFF 0%,#CFBAFF 60%,#FFFFFF 100%) border-box;
  box-shadow:0 2px 8px rgba(34,0,92,.25); backdrop-filter:blur(6px); }

/* Pie de Detalles (AVT): Saltar 1/3 · Ver valuación 2/3, mismos 48 px, con los botones de Concorde */
.fl--vmc .fl-foot__pair { display:grid; grid-template-columns:1fr 2fr; gap:12px; width:100%; }
.fl--vmc .fl-foot__pair > * { width:100%; min-width:0; }
/* «Saltar» = acción secundaria neutra (en AVT es gris con borde): outline de Concorde con la paleta lila de .psec
   (borde #CFBAFF → blanco → #AE8EFF) sobre blanco, para que el único naranja del pie sea «Ver valuación» */
.fl--vmc .fl-foot__pair .poutline { color:#3B1782; background-color:#fff; background-image:linear-gradient(180deg,rgba(255,255,255,.1),rgba(255,255,255,0) 55%); text-shadow:none; }
.fl--vmc .fl-foot__pair .poutline::before { padding:1.5px; background:linear-gradient(135deg,#CFBAFF 0%,#FFFFFF 35%,#AE8EFF 65%,#CFBAFF 100%); }
.fl--vmc .fl-foot__pair .poutline::after { background:linear-gradient(144deg,#8460E5,#F5F0FF); }
.fl--vmc .fl-foot__pair .poutline:hover { color:#3B1782; background-image:linear-gradient(180deg,rgba(255,255,255,.1),rgba(255,255,255,0) 55%), linear-gradient(90deg,#fff 0%,#F5F0FF 100%); box-shadow:rgba(59,23,130,.16) 0 6px 18px -4px; }
.fl--vmc .fl-foot__pair .poutline:active { color:#fff; background-image:linear-gradient(156deg,#5A35C2 0%,#3B1782 100%); }
.fl--vmc .fl-foot__pair .poutline:active::before { background:linear-gradient(180deg,#5A35C2,#3B1782); }
.fl--vmc .fl-foot__pair .poutline:focus-visible { outline:2px solid var(--f-focus); outline-offset:3px; }

/* 19/10 · pie de Detalles (impeccable polish): fila completa 1/3 · 2/3 como AVT en todos los anchos (elegido 19/10). Borde de «Saltar» sin el tramo
   blanco de .psec (sobre fondo blanco parecía cortado) */
.fl--vmc .fl-foot__pair .poutline::before { padding:1.5px; background:linear-gradient(135deg,#CFBAFF 0%,#AE8EFF 60%,#8460E5 100%); }


/* 19/10 · Colores del sistema (13/10): teal/cyan solo para lo negociable. En datos: lila = favorable, naranja oscuro = desfavorable,
   gris = neutro. Km bajo el promedio pasa de teal a lila; «≈ Promedio» pasa a neutro */
.fl--vmc .fl-kmh__d.is-down { color:#5A35C2; --kmh-g:linear-gradient(90deg,#AE8EFF,#8460E5); }
.fl--vmc .fl-kmh__d.is-avg { color:#6B6878; --kmh-g:linear-gradient(90deg,#E1E3E2,#C9C6D3); }
/* «Guardar» en la barra del resultado: mismo outline lila que tuvo «Saltar»; el único naranja de la barra es «Publicar» */
.fl--vmc .fl-save.poutline { color:#3B1782; background-color:#fff; background-image:linear-gradient(180deg,rgba(255,255,255,.1),rgba(255,255,255,0) 55%); text-shadow:none; }
.fl--vmc .fl-save.poutline::before { padding:1.5px; background:linear-gradient(135deg,#CFBAFF 0%,#AE8EFF 60%,#8460E5 100%); }
.fl--vmc .fl-save.poutline::after { background:linear-gradient(144deg,#8460E5,#F5F0FF); }
.fl--vmc .fl-save.poutline:hover { color:#3B1782; background-image:linear-gradient(180deg,rgba(255,255,255,.1),rgba(255,255,255,0) 55%), linear-gradient(90deg,#fff 0%,#F5F0FF 100%); box-shadow:rgba(59,23,130,.16) 0 6px 18px -4px; }
.fl--vmc .fl-save.poutline:active { color:#fff; background-image:linear-gradient(156deg,#5A35C2 0%,#3B1782 100%); }
.fl--vmc .fl-save.poutline:active::before { background:linear-gradient(180deg,#5A35C2,#3B1782); }
.fl--vmc .fl-save.poutline:focus-visible { outline:2px solid var(--f-focus); outline-offset:3px; }
.fl--vmc .fl-save.poutline svg { color:#5A35C2; stroke:currentColor; }

/* 19/10 · «De tu valorización»: dato, no aviso. Superficie de AmountOption (como Versión y las tarjetas del resultado),
   vidrio de valorizaciones en vez del check naranja en su recuadro, y «Cambiar» como botón secundario lila (sin chevron naranja) */
.fl--vmc .fl-have--ds { padding:16px 20px; column-gap:16px; border:1px solid transparent; border-radius:16px;
  background:linear-gradient(#fff,#fff) padding-box, linear-gradient(335deg,#8460E5 0%,#FFF8F1 100%) border-box; box-shadow:0 0 16px 4px rgba(0,0,0,.05); }
.fl--vmc .fl-have--ds .fl-have__ico { width:40px; height:40px; border-radius:0; background:none; box-shadow:none; }
.fl--vmc .fl-have--ds .fl-have__ico svg { width:40px; height:40px; }
