const vigente = (m: string, y: number) => { const r = VIGENCIA[m]; return !y || !r || (y >= r[0] && y <= r[1]); };
const YEARS = Array.from({ length: 2026 - 2000 + 1 }, (_, i) => 2026 - i); // AVT: del año actual a 2000
