@keyframes fc-tint-flash { 0%, 35% { background:var(--fc-tint); } 100% { background:transparent; } }

/* Aparece: el cartel morado entra con un fundido de arriba hacia abajo (clip + opacidad), espera 6 s y se va igual, hacia arriba. */
