  background:linear-gradient(135deg, #6E4BD8 0%, #3B1782 100%); color:#fff; box-shadow:0 6px 16px rgba(59,23,130,.25); animation:fc-reveal .45s var(--fc-in) .1s both; }
.fc-appear.is-out .fc-appear__bar { animation:fc-unreveal .3s var(--fc-out) both; }
