@keyframes fc-close { to { grid-template-rows:0fr; opacity:0; } }
.fc-push__card { position:relative; display:grid; grid-template-columns:32px minmax(0,1fr); align-items:center; gap:12px; margin:10px 0 12px; padding:14px 14px 14px 16px; border:1.5px solid transparent; border-radius:14px;
  background:linear-gradient(var(--fc-tint), var(--fc-tint)) padding-box, var(--fc-grad) border-box; }
