  padding:4px 10px 4px 8px; border-radius:9999px; background:var(--fc-tint); box-shadow:inset 0 0 0 1px #E8DEFF; color:#5A35C2; font-size:.75rem; font-weight:600; line-height:1.3; animation:fc-chip-in .3s var(--fc-in) .1s both; }
