.fc-toast__see { flex:none; min-height:36px; padding:0 16px; border:1.5px solid transparent; border-radius:9999px; background:linear-gradient(#fff, #fff) padding-box, var(--fc-grad) border-box; color:var(--fc-ink); font:inherit; font-size:.8125rem; font-weight:700; cursor:pointer; }
