.fc-toast:hover .fc-toast__time, .fc-toast:focus-within .fc-toast__time { animation-play-state:paused; }
@keyframes fc-toast-in { from { opacity:0; transform:translateY(12px); } }
@keyframes fc-toast-out { to { opacity:0; transform:translateY(8px); } }
