/* Actual: lo que hay hoy, tal cual (brillo cian de 2.4 s), para comparar. */
html[data-foco="actual"][data-foco-fase] [data-foco-row] > .fr.fr { border-radius:12px; animation:fr-flash 2.4s ease-out .2s both; }

/* ── Panel del lab: arriba a la derecha, sobre el velo, sobre el simulador del vendedor ─────────── */
/* 420 px: a 1280 de ancho no tapa la columna de Tu actividad (termina en x 823). */
