/* ── Móvil ───────────────────────────────────────────────────── */
@media (max-width:600px) {
  .fc-panel { top:12px; right:12px; width:calc(100vw - 24px); }
  .fc-panel.f-sw--closed { width:auto; }
  .fc-card { grid-template-columns:32px minmax(0,1fr); padding:14px; }
  .fc-card > .fc-ok { grid-column:1 / -1; justify-self:center; }
  .fc-strip__body, .fc-push__card { grid-template-columns:32px minmax(0,1fr); }
  .fc-strip__body > .fc-ok, .fc-push__card > .fc-ok { grid-column:1 / -1; justify-self:center; }
  .fc-drawer__card > .fc-ok { justify-self:center; }
  .fc-expand { padding-left:0; } .fc-expand > .fc-ok { justify-self:center; }
  .fc-chip { max-width:calc(100% - 96px); margin-left:84px; } /* en móvil el texto de la fila empieza a 84 px */
  .fc-appear__bar { margin-left:0; }
  .fc-toast { flex-wrap:wrap; } .fc-toast p { flex-basis:calc(100% - 120px); }
  .fc-toast__see { order:3; flex-basis:100%; min-height:44px; }
