.g-wallet-dark button { width:100%; }
@media (max-width:829px) { .g-wallet-dark { width:100%; } }

/* ── Tu actividad ─────────────────────────────────────── */
.g-activity { display:grid; gap:20px; padding-top:8px; }
.g-sec { display:grid; gap:14px; padding:20px 24px 12px; background:#fff; border-radius:20px; box-shadow:0 1px 3px rgba(34,0,92,.05), 0 8px 24px rgba(34,0,92,.05); }
