/* ── Fernando+ · Tu actividad v2 ──────────────────────── */
.fa { background:#fff; border-radius:22px; box-shadow:0 1px 3px rgba(34,0,92,.05), 0 10px 30px rgba(34,0,92,.06); overflow:hidden; }
.fs + .fs { border-top:1px solid var(--line); }
.fs { scroll-margin-top:24px; }
.fs__head { display:flex; align-items:center; gap:16px; padding:6px 20px 6px 8px; }
.fs__toggle { all:unset; box-sizing:border-box; flex:1; min-width:0; cursor:pointer; display:flex; align-items:center; gap:16px; padding:14px 12px; border-radius:14px; transition:background-color .15s; }
.fs__toggle:hover { background:var(--vmc-color-vault-100); }
.fs__toggle:focus-visible { outline:2px solid #8460E5; outline-offset:-2px; }
.fs__title { display:flex; align-items:center; gap:10px; flex:none; }
.fs__h { margin:0; flex:1; min-width:0; display:flex; font:inherit; }
.fs__name { font-size:1.125rem; font-weight:800; letter-spacing:-0.01em; color:var(--ink); }
.fs__count { min-width:24px; height:24px; display:inline-grid; place-items:center; padding:0 7px; border-radius:9999px; font-size:.75rem; font-weight:800; color:#5A35C2; background:#F5F0FF; font-variant-numeric:tabular-nums; }
.fs__summary { flex:1; min-width:0; font-size:.8125rem; color:var(--muted); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.fs__thumbs { display:inline-flex; }
.fs__thumbs img { width:28px; height:28px; border-radius:9999px; object-fit:cover; box-shadow:0 0 0 2px #fff; }
.fs__thumbs img + img { margin-left:-8px; }
.fs__chev { margin-left:auto; display:grid; transition:transform .2s cubic-bezier(.2,.8,.2,1); }
.fs__chev { transform:rotate(90deg); } /* acordeón (Accordion de Concorde): cerrado ↓, abierto ↑ */
.fs.is-open .fs__chev { transform:rotate(-90deg); }
.fs__body { display:grid; gap:8px; padding:0 20px 14px; }
.fs__more { display:none; }
.f-src .fs__more { display:flex; padding:6px 0 2px; } /* Fuente: «Ver todas» al pie de cada sección también en escritorio (Stage 1: conservar el destino) */
.fs__tabs { display:flex; gap:4px; padding:0 0 6px; border-bottom:1px solid var(--line); }
.fs__tabs button { all:unset; cursor:pointer; position:relative; display:inline-flex; align-items:center; gap:6px; padding:8px 12px 10px; font-size:.8125rem; font-weight:700; color:var(--muted); border-radius:10px 10px 0 0; }
.fs__tabs button span { font-size:.6875rem; padding:1px 6px; border-radius:9999px; background:color-mix(in srgb,#E1E3E2 60%,#fff); color:color-mix(in srgb,#191C1C 82%,#fff); }
.fs__tabs button:hover { color:var(--ink); }
.fs__tabs button[aria-selected="true"] { color:var(--ink); }
.fs__tabs button[aria-selected="true"]::after { content:""; position:absolute; left:10px; right:10px; bottom:-7px; height:3px; border-radius:9999px; background:linear-gradient(90deg,#F4AC59,#8460E5); }
.fs__tabs button[aria-selected="true"] span { background:#F5F0FF; color:#5A35C2; }
.fs__tabs button:focus-visible { outline:2px solid #8460E5; outline-offset:2px; }
.fs__list { display:grid; margin:0 -10px; }
.fs__list > div + div .fr { box-shadow:0 -1px 0 var(--line); }
/* Guía de demo: baja el ruido visual de las otras propuestas; la fila señalada y
   su flecha permanecen a plena opacidad. */
.fs--guided .fs__list > div { opacity:.22; transition:opacity .2s ease; }
.fs--guided .fs__list > div.g-row-guided { position:relative; z-index:2; opacity:1; }
.fs__empty { display:flex; justify-content:space-between; align-items:center; gap:16px; flex-wrap:wrap; padding:4px 0 8px; }
.fs__empty p { margin:0; max-width:56ch; font-size:.875rem; line-height:1.5; color:color-mix(in srgb,#191C1C 82%,#fff); }
.fs--compras .fs__empty, .fs--participaciones .fs__empty { justify-content:center; text-align:center; }

.fr { all:unset; box-sizing:border-box; position:relative; width:100%; cursor:pointer; display:grid; grid-template-columns:64px minmax(0,1fr) auto 20px; gap:14px; align-items:center; padding:10px; border-radius:12px; transition:background-color .15s; }
.fr__demo-arrow { position:absolute; z-index:3; left:4px; top:50%; display:grid; place-items:center; width:46px; height:38px; border-radius:999px; color:#ED8936; background:rgba(255,255,255,.96); box-shadow:0 3px 10px rgba(112,52,11,.30); transform:translateY(-50%); animation:fr-guide 1s ease-in-out infinite alternate; pointer-events:none; }
.fr__demo-arrow svg { width:40px; height:32px; }
@keyframes fr-guide { from { transform:translate(-3px,-50%); } to { transform:translate(5px,-50%); } }
.fs__list > div:hover + div .fr { box-shadow:none; }
.fr:focus-visible { outline:2px solid #8460E5; outline-offset:-2px; }
.fr:active { transform:scale(.996); }
.fr img { width:64px; height:48px; object-fit:cover; border-radius:10px; }
.fr__main { display:grid; gap:2px; min-width:0; }
.fr__name { display:flex; align-items:center; gap:8px; font-size:.9375rem; font-weight:700; color:var(--ink); }
.fr__new { display:inline-flex; align-items:center; gap:5px; font-size:.6875rem; font-weight:800; letter-spacing:.06em; text-transform:uppercase; color:#CC00FF; }
.fr__new { background:linear-gradient(90deg,#CC00FF,#FF0066); -webkit-background-clip:text; background-clip:text; color:transparent; }
.fr__new i { width:7px; height:7px; border-radius:9999px; background:linear-gradient(135deg,#CC00FF,#FF0066); box-shadow:0 0 6px rgba(204,0,255,.6), 0 0 10px rgba(255,0,102,.35); }
.fr.is-new { animation:g-arrive .9s cubic-bezier(.16,1,.3,1) both; }
.fr.is-new.is-relocated { animation:none; }
.fr:hover, .fr.is-new:hover { background:var(--vmc-color-orange-200); }
/* Regreso de Valorizar/Publicar: el mismo gesto de llegada que una acción
   importante, pero sin una pantalla de «terminado». El trazo desaparece y la
   fila queda como parte normal de Mi Garaje. */
.fr.is-arrival--valorizacion, .fr.is-arrival--publicacion { box-shadow:0 0 0 4px rgba(0,168,171,.10),0 8px 20px rgba(90,53,194,.14); animation:fr-arrival-pulse 8.2s cubic-bezier(.16,1,.3,1) both; }
/* El trazo es una capa, no un border: así no achica el área interna ni desplaza
   el CTA cuando la card recién aterriza en Mi Garaje. */
.fr.is-arrival--valorizacion::after, .fr.is-arrival--publicacion::after { content:""; position:absolute; z-index:2; inset:0; padding:2px; border-radius:inherit; pointer-events:none; background:linear-gradient(112deg,#00B7BA 0%,#8460E5 52%,#CC00FF 100%); -webkit-mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0); -webkit-mask-composite:xor; mask-composite:exclude; }
@keyframes fr-arrival-pulse { 0% { box-shadow:0 0 0 0 rgba(204,0,255,.26); } 24% { box-shadow:0 0 0 6px rgba(0,168,171,.12),0 8px 20px rgba(90,53,194,.14); } 72% { box-shadow:0 0 0 4px rgba(204,0,255,.08),0 8px 20px rgba(90,53,194,.14); } 100% { box-shadow:0 0 0 0 transparent; } }
/* Fila nueva: gradiente del countdown del chat (ProgressBar «rainbow»: #CC00FF→#FF0066) + texto en negrita para separarla de las demás (sin fondo propio). */
.fr.is-new .fr__name { font-weight:800; }
.fr.is-new .fr__meta { font-weight:700; color:var(--ink); }
.fr__meta { font-size:.8125rem; color:color-mix(in srgb,#191C1C 74%,#fff); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; font-variant-numeric:tabular-nums; }
.fr__step { font-size:.75rem; font-weight:700; color:#5A35C2; }
.fr__side { display:grid; justify-items:end; gap:4px; }
/* La píldora EN VIVO ocupa el alto de la fila: así queda centrada respecto de
   foto, nombre y detalle, en lugar de pegarse al borde superior. */
.fr__side:has(.badgestatus) { align-self:stretch; align-items:center; }
.fr__side small { font-size:.75rem; color:var(--muted); font-variant-numeric:tabular-nums; }
/* Contrapropuesta nueva: el plazo vive a la derecha de la fila; no se confunde
   con «Ahora», que marca solamente la llegada de la notificación. */
.fr__name .fr__timer { display:inline-flex; flex:none; align-items:center; margin-left:6px; padding-left:8px; border-left:1px solid #D9D6E1; }
.fr.is-new .fr__name .fr__timer { border-left:2px solid #191C1C; }
.fr__timer .cp-count { justify-items:end; gap:0; }
.fr__timer .cp-count small { display:none; }
.fr__timer .cp-count b { font-family:inherit; font-size:.75rem; font-weight:inherit; line-height:1.2; color:inherit; white-space:nowrap; }

@media (max-width:829px) {
