  .fr { grid-template-columns:56px minmax(0,1fr) 18px; grid-template-areas:"img main chev" "img side chev"; gap:4px 12px; align-items:start; }
  /* Una valorización no tiene chevron ni estado debajo del texto: su CTA vive
     en la misma fila y se centra respecto de la miniatura y las dos líneas. */
  .fr.fr--publishable { grid-template-columns:56px minmax(0,1fr) auto; grid-template-areas:"img main side"; align-items:center; }
  .fr--publishable .fr__side { grid-area:side; align-self:center; min-height:44px; }
