/* ══ Pulso Fuente · auditoría de jerarquía (13/10) ══════════════════════════════════════════════
   Escala: Display 40/800 · Headline 24/800 · Title 18/800 · Body fuerte 15/600 · Label 14/600 (Concorde label-md)
   · Body 14/400 · Caption 12/600. Pesos: 800 títulos · 600 etiquetas y nombres · 400 detalle.
   Texto: morado de marca (principal) + un solo gris (--muted). Espacios en múltiplos de 8 (4 dentro de piezas chicas).
   Cyan queda para NEGOCIABLE (Concorde): lo «bueno» y lo completado ya no lo usan. */
/* Headline */
.f-src .f-wallet__bal dd, .f-src .f-wallet__bal div + div dd { font-size:1.5rem; font-weight:800; }
.f-src .f-wallet__bal dd small { font-size:.875rem; font-weight:600; }
/* Title 18/800 */
.f-src .fs__name, .f-src .f-act__text b, .f-src .f-wallet h2, .f-src .f-acct__stat:not(.f-acct__me) .f-acct__v b { font-size:1.125rem; font-weight:800; }
/* Body fuerte 15/600 */
.f-src .f-acct__me .f-acct__v b { font-size:.9375rem; font-weight:600; }
/* Una fila se lee de un solo peso: completa en light al verla y completa en bold
   mientras sea una novedad. No mezclar el nombre fuerte con los metadatos tenues. */
.f-src .fr__name { font-size:.9375rem; font-weight:400; }
.f-src .fr.is-new .fr__name { font-weight:700; color:#191C1C; }
.f-src .f-acct__passname { font-size:.9375rem; font-weight:800; }
/* Wallet (14/10): ghost de Concorde, la variante para fondo oscuro; en una línea y secundaria frente a «Publicar». */
.f-src .f-wallet .psec { width:100%; font-size:.9375rem; white-space:nowrap; gap:8px; } .f-src .f-wallet .psec svg { width:20px; height:20px; flex:none; }
.f-src .f-wallet .f-wallet__acquire-circle { flex:none; display:grid; place-items:center; width:26px; height:26px; border-radius:50%; background:rgba(255,255,255,.34); box-shadow:inset 0 0 0 1px rgba(255,255,255,.32),0 1px 3px rgba(34,0,92,.18); color:#fff; font-family:var(--vmc-font-mono,ui-monospace,monospace); font-size:10px; font-weight:800; letter-spacing:-.04em; line-height:1; text-shadow:0 1px 2px rgba(34,0,92,.42); }
/* Label 14/600 */
.f-src .fs__tabs button, .f-src .f-wallet header a, .f-src .f-acct__passcta, .f-src .f-only { font-size:.875rem; font-weight:600; }
/* Body 14/400 */
.f-src .fr__meta, .f-src .fs__summary, .f-src .f-act__text small, .f-src .f-acct__passmsg, .f-tip__body { font-size:.875rem; font-weight:400; }
