.f-src .fr.is-new .fr__meta { font-weight:700; color:var(--ink); }
.f-src .fr.is-sent .fr__name { font-weight:400; }
.f-src .fr.is-unread .fr__name, .f-src .fr.is-unread .fr__meta { font-weight:700; color:#191C1C; }
.f-src .fr.is-regular:not(.is-new):not(.is-unread) .fr__name { font-weight:400; }
.f-src .fr.is-detail-strong .fr__name, .f-src .fr.is-detail-strong .fr__meta, .f-src .fr.is-detail-strong .fr__side small { font-weight:700; color:#191C1C; }
.f-src .fr__side .fr__due { font-weight:700; color:#191C1C; }
.f-tip__body li b { font-weight:600; }
/* Caption 12/600 */
.f-src .f-acct__k, .f-src .fs__count, .f-src .fs__tabs button span, .f-src .fs__act, .f-src .f-only b, .f-src .g-status, .f-src .fr__step, .f-src .f-wallet__last b, .f-src .g-newcount { font-size:.75rem; font-weight:600; }
.f-src .f-wallet__last span, .f-src .fr__side small, .f-src .f-wallet__bal dt { font-size:.75rem; font-weight:400; }
.f-src .fr.is-new .fr__side small, .f-src .fr.is-unread .fr__side small { font-weight:700; color:#191C1C; }
/* Leídas: todo va en el mismo light real (300), incluso el nombre, el detalle y el vencimiento.
   Solo is-new/is-unread es una notificación y por eso puede usar bold. */
.f-src .fr:not(.is-new):not(.is-unread):not(.is-detail-strong) .fr__name,
.f-src .fr:not(.is-new):not(.is-unread):not(.is-detail-strong) .fr__meta,
.f-src .fr:not(.is-new):not(.is-unread):not(.is-detail-strong) .fr__side small { font-weight:300; }
.f-src .g-status--action { font-weight:800; }
.f-src .fr__new span { font-size:.75rem; }
/* Un solo gris de texto */
.f-src .g-status--wait, .f-src .g-status--done { color:var(--muted); background:color-mix(in srgb,#E1E3E2 60%,#fff); }
/* Riesgo: el estado bueno es el termómetro lleno en morado, no el cyan (Concorde: cyan = negociable) */
.f-rep, .f-rep.is-bajo, .f-rep.is-regular { --rep:#8460E5; --rep-ink:#3B1782; }
/* Espacios en la grilla de 8 */
.f-src .f-head { gap:16px; }
.f-src__main { gap:40px; }
.f-src .g-activity { gap:16px; }
.f-src .fr { padding:12px; gap:16px; }

/* ── Notificación de sección (13/10): número en círculo magenta (badge) + texto corto en magenta, sin píldora. */
.g-sr { position:absolute; width:1px; height:1px; overflow:hidden; clip-path:inset(50%); white-space:nowrap; }
.f-src .fs__act, .f-src .fs__act--live { height:auto; padding:0; gap:6px; background:none; box-shadow:none; border:0; color:var(--mg-text); font-size:.75rem; font-weight:600; }
.f-src .fs__act > b { min-width:20px; height:20px; display:inline-grid; place-items:center; padding:0 6px; border-radius:9999px; font-size:.75rem; font-weight:800; color:#fff; background:var(--mg-ink); box-shadow:0 0 0 2px #fff, 0 2px 6px rgba(204,0,255,.35); font-variant-numeric:tabular-nums; }
.f-acct__passname em { margin-left:6px; padding:1px 7px; border-radius:9999px; font-style:normal; font-size:.75rem; font-weight:800; letter-spacing:.04em; color:#22005C; background:#FBC47D; }

/* ── Vista rápida: un solo scroll (13/10). Todo el panel desliza junto (foto, título, propuesta); solo las acciones quedan
   pegadas abajo y la página de atrás no se mueve mientras el panel está abierto. */
.g-qv__panel { display:flex; flex-direction:column; overflow-y:auto; overscroll-behavior:contain; }
.g-qv__body { overflow:visible; flex:1 0 auto; }
.g-qv__foot { position:sticky; bottom:0; z-index:2; background:#fff; }
.g-qv .np__foot { bottom:0; z-index:2; }
html:has(dialog.g-qv[open]) { overflow:hidden; }
/* Si el contenido es corto, las acciones bajan al borde inferior del panel (sin hueco debajo). */
.g-qv__body { display:flex; flex-direction:column; }
.g-qv .np { flex:1; display:flex; flex-direction:column; }
.g-qv .np__foot { margin-top:auto; }
.g-qv__foot { margin-top:auto; }

/* ══ Mi Wallet · jerarquía (14/10): título → saldos → acción. «Transacciones» baja a enlace secundario,
   saldos en dos columnas iguales con la misma línea base, y la acción separada por aire y un divisor. */
.f-src .f-wallet { gap:0; padding:20px 20px 18px; }
.f-src .f-wallet header { margin-bottom:16px; }
.f-src .f-wallet header a { font-size:.8125rem; font-weight:600; color:rgba(255,255,255,.72); }
.f-src .f-wallet header a .g-chev { color:currentColor; }
.f-src .f-wallet header a:hover { color:#fff; }
.f-src .f-wallet__bal { grid-template-columns:1fr 1fr; align-items:end; }
.f-src .f-wallet__bal dd, .f-src .f-wallet__bal div + div dd { font-size:1.5rem; padding-top:0; }
.f-src .f-wallet__bal div + div { padding-left:20px; }
.f-src .f-wallet__bal { padding-bottom:20px; border-bottom:1px solid rgba(255,255,255,.14); }
.f-src .f-wallet > button { margin-top:18px; }

/* ── Pulso Fuente · estados (14/10). La píldora queda solo para Concorde (BadgeStatus EN VIVO / PRÓXIMA).
   El resto del estado es texto: gris si toca esperar, magenta si te toca actuar. Sin estado cuando la sección
   o el paso ya lo dicen (Mis valorizaciones, Mis publicaciones). */
.f-src .g-status:not(.g-status--neg) { height:auto; padding:0; background:none; }
.f-src .g-status--wait, .f-src .g-status--done, .f-src .g-status--progress { color:var(--muted); }


/* ── Pulso Fuente · Wallet plana (14/10): sin el brillo naranja (se mezclaba en marrón y competía con «Publicar»).
   Degradado de Concorde (TabSelector activo). */
.f-src .f-wallet { background:linear-gradient(160deg,#3B1782 0%,#22005C 100%); }
.f-src .f-wallet::before { display:none; }

/* ══ Pulso Fuente · movimiento y claridad (14/10, pedido de Julio vía Cobblepot)
   Curva y duración: las que Concorde repite en sus componentes (0.2s cubic-bezier(.25,.8,.25,1)); no hay tokens de movimiento aún. */
.f-src { --mg-ease:cubic-bezier(.25,.8,.25,1); }
/* Acordeón: altura y opacidad, sin rebote ni filas escalonadas. El cuerpo queda montado e inert cuando está cerrado. */
.f-src .fs__wrap { display:grid; grid-template-rows:0fr; opacity:0; overflow:hidden; transition:grid-template-rows .2s var(--mg-ease), opacity .2s var(--mg-ease); }
.f-src .fs.is-open .fs__wrap { grid-template-rows:1fr; opacity:1; }
.f-src .fs__wrap > .fs__body { min-height:0; overflow:hidden; }
/* Filtro: reacomodo de 200 ms; las filas que salen solo se desvanecen (sin escala). */
::view-transition-group(*) { animation-duration:.2s; animation-timing-function:cubic-bezier(.25,.8,.25,1); }
::view-transition-old(*), ::view-transition-new(*) { height:100%; object-fit:none; object-position:left top; }
/* Encabezado de sección: total junto al título; lo que pide acción a la derecha, antes de la flecha, visible plegado o abierto. */
.f-src .fs__toggle { grid-template-columns:minmax(0,1fr) auto auto 20px; }
.f-src .fs__summary { order:2; text-align:right; }
.f-src .fs__chips { order:3; justify-self:end; }
.f-src .fs__chev { order:4; grid-column:auto; }
@media (max-width:829px) {
  .f-src .fs__toggle { grid-template-columns:minmax(0,1fr) auto 20px; }
  .f-src .fs__chips { grid-column:2; grid-row:1; } .f-src .fs__chev { grid-column:3; grid-row:1; } .f-src .fs__summary { grid-column:1 / -1; grid-row:2; text-align:left; }
}
/* Publicidad: rotulada, con el espacio reservado; un brillo del borde al aparecer y luego quieta (la Wallet no se mueve). */
.f-ad { display:grid; gap:6px; }
.f-ad__k { font-size:.75rem; font-weight:600; color:var(--muted); }
.f-ad__slot { position:relative; display:grid; place-content:center; gap:4px; aspect-ratio:6 / 5; border-radius:20px; text-align:center; color:var(--muted); background:#fff; box-shadow:inset 0 0 0 1px var(--line); }
.f-ad__slot span { font-size:.875rem; font-weight:600; color:var(--ink); }
.f-ad__slot small { font-size:.75rem; }
.f-ad__slot::before { content:""; position:absolute; inset:0; padding:1.5px; border-radius:inherit; pointer-events:none;
  background:linear-gradient(110deg, transparent 35%, #FBC47D 45%, #AE8EFF 55%, transparent 65%) 200% 0 / 300% 100% no-repeat;
  -webkit-mask:linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0); -webkit-mask-composite:xor; mask-composite:exclude;
  animation:f-ad-shine 1.6s .6s var(--mg-ease) 1 both; }
@keyframes f-ad-shine { from { background-position:200% 0; } to { background-position:-100% 0; } }
@media (prefers-reduced-motion:reduce) { .f-src .fs__wrap { transition:none; } .f-ad__slot::before { animation:none; opacity:0; } ::view-transition-group(*) { animation:none; } }
/* Riel más alto que la pantalla: baja con la página hasta mostrar su final y ahí queda fijo (--rail-h lo mide Garaje.tsx).
   Si entra entero, se queda arriba como antes. */
.f-src__rail { top:min(24px, calc(100vh - var(--rail-h, 0px) - 24px)); }
@media (max-width:1100px) { .f-src__rail .f-ad { order:5; } }
.f-ad__k { user-select:none; } /* el rótulo no se selecciona al hacer doble clic cerca */
/* Mobile: no entra título + total + «1 Por responder» en una línea; el aviso baja a la segunda, el total queda junto al título. */
@media (max-width:829px) {
  .f-src .fs__toggle { grid-template-columns:minmax(0,1fr) 20px; }
  .f-src .fs__title { flex-wrap:nowrap; }
  .f-src .fs__chev { grid-column:2; grid-row:1; }
  .f-src .fs__chips { grid-column:1; grid-row:2; justify-self:start; }
  .f-src .fs__summary { grid-column:1; grid-row:3; }
}

/* ══ Revisión de Julio (14/10, segunda ronda) ══════════════════════════════════════════════════════
   Recomendados: OfferShelf de Concorde bajo Tu actividad. Mide 766 fijos: aquí ocupa el ancho de la columna
   y en pantallas angostas las tarjetas se desplazan en horizontal (sin achicarlas). */
.f-shelf { width:100% !important; height:auto !important; gap:16px; margin-top:24px; }
.f-shelf > div:last-child { gap:12px; overflow-x:auto; padding-bottom:8px !important; scroll-snap-type:x mandatory; }
