@media (max-width:1100px) { .f-src__main .f-shelf { order:4; } }
/* Publicar y Valorizar: hover y pressed visibles (antes solo subían 2 px). Curva de Concorde. */
.f-src .f-act { transition:transform .2s cubic-bezier(.25,.8,.25,1), box-shadow .2s cubic-bezier(.25,.8,.25,1), background-color .2s, border-color .2s, filter .2s; }
.f-src .f-act--publish:hover { filter:brightness(1.06) saturate(1.05); box-shadow:0 14px 28px rgba(212,110,32,.4), inset 0 1px 0 rgba(255,255,255,.4); }
.f-src .f-act--publish:active { transform:scale(.98); filter:brightness(.94); box-shadow:inset 0 2px 6px rgba(120,50,0,.35); }
.f-src .f-act--value:hover { border-color:#CFBAFF; background-color:#FBF9FF; box-shadow:0 12px 26px rgba(34,0,92,.12); }
.f-src .f-act--value:hover .f-act__icon { color:#ED8936; background:#FFF1E2; }
.f-src .f-act--value:active { transform:scale(.98); background-color:#F5F0FF; box-shadow:inset 0 2px 6px rgba(34,0,92,.12); }
.f-src .f-act__icon { transition:color .2s, background-color .2s; }
/* Íconos de sección: degradado vault (TabSelector activo) en un mosaico suave; naranja al pasar, como la barra lateral de Concorde. */
.f-src .fs__icon { width:36px; height:36px; border-radius:12px; background:linear-gradient(135deg,#F5F0FF,#EDE6FF); box-shadow:inset 0 1px 0 #fff, inset 0 0 0 1px rgba(132,96,229,.14); transition:background .2s; }
.f-src .fs__icon path { fill:var(--ico); }
.f-src .fs__toggle:hover .fs__icon { background:linear-gradient(135deg,#FFF8F1,#FFEBD6); }
.f-src .fs__toggle:hover .fs__icon path { fill:var(--ico-h); }
@media (prefers-reduced-motion:reduce) { .f-src .f-act, .f-src .fs__icon { transition:none; } .f-src .f-act:active { transform:none; } }
.f-shelf { min-width:0; max-width:100%; } .f-shelf > div:last-child { min-width:0; } /* en la grilla, el estante no impone sus 766 px */

/* ── Maqueta VMC (15/10): Pulso Fuente tal cual, compactado a la columna de ~766 px de vmcsubastas.com.
   Misma composición (Tu actividad + riel); el riel pasa a 248 px y las filas de sección usan su versión de dos líneas.
   Sin banner principal (pedido de Abraham, 15/10). En móvil es idéntico a Pulso Fuente. ── */
@media (min-width:1024px) {
  .g--vmc.g-page { max-width:none; padding:24px 16px 64px; gap:24px; }
  .g--vmc .f-src { grid-template-columns:minmax(0,1fr) 248px; gap:16px; }
