  .g--vmc .f-src__rail { display:grid; gap:12px; position:sticky; }
  .g--vmc .f-src .f-actions__row { grid-template-columns:1fr; gap:10px; } /* entre 1024 y 1100 px Fuente las pone lado a lado */
  .g--vmc .f-src .fs__toggle { grid-template-columns:minmax(0,1fr) auto 20px; }
  .g--vmc .f-src .fs__chips { grid-column:2; grid-row:1; justify-content:flex-end; } .g--vmc .f-src .fs__summary { grid-column:1 / 3; grid-row:2; } .g--vmc .f-src .fs__chev { grid-row:1; grid-column:3; }
  .g--vmc .f-src .f-head__title { flex-wrap:wrap; }
}

/* Oferta VMC medida con Playwright a 1024 px: sidebar 229, área útil 795,
   padding lateral 16, contenido 451 + 12 + riel 300. Solo sistema de layout. */
@media (min-width:1024px) {
  .g--vmc.g-page { padding:16px 16px 64px; gap:16px; }
  .g--vmc .f-src { grid-template-columns:451px 300px; gap:12px; justify-content:normal; }
