/* Jerarquía compacta (15/10): la misma escala de Mi Garaje (40·24·18·15·14·12 · pesos 800/600/400) bajada un escalón,
   como el contenido de VMC. 1º título 24 · 2º Tu actividad, valores de la cuenta y montos 18 · 3º secciones, filas y acciones 15 · 4º rótulos 12. */
@media (min-width:1024px) {
  .g--vmc .f-src { grid-template-columns:minmax(0,1fr) 256px; }
  .g--vmc .f-head .g-head h1, .g--vmc .f-head h1 { font-size:1.5rem; }
  .g--vmc .g-activity .g-head h2, .g--vmc .f-recs .g-head h2 { font-size:1.125rem; }
  .g--vmc .f-src .fs__name { font-size:.9375rem; }
  /* Tarjeta de cuenta: rótulos en una línea, valores al mismo tamaño. */
  .g--vmc .f-acct__row > * { padding:12px 16px; }
