  .g--vmc .f-acct__passmsg { padding-left:8px; }
  /* Riel: Publicar/Valorizar y Wallet a la medida de 256 px. */
  .g--vmc .f-act { grid-template-columns:32px 1fr 16px; gap:10px; min-height:56px; padding:10px 12px; border-radius:16px; }
  .g--vmc .f-act__icon { width:32px; height:32px; }
  .g--vmc .f-act__text b { font-size:.9375rem; } .g--vmc .f-act__text small { font-size:.75rem; }
  .g--vmc .f-src .f-wallet { padding:16px; gap:12px; border-radius:16px; }
  .g--vmc .f-wallet h2 { font-size:.9375rem; font-weight:800; }
  .g--vmc .f-src .f-wallet a, .g--vmc .f-src .f-wallet h2 + * { font-size:.75rem; }
  .g--vmc .f-src .f-wallet__bal dd, .g--vmc .f-src .f-wallet__bal div + div dd { font-size:1.125rem; padding-top:0; }
  .g--vmc .f-src .f-wallet__bal dd small { font-size:.75rem; }
  .g--vmc .f-wallet__bal div + div { padding-left:12px; }
  .g--vmc .f-wallet .psec { font-size:.875rem; }
  /* Revisión final: Wallet sin aire de más, íconos a la medida del texto de 15 px, SubasPass con respiro. */
