}

/* Íconos de vidrio en las secciones de Pulso Fuente (15/10): sin mosaico, el ícono es la composición. Hover/foco del encabezado los anima. */
.f-src .fs__icon--glass, .f-src .fs__toggle:hover .fs__icon--glass { width:40px; height:40px; border-radius:0; background:none; box-shadow:none; }
/* Resto de íconos de vidrio en Pulso Fuente (15/10). Publicar: el ícono va sobre un círculo blanco para leerse sobre el naranja.
   Wallet: sólido naranja sobre el fondo vault (el violeta se perdería). «Requieren tu acción»: la campana suena al pasar. */
/* Íconos de vidrio en Publicar/Valorizar (15/10): son ilustrativos, no glifos. Un glifo en botón mide ~1,1× el texto;
   uno ilustrativo necesita 32 px o más para leerse, así que va como ilustración de la tarjeta: 48 px, sin círculo.
   Sobre el naranja de Publicar el vidrio pasa a blanco esmerilado con el detalle en naranja oscuro. */
.f-act:has(.f-act__icon--glass) { grid-template-columns:48px 1fr 20px; gap:14px; padding-top:12px; padding-bottom:12px; }
.f-act .f-act__icon.f-act__icon--glass { width:48px; height:48px; border-radius:0; background:none; box-shadow:none; }
.f-act .f-act__icon--glass svg.vd { width:48px; height:48px; }
.f-act--publish .vd { --solid:#fff; --glass:#FFE3C7; }
.f-act--publish .vd :is([fill="#fff"]) { fill:#C2560F; } .f-act--publish .vd :is([stroke="#fff"]) { stroke:#C2560F; }
.f-act--publish .vd .vd-edge { stroke:#fff; stroke-opacity:.8; }
.f-wallet h2 { display:flex; align-items:center; gap:8px; }
.f-wallet .vd { --solid:#ED8936; --glass:#CFBAFF; }
.f-only .vd { flex:none; margin:-4px 0; }

/* ── Maqueta VMC · revisión (15/10) ──
   1) Anchos de la página de detalle de VMC (columna 451 · separación 12 · columna 300) para reutilizar sus componentes.
   2) Mi Wallet recupera el degradado diagonal con el brillo naranja (antes de aplanarlo en Fuente).
   3) Anuncio como banner con botón HTML clicable (en VMC es una imagen entera). */
@media (min-width:1024px) {
  .g--vmc .f-src { grid-template-columns:minmax(0,451px) 300px; gap:16px 12px; justify-content:space-between; }
  .g--vmc .f-src .f-wallet { background:linear-gradient(116deg,#5A35C2 0%,#2E0F70 55%,#100030 100%); box-shadow:0 12px 32px rgba(34,0,92,.28); }
