}
.f-ad--banner { display:block; }
.f-ad__banner { position:relative; overflow:hidden; display:grid; align-content:space-between; gap:16px; min-height:250px; padding:20px; border-radius:16px; color:#fff;
  background:radial-gradient(120% 80% at 100% 100%, rgba(237,137,54,.85), transparent 60%), linear-gradient(160deg,#5A35C2 0%,#3B1782 55%,#22005C 100%); }
.f-ad__banner p { margin:0; display:grid; gap:8px; }
.f-ad__banner b { font-size:1.125rem; line-height:1.25; font-weight:800; }
.f-ad__banner span { font-size:.875rem; line-height:1.4; color:#E8DEFF; }
.f-ad__cta { justify-self:start; display:inline-flex; align-items:center; min-height:40px; padding:0 20px; border-radius:9999px; font-size:.875rem; font-weight:700; color:#fff; text-decoration:none;
  background:linear-gradient(180deg,#F4AC59,#ED8936 50%,#D46E20); box-shadow:inset 0 1px 0 rgba(255,255,255,.35), 0 6px 16px rgba(237,137,54,.35); transition:transform .15s; }
.f-ad__cta:hover { transform:translateY(-1px); } .f-ad__cta:focus-visible { outline:2px solid #fff; outline-offset:2px; }
@media (prefers-reduced-motion:reduce) { .f-ad__cta { transition:none; } }
/* Columna de 451 px: el precio de la fila nunca se corta; el texto pasa a una segunda línea. */
@media (min-width:1024px) { .g--vmc .fr__meta { white-space:normal; overflow:visible; text-overflow:clip; } }
/* Columna de 451 px (revisión 15/10): la cuenta y las filas toman su versión móvil para no pasar por debajo del riel. */
@media (min-width:1024px) {
  .g--vmc .f-src__main > *, .g--vmc .f-head, .g--vmc .f-head__acct { min-width:0; }
