  .g--vmc.g-page .f-acct__pass { border-radius:0 0 8px 8px; }
  /* 3 · Filas en una línea */
  .g--vmc.g-page .f-src .fr { grid-template-columns:48px minmax(0,1fr) auto 16px; grid-template-areas:"img main side chev"; gap:0 12px; align-items:center; padding:8px; }
  .g--vmc.g-page .fr__img, .g--vmc.g-page .fr img { width:48px; height:36px; border-radius:6px; align-self:center; }
