  .g--vmc.g-page .f-acct__summary .f-acct__metric { display:grid; grid-row:1 / span 3; grid-template-rows:subgrid; row-gap:8px; min-width:0; align-items:center; box-sizing:border-box; padding:16px 12px 12px; }
  .g--vmc.g-page .f-acct__summary .f-acct__metric:first-child { grid-column:2; border-left:1px solid var(--line); }
  .g--vmc.g-page .f-acct__summary .f-acct__metric:last-child { grid-column:3; border-left:1px solid var(--line); }
  .g--vmc.g-page .f-acct__membership { grid-column:1 / -1; grid-row:4; grid-template-columns:max-content max-content minmax(0,1fr); grid-template-rows:none; align-items:center; column-gap:10px; padding:10px 16px; border-left:0; border-top:1px solid var(--line); }
