.f-src .f-act::after { content:""; position:absolute; z-index:2; inset:0; padding:2px; border-radius:inherit; pointer-events:none; opacity:0; background-size:220% 220%; background-position:0% 50%; -webkit-mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0); -webkit-mask-composite:xor; mask-composite:exclude; transition:opacity .18s ease-out; }
