/* ══ Campaña «Venta para empresas» (20/10) · Promo, cuarta ronda: jerarquía y recetas de los banners de vmc-index-lab.
   Z: chip (11–12 · 800) → titular (18 · 700, columna angosta) → bajada (12 · 400) → CTA abajo a la izquierda; la flota recortada
   es la masa visual abajo a la derecha y sale por el borde. Radio 8 y sombras del riel de Mi Garaje VMC. */
.pr { --pr-ink:#1B1442; --pr-muted:#6B6878; --pr-out:cubic-bezier(.16,1,.3,1);
  position:relative; isolation:isolate; overflow:hidden; display:flex; flex-direction:column; align-items:flex-start; min-height:320px; padding:20px;
  border-radius:8px; font-family:inherit; cursor:pointer; }
.pr > :not(.pr__stage) { position:relative; z-index:2; }
.pr__chip { display:inline-flex; align-items:center; gap:6px; height:24px; padding:0 10px; border-radius:999px; font-size:.75rem; font-weight:800; letter-spacing:.01em; white-space:nowrap; }
.pr__h { max-width:180px; margin:12px 0 0; font-size:1.125rem; line-height:1.22; font-weight:700; letter-spacing:-.02em; color:var(--pr-ink); text-wrap:balance; }
