.pr__cta { margin-top:auto; text-decoration:none; }
.pr:has(a:focus-visible) { outline:2px solid #8460E5; outline-offset:2px; }
.pr .sr-only { position:absolute; width:1px; height:1px; overflow:hidden; clip-path:inset(50%); white-space:nowrap; }

/* Escenario: la flota, anclada abajo a la derecha por encima de la fila del CTA. Sombra desde el alfa + sombra de contacto. */
.pr__stage { position:absolute; z-index:1; right:0; bottom:58px; width:220px; height:130px; pointer-events:none; }
.pr__stage::before { content:""; position:absolute; left:6%; right:-6%; bottom:-8px; height:26px; border-radius:50%; background:radial-gradient(closest-side, rgba(16,4,48,.4), rgba(16,4,48,0)); }
.pr__car { position:absolute; bottom:0; height:auto; filter:drop-shadow(0 10px 8px rgba(16,4,48,.3)); transition:transform .6s var(--pr-out); }
.pr__car--back { z-index:1; right:-46px; bottom:30px; width:132px; filter:drop-shadow(0 8px 6px rgba(16,4,48,.26)) brightness(.9); }
.pr__car--mid { z-index:2; right:6px; bottom:18px; width:100px; }
.pr__car--front { z-index:3; left:4px; bottom:0; width:176px; animation:pr-drive .9s var(--pr-out) .1s both; }
@keyframes pr-drive { from { opacity:0; transform:translateX(28px); } }
.pr:hover .pr__car--front { transform:translateX(-6px); } .pr:hover .pr__car--mid { transform:translateX(-3px); } .pr:hover .pr__car--back { transform:translateX(-1px); }

/* Botón de vidrio de index-lab (.hib-glass): relleno translúcido + borde degradado VYStrokes1. */
