  -webkit-mask:linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0); -webkit-mask-composite:xor; mask-composite:exclude; }
.pr:hover .pr-glass { transform:translateY(-1px); background-color:rgba(255,255,255,.1); box-shadow:rgba(0,0,0,.16) 0 12px 28px, inset 0 1px 8px rgba(255,255,255,.6); }
