/* Noche: escenario oscuro centrado; una sola pickup con reflejo real en el piso (-webkit-box-reflect) y luz cenital. */
.pr--noche { align-items:center; text-align:center; color:#fff; box-shadow:0 12px 32px rgba(34,0,92,.28);
  background:radial-gradient(70% 34% at 50% 74%, rgba(174,142,255,.45), rgba(174,142,255,0) 70%), radial-gradient(60% 40% at 50% -10%, rgba(244,172,89,.28), transparent 70%), linear-gradient(180deg,#22005C 0%,#2E0F70 60%,#1A0048 100%); }
.pr--noche .pr__chip { border:1px solid rgba(255,255,255,.28); background:rgba(255,255,255,.12); color:#fff; }
.pr--noche .pr__h { max-width:230px; margin-top:12px; color:#fff; } .pr--noche .pr__p { max-width:240px; color:rgba(255,255,255,.88); }
.pr--noche .pr__stage { position:relative; right:auto; bottom:auto; width:100%; height:128px; margin:4px 0 0; }
.pr--noche .pr__stage::before { display:none; }
.pr--noche .pr__car--front { left:50%; width:220px; margin-left:-110px; -webkit-box-reflect:below 0 linear-gradient(transparent 72%, rgba(255,255,255,.14)); /* reflejo tenue: no ensucia el chip */ }
.pr--noche .pr__cta { align-self:stretch; margin-top:28px; }

/* Flota = «¿Vendes varios vehículos?»: imagen a la izquierda, titular 14/700, bajada 12 y enlace violeta con flecha en círculo. */
.pr--flota { min-height:0; display:grid; grid-template-columns:104px 1fr; grid-template-rows:auto auto auto; column-gap:16px; align-items:start; padding:12px 16px 12px 0;
  background:#fff; border:1px solid #E6DEFF; box-shadow:0 1px 3px rgba(34,0,92,.05), 0 10px 30px rgba(34,0,92,.06); }
.pr--flota .pr__stage { position:relative; grid-row:1 / 4; align-self:stretch; width:auto; height:auto; min-height:76px; right:auto; bottom:auto; margin:-12px 0; overflow:hidden; background:linear-gradient(160deg,#F6F2FF,#ECE4FF); }
.pr--flota .pr__h { grid-column:2; max-width:none; margin:0; font-size:.875rem; line-height:1.3; }
.pr--flota .pr__p { grid-column:2; max-width:none; margin:2px 0 0; }
.pr--flota .pr__car--back { right:-18px; bottom:30px; width:58px; } .pr--flota .pr__car--mid { right:22px; bottom:22px; width:44px; }
.pr--flota .pr__car--front { left:2px; bottom:12px; width:78px; }
.pr--flota .pr__stage::before { bottom:6px; height:12px; }
.pr__link { grid-column:2; display:inline-flex; align-items:center; gap:6px; margin-top:6px; font-size:.8125rem; font-weight:700; color:#3B1782; text-decoration:none; white-space:nowrap; }
.pr__link svg { flex:none; transition:transform .2s var(--pr-out); } .pr:hover .pr__link svg { transform:translateX(3px); }

/* Barra lateral (200 × 264): misma lectura en Z a escala; sin bajada; CTA a lo ancho. */
[data-slot="sidebar-banner"]:has(.pr, .pr-arte) { position:relative; overflow:hidden; background:none !important; }
[data-slot="sidebar-banner"]:has(.pr, .pr-arte) > span { display:none; }
/* El espacio crece a 200 × 380 (cerca del formato oficial «Lateral inferior» 200 × 400) y ocupa el hueco libre bajo el menú. */
.kit-shell--vmc .sb-banner:has(.pr, .pr-arte) { max-height:400px; }
.kit-shell--vmc [data-slot="sidebar-banner"]:has(.pr) { height:380px !important; }
/* 22/10: las piezas de /banners-publica en la barra lateral usan el formato 200 × 400 y llenan el hueco bajo el menú. */
.kit-shell--vmc [data-slot="sidebar-banner"]:has(.pr-arte) { height:400px !important; }
/* 22/10 (Abraham): aire entre «Centro de Ayuda» y el banner. */
.kit-shell--vmc .sb-banner:has(.pr-arte) { max-height:none; padding-top:16px; }
.pr--side, .pr-arte--side { position:absolute; inset:0; border-radius:inherit; }
.pr-arte--side { display:block; width:100%; height:100%; border:0; }
.pr--side { min-height:0; padding:16px; }
.pr--side .pr__chip { height:22px; font-size:.6875rem; }
.pr--side .pr__h { max-width:none; margin-top:10px; font-size:1.0625rem; }
.pr--side .pr__p { max-width:none; }
.pr--side .pr__cta, .pr--side .pvbtn.pr__cta { align-self:stretch; height:38px; margin-top:auto; padding:0 10px; font-size:.8125rem; white-space:nowrap; }
.pr--side .pr__stage { bottom:58px; width:168px; height:110px; }
.pr--side .pr__car--back { right:-36px; bottom:22px; width:92px; } .pr--side .pr__car--mid { right:2px; bottom:12px; width:70px; }
.pr--side .pr__car--front { left:0; width:150px; }
.pr--side.pr--vitrina .pr__car--front { left:auto; right:-20px; width:170px; }
/* Lote: la imagen ocupa el tercio superior (148 px) y el texto respira debajo. */
.pr--side.pr--lote .pr__stage { right:auto; bottom:auto; width:auto; height:156px; margin:-16px -16px 0; }
.pr--side.pr--lote .pr__car--front { left:50%; width:164px; margin-left:-82px; bottom:10px; } /* la cabina queda bajo la insignia */
.pr--side.pr--lote .pr__h { margin-top:12px; }
.pr--side.pr--noche .pr__h { margin-top:10px; }
.pr--side.pr--noche .pr__stage { right:auto; bottom:auto; width:100%; height:150px; margin:0; }
.pr--side.pr--noche .pr__car--front { left:50%; width:184px; margin-left:-92px; }

/* ── Quinta ronda: profundidad. Plataforma de vidrio bajo el vehículo, luz cenital, palabra clave en color, chips de vidrio
   y un destello que cruza una vez al pasar el cursor. */
/* Plataforma de vidrio: elipse translúcida con filo blanco; el vehículo se apoya encima (z 1–3). */
.pr--lote .pr__stage::after, .pr--vitrina .pr__stage::after, .pr--noche .pr__stage::after { content:""; position:absolute; z-index:0; left:10%; right:10%; bottom:-2px; height:30px; border-radius:50%;
  background:linear-gradient(180deg, rgba(255,255,255,.75), rgba(255,255,255,.12)); box-shadow:inset 0 1px 0 #fff, 0 10px 24px -8px rgba(59,23,130,.35); }
.pr--noche .pr__stage::after { background:linear-gradient(180deg, rgba(174,142,255,.45), rgba(174,142,255,.04)); box-shadow:inset 0 1px 0 rgba(255,255,255,.55), 0 0 40px rgba(174,142,255,.35); }
.pr--vitrina .pr__stage::after { left:16%; right:0; }
.pr--noche .pr__stage { background:radial-gradient(42% 100% at 50% 0%, rgba(255,255,255,.16), transparent 72%); } /* luz cenital */
.pr__car--front { bottom:8px; }
/* Destello: una banda de luz cruza una vez por hover. */
.pr__shine { position:absolute; z-index:4; inset:0; pointer-events:none; overflow:hidden; border-radius:inherit; }
.pr__shine::before { content:""; position:absolute; top:0; bottom:0; left:-40%; width:30%; transform:skewX(-20deg); background:linear-gradient(90deg, transparent, rgba(255,255,255,.35), transparent); opacity:0; }
.pr:hover .pr__shine::before { animation:pr-sweep .9s var(--pr-out) 1; }
@keyframes pr-sweep { from { left:-40%; opacity:1; } to { left:130%; opacity:1; } }
/* Flota en formación en V: el camión al frente y al centro; pickup y sedán detrás, a los lados, más chicos y sobre el mismo piso.
   Todo dentro del escenario (nada cortado); el escenario ocupa todo el ancho de la pieza. */
.pr.pr--many:not(.pr--flota) .pr__stage { left:0; right:0; width:auto; align-self:stretch; } /* en Noche (centrado) sin esto mide 0 */
.pr.pr--many .pr__stage .pr__car--front { left:50%; right:auto; width:66%; margin-left:-33%; bottom:4px; }
.pr.pr--many .pr__stage .pr__car--mid { left:auto; right:0; width:44%; bottom:30%; filter:drop-shadow(0 8px 6px rgba(16,4,48,.26)) brightness(.94); }
.pr.pr--many .pr__stage .pr__car--back { left:0; right:auto; width:42%; bottom:32%; filter:drop-shadow(0 8px 6px rgba(16,4,48,.24)) brightness(.9); }
.pr--many .pr__stage::after { left:6%; right:6%; }
.pr--side.pr--many .pr__stage { height:168px; }
.pr--side.pr--vitrina.pr--many .pr__stage { bottom:62px; }
.pr--vitrina.pr--many:not(.pr--side) .pr__stage { height:160px; }
/* Barra lateral: CTA que respira en 176 px (padding 12, texto 12 px) y chips apilados. */
.pr--side { padding:16px 12px; }
.pr--side .pr__chip { margin-left:4px; }
.pr--side .pr__h { padding-inline:4px; }
.pr--side .pr__cta, .pr--side .pvbtn.pr__cta { height:40px; padding:0 8px; font-size:.75rem; letter-spacing:0; border-width:1.5px; }
.pr--side.pr--lote .pr__stage { margin:-16px -12px 0; }
.pr--side .pr__shine { border-radius:inherit; }
/* Aire: más separación entre bloques; el CTA siempre al fondo con al menos 20 px de respiro. */
.pr .pr__h { margin-top:16px; } .pr .pr__p { margin-top:8px; font-size:.8125rem; }
.pr .pr__cta { margin-top:auto; } .pr:not(.pr--flota) > .pr__p { margin-bottom:20px; } .pr--side .pr__h { margin-bottom:16px; }
.pr--lote .pr__h { margin-top:16px; } .pr--lote .pr__cta { margin-top:20px; }
.pr--noche .pr__p { color:rgba(255,255,255,.85); }
.pr--side .pr__h { margin-top:14px; font-size:1.0625rem; line-height:1.25; }
.pr--side.pr--lote .pr__cta, .pr--side .pr__cta { margin-top:auto; }
.pr--side.pr--noche .pr__stage { height:170px; } .pr--side.pr--noche .pr__car--front { width:180px; margin-left:-90px; }
.pr--side.pr--lote .pr__stage { height:200px; } .pr--side.pr--lote .pr__car--front { width:184px; margin-left:-92px; bottom:16px; }
.pr--side.pr--vitrina .pr__stage { bottom:66px; height:150px; } .pr--side.pr--vitrina .pr__car--front { width:190px; right:-26px; }

/* ── Coherencia con la página (20/10): la insignia usa la escala de BadgeStatus de Concorde (mayúsculas 10 px, sin alto fijo)
   y la barra lateral es siempre oscura (degradado del banner del sidebar de Concorde), como los botones del menú. */
.pr .pr__chip { height:auto; padding:3px 8px 3px 7px; font-size:.625rem; font-weight:700; letter-spacing:.07em; text-transform:uppercase; }
.pr--vitrina .pr__chip::before { width:5px; height:5px; box-shadow:0 0 0 2px #DCD2FB; }
.pr--side.pr--lote, .pr--side.pr--vitrina { border:0; box-shadow:inset 0 0 0 1px rgba(255,255,255,.12); background:linear-gradient(180deg,#3B1A7A 0%,#3B1782 55%,#6E3E2A 100%); }
.pr--side .pr__h { color:#fff; }
.pr--side.pr--lote .pr__stage { background:radial-gradient(60% 70% at 50% 68%, rgba(174,142,255,.38), rgba(174,142,255,0)); }
.pr--side.pr--vitrina .pr__stage { background:radial-gradient(55% 60% at 55% 62%, rgba(244,172,89,.3), rgba(244,172,89,0)); }
.pr--side.pr--vitrina .pr__chip { border:1px solid rgba(255,255,255,.28); background:rgba(255,255,255,.12); color:#fff; box-shadow:none; }
.pr--side.pr--vitrina .pr__chip::before { background:#FBC47D; box-shadow:0 0 0 2px rgba(251,196,125,.25); }
.pr--side .pr__stage::after { background:linear-gradient(180deg, rgba(174,142,255,.45), rgba(174,142,255,.04)); box-shadow:inset 0 1px 0 rgba(255,255,255,.5), 0 0 30px rgba(174,142,255,.3); }
.pr--side .pr__stage::before { background:radial-gradient(closest-side, rgba(16,0,48,.5), rgba(16,0,48,0)); }

/* ── Sexta ronda: la flota como grupo sobre un piso común, escenario sin bordes y fondo de Mi billetera en la barra lateral. */
.pr.pr--many .pr__stage .pr__car--front { width:70%; margin-left:-35%; bottom:6px; }
.pr.pr--many .pr__stage .pr__car--back { left:6%; width:42%; bottom:26%; }
.pr.pr--many .pr__stage .pr__car--mid { right:4%; width:46%; bottom:24%; }
.pr__car { filter:drop-shadow(0 2px 1.5px rgba(16,4,48,.45)) drop-shadow(0 12px 10px rgba(16,4,48,.22)); } /* sombra de contacto + sombra suave */
/* Piso común: una elipse ancha de luz sobre la que se apoyan los tres. */
.pr--many .pr__stage::after { left:-4%; right:-4%; bottom:-6px; height:56%; border-radius:50%;
  background:radial-gradient(closest-side, rgba(255,255,255,.55), rgba(255,255,255,.14) 62%, rgba(255,255,255,0)); box-shadow:none; }
.pr--side.pr--many .pr__stage::after, .pr--noche.pr--many .pr__stage::after { background:radial-gradient(closest-side, rgba(174,142,255,.5), rgba(174,142,255,.12) 62%, rgba(174,142,255,0)); }
/* Barra lateral: fondo de Mi billetera (violeta con brasa abajo) y el escenario sin caja: la luz vive en la tarjeta. */
.pr--side.pr--lote, .pr--side.pr--vitrina { background:radial-gradient(92% 40% at 50% 30%, rgba(174,142,255,.32), rgba(174,142,255,0) 72%),
  radial-gradient(125% 60% at 20% 112%, rgba(244,172,89,.36), rgba(237,137,54,.12) 40%, transparent 72%), linear-gradient(160deg,#5A35C2 0%,#3B1782 52%,#22005C 100%); }
.pr--side.pr--lote .pr__stage, .pr--side.pr--vitrina .pr__stage { background:none; overflow:visible; }
.pr--side .pr__p { margin-top:6px; color:rgba(255,255,255,.82); }
.pr--side .pr__h { margin-bottom:0; }
.pr--side > .pr__p { margin-bottom:16px; }

/* Flota (fila), rehecha: texto a la izquierda y vehículos a la derecha saliendo por el borde, sobre un halo (sin caja).
   Con varios vehículos, diagonal ascendente (encaja con el formato horizontal); con uno, el vehículo grande y cortado por el borde. */
.pr.pr--flota { grid-template-columns:minmax(0,1fr) 128px; column-gap:8px; padding:16px 0 16px 16px; }
.pr--flota .pr__h, .pr--flota .pr__p, .pr--flota .pr__link { grid-column:1; }
.pr--flota .pr__h { font-size:.9375rem; }
.pr.pr--flota .pr__stage { grid-column:2; grid-row:1 / 4; align-self:stretch; min-height:96px; margin:-16px 0; overflow:visible;
  background:radial-gradient(70% 55% at 62% 62%, rgba(174,142,255,.32), rgba(174,142,255,0) 75%); }
.pr.pr--flota .pr__stage::before { left:0; right:-10%; bottom:10px; height:16px; }
.pr.pr--flota .pr__stage::after { display:none; }
.pr.pr--flota .pr__stage .pr__car--front { left:2px; right:auto; width:150px; margin:0; bottom:16px; }
.pr.pr--many.pr--flota .pr__stage .pr__car--front { left:-6px; width:112px; bottom:12px; }
.pr.pr--many.pr--flota .pr__stage .pr__car--mid { left:46px; right:auto; width:80px; bottom:34px; }
.pr.pr--many.pr--flota .pr__stage .pr__car--back { left:66px; right:auto; width:70px; bottom:52px; }
.pr.pr--flota { overflow:hidden; }

/* Fila, versión rica (patrón horizontal de maquinaria C en index-lab): texto sobre blanco a la izquierda y, a la derecha, un panel
   violeta en diagonal con brasa y anillo; los vehículos lo rompen por arriba. Contenido centrado en vertical. */
.pr.pr--flota { grid-template-columns:minmax(0,1fr) 132px; grid-template-rows:auto auto auto auto; align-content:center; row-gap:0; min-height:168px; padding:16px 0 16px 16px; isolation:isolate; }
.pr.pr--flota::before { content:""; position:absolute; z-index:0; top:0; right:0; bottom:0; width:48%; clip-path:polygon(22% 0, 100% 0, 100% 100%, 46% 100%); /* la base deja libre el enlace */
  background:radial-gradient(70% 60% at 30% 110%, rgba(239,133,46,.8), transparent 70%), linear-gradient(145deg,#4E22A9 0%,#7B4BE3 100%); }
.pr.pr--flota::after { content:""; position:absolute; z-index:0; right:-56px; top:-64px; width:150px; height:130px; border:26px solid rgba(255,255,255,.1); border-radius:50%; }
.pr--flota .pr__chip { grid-column:1; justify-self:start; padding:3px 8px 3px 7px; color:#fff; background:linear-gradient(135deg,#8460E5,#3B1782); box-shadow:rgba(34,0,92,.2) 0 2px 6px; }
.pr--flota .pr__h { grid-column:1; margin-top:10px; font-size:1rem; line-height:1.25; color:#3B1782; }
.pr--flota .pr__p { grid-column:1; margin:6px 0 0 !important; }
.pr--flota .pr__link { grid-column:1; margin-top:12px; }
.pr.pr--flota .pr__stage { grid-column:2; grid-row:1 / 5; background:none; margin:-16px 0; }
.pr.pr--flota .pr__stage::before { left:-6%; right:-6%; bottom:14px; height:18px; background:radial-gradient(closest-side, rgba(16,0,48,.55), rgba(16,0,48,0)); }
.pr.pr--flota .pr__stage .pr__car--front { left:-22px; width:164px; bottom:18px; }
.pr.pr--many.pr--flota .pr__stage .pr__car--front { left:-26px; width:128px; bottom:16px; }
.pr.pr--many.pr--flota .pr__stage .pr__car--mid { left:34px; width:94px; bottom:40px; }
.pr.pr--many.pr--flota .pr__stage .pr__car--back { left:58px; width:80px; bottom:62px; }
.pr--flota .pr__link svg { color:#ED8936; }

/* Arte original (riel): JPG a tamaño nativo, sin recorte. */
.f-camp--arte iframe { display:block; width:100%; border:0; border-radius:8px; box-shadow:0 0 0 1px #E1E3E2; }
.f-camp__lg { height:320px; } /* alto inicial; fitBanner() lo ajusta al contenido */ .f-camp__sm { display:none !important; max-width:776px; aspect-ratio:776/232; }
@media (max-width:1100px) { .f-camp__lg { display:none !important; } .f-camp__sm { display:block !important; } }

/* Accesibilidad: sin movimiento, sin transparencia (vidrio sólido) y colores forzados. */
@media (prefers-reduced-motion:reduce) { .pr__car, .pr__link svg, .pr-glass, .pr:hover .pr__shine::before { animation:none; transition:none; } .pr:hover .pr__cta { transform:none; } }
@media (forced-colors:active) { .pr { border:1px solid CanvasText; } }
/* Selector flotante de banners (solo maqueta VMC). */
.f-sw { position:fixed; z-index:90; right:16px; bottom:16px; display:grid; gap:10px; max-width:min(560px, calc(100vw - 32px)); padding:12px; border-radius:16px;
  background:#fff; box-shadow:0 12px 32px rgba(34,0,92,.28), 0 0 0 1px #E6DEFF; font-size:.8125rem; color:#3B1782; }
.f-sw__bar { display:flex; align-items:center; gap:2px; margin:-4px -4px 0 0; } .f-sw__bar b { flex:1; font-size:.875rem; font-weight:800; }
.f-sw__win { display:grid; place-items:center; width:32px; height:32px; border:0; border-radius:8px; background:none; color:#6B6878; cursor:pointer; }
.f-sw__win:hover { background:#F3EFFD; color:#3B1782; } .f-sw__win:last-child:hover { background:#FDECEC; color:#B42318; }
.f-sw__win:focus-visible, .f-sw__pill:focus-visible { outline:2px solid #8460E5; outline-offset:2px; }
.f-sw--closed { padding:0; border-radius:9999px; }
.f-sw__pill { display:inline-flex; align-items:center; gap:8px; height:40px; padding:0 14px 0 16px; border:0; border-radius:9999px; background:#fff; font:inherit; font-weight:800; color:#3B1782; cursor:pointer; }
.f-sw__pill:hover { background:#F3EFFD; }
.f-sw__g { display:flex; flex-wrap:wrap; align-items:center; gap:6px; }
.f-sw__g { padding-top:10px; border-top:1px solid #EEE9FB; } .f-sw__g:first-of-type { padding-top:10px; }
.f-sw__k { flex-basis:100%; font-size:.75rem; color:#6B6878; } .f-sw__k b { font-weight:800; color:#3B1782; } .f-sw__k em { font-style:normal; color:#B3400C; }
.f-sw__hint { flex-basis:100%; font-size:.75rem; color:#6B6878; }
.f-sw__all { display:block; margin-top:10px; font-size:.75rem; font-weight:600; color:var(--vmc-color-vault-600); }
.f-sw__g.is-off button { opacity:.45; }
.f-sw__g button { min-height:32px; padding:0 12px; border:1px solid #DCD2FB; border-radius:9999px; background:#fff; font:inherit; font-weight:600; color:inherit; cursor:pointer; }
.f-sw__g button[aria-pressed="true"] { border-color:#3B1782; background:#3B1782; color:#fff; }
.f-sw__g button:not(:disabled):not([aria-pressed="true"]):hover { border-color:#8460E5; background:#F8F5FF; }
.f-sw__g button:focus-visible { outline:2px solid #8460E5; outline-offset:2px; }
/* 27/10: dos tipos de control. Chip (aria-pressed) = elegir una variante. Fila (grupo data-acts) = disparar un evento de la
   demo: a ancho completo, la acción a la izquierda y el dato (monto, ronda) a la derecha; nunca se parte en tres líneas. */
.f-sw__g[data-acts] { gap:4px; }
.f-sw .f-sw__g[data-acts] button { flex:0 0 100%; padding:0 12px; display:flex; align-items:center; justify-content:space-between; gap:12px; min-height:36px; border-radius:10px; text-align:left; }
.f-sw__g[data-acts] button small { flex:none; font-size:.75rem; font-weight:500; color:#6B6878; font-variant-numeric:tabular-nums; }
.f-sw__g[data-acts] .f-sw__k { margin-bottom:2px; } .f-sw__g[data-acts] .f-sw__hint { margin-top:2px; }

/* 27/10 (Abraham): dock del lab. Antes cada panel tenía su propio position:fixed y se encimaban (Banners sobre
   Notificaciones, Foco sobre la demo). Ahora LabPanel con `side` se monta en una columna por lado: se apilan desde
   abajo, se reparten el alto y cada uno desplaza su contenido si no entra. Mismo ancho para todos. */
.lab-dock { position:fixed; z-index:140; inset:16px; display:flex; justify-content:space-between; gap:16px; pointer-events:none; }
.lab-dock__col { display:flex; flex-direction:column; justify-content:flex-end; gap:8px; width:300px; min-height:0; }
.lab-dock__col--right { align-items:flex-end; } .lab-dock__col--left { align-items:flex-start; }
#lab-dock .f-sw { position:relative; inset:auto; z-index:auto; width:100%; max-width:none; max-height:none; min-height:0; flex:0 1 auto;
  overflow:auto; overscroll-behavior:contain; scrollbar-width:thin; box-sizing:border-box; pointer-events:auto; }
#lab-dock .f-sw--closed { width:auto; flex:none; overflow:visible; }
.lab-dock .f-sw:not(.f-sw--closed) { min-height:min(160px, 100%); }
.lab-dock .f-sw__bar { position:sticky; top:-12px; z-index:1; margin:-12px 0 0; padding:8px 0; background:#fff; }
@media (max-width:600px) {
  .lab-dock { inset:auto 8px 8px; flex-direction:column-reverse; max-height:60vh; gap:8px; }
