/* Cierre del panel (23/10): se pliega hacia la derecha (abajo en móvil); la flecha apunta hacia allí. */
.g-qv.is-closing { animation:g-qv-out .62s cubic-bezier(.55,0,.75,.2) forwards; }
.g-qv.is-closing::backdrop { animation:g-qv-fade .62s ease forwards; }
@keyframes g-qv-out { to { transform:translateX(100%); } }
@keyframes g-qv-fade { to { opacity:0; } }
.fr.is-negotiation-leaving { pointer-events:none; animation:fr-negotiation-leave .62s cubic-bezier(.55,0,.75,.2) forwards; }
/* Expiración vista comprador: al salir la hoja lateral/inferior, esta fila es
   la única que se mueve. Todo su contenido gana peso en ese instante para
   conducir la mirada antes de desvanecerse. No reutiliza el estado is-new. */
.fr.is-negotiation-leaving.is-expiry-exit,
.fr.is-negotiation-leaving.is-expiry-exit * { font-weight:700 !important; color:#191C1C !important; }
@keyframes fr-negotiation-leave { to { opacity:0; transform:translateX(36px) scale(.98); } }
/* 30/10 (Aaron): salida a elegir en el lab «Salida de la negociación» (data-salida en .g-page), con su duración
   y la espera tras cerrar el panel. Por defecto (30/10): «Crece y se va», 1.2 s, tras 1.4 s; las de respaldo de abajo son las anteriores. */
.g-page .fr.is-negotiation-leaving { animation-duration:var(--salida-ms, .62s); animation-delay:var(--salida-espera, 0s); }
[data-salida="crece"] .fr.is-negotiation-leaving { position:relative; z-index:2; animation-name:fr-salida-crece; animation-timing-function:ease-in-out; }
@keyframes fr-salida-crece { 35% { opacity:1; transform:scale(1.05); box-shadow:0 14px 34px rgba(59,23,130,.24); } 100% { opacity:0; transform:translateX(64px) scale(.86); box-shadow:none; } }
[data-salida="negrita"] .fr.is-negotiation-leaving { animation-name:fr-salida-sostiene; }
[data-salida="negrita"] .fr.is-negotiation-leaving * { font-weight:800 !important; color:#2A0E66; }
@keyframes fr-salida-sostiene { 0%, 50% { opacity:1; transform:none; } 100% { opacity:0; transform:translateX(36px) scale(.98); } }
[data-salida="parpadea"] .fr.is-negotiation-leaving { animation-name:fr-salida-parpadea; animation-timing-function:linear; }
@keyframes fr-salida-parpadea { 0%, 16%, 32%, 48% { opacity:1; } 8%, 24%, 40% { opacity:.2; } 62% { opacity:1; transform:none; } 100% { opacity:0; transform:translateX(36px) scale(.98); } }
[data-salida="magenta"] .fr.is-negotiation-leaving { position:relative; z-index:2; animation-name:fr-salida-magenta; }
@keyframes fr-salida-magenta { 0% { box-shadow:inset 0 0 0 0 transparent; } 20%, 55% { opacity:1; transform:none; box-shadow:inset 0 0 0 2px #CC00FF, 0 0 0 4px rgba(204,0,255,.16); } 100% { opacity:0; transform:translateX(36px) scale(.98); box-shadow:inset 0 0 0 2px #FF0066, 0 0 0 4px rgba(255,0,102,.1); } }
[data-salida="pliega"] .fr.is-negotiation-leaving { overflow:hidden; animation-name:fr-salida-pliega; }
@keyframes fr-salida-pliega { 0% { max-height:160px; } 45% { opacity:0; transform:translateX(36px); max-height:160px; } 100% { opacity:0; transform:translateX(36px); max-height:0; padding-top:0; padding-bottom:0; margin-top:0; margin-bottom:0; border-width:0; } }
@media (prefers-reduced-motion:reduce) { [data-salida] .fr.is-negotiation-leaving { animation:none; } }
.g-qv__close--arrow svg { transition:transform .2s; } .g-qv__close--arrow:hover svg { transform:translateX(2px); }
@media (max-width:767px) { /* = hoja inferior del panel */
  .g-qv.is-closing { animation-name:g-qv-down; }
  @keyframes g-qv-down { to { transform:translateY(100%); } }
