        {t.piezas.map((x) => <button key={x.key} type="button" aria-pressed={v === x.key} disabled={usado} title={usado ? "Este tipo ya está en el otro espacio" : undefined} onClick={() => onPick(x.key)}>{x.corto}</button>)}</div>; })}
