      </> : <>
        <AvatarZone size={32} />
        <b>¡Hola, ZAEX5G!</b>
        <RiskMeter level={0} tone="light" />
        <span className="f-head__pts"><StarIcon size="sm" />Puntos VMC <b>500</b> pts<InfoIcon size={14} title="Acumulas puntos con tu actividad en VMC" /></span>
