      setOver((o) => ({ ...o, sf1: { detail: `Contrapropuesta recibida · ${usd(FINAL_BUY.counter)}`, status: "Responder", tone: "action", isNew: true, unread: true, sentByMe: false, when: "Ahora", ago: undefined, due: 1, dueAt: Date.now() + 864e5, arrivedAt: Date.now(),
        history: [`Ahora · El vendedor te hizo su contrapropuesta final de ${usd(FINAL_BUY.counter)} (5 de 5)`, `Hoy · Enviaste tu última propuesta de ${usd(offer)} (5 de 5)`] } }));
      return;
    }
    if (k === "rechaza") {
      const showNotice = () => {
        setNegs((m) => ({ ...m, sf1: { ...n, state: "rechazada", round: 5 } }));
        setOver((o) => ({ ...o, sf1: finalRejectedNoticeRow(offer) }));
      };
      const changeToRejected = () => {
        setStageFocus(3);
      };
      const showRejectedCard = () => {
        const finish = () => { setStageFocus(undefined); setOver((o) => ({ ...o, sf1: { ...finalRejectedBuyRow(offer, 3), flash: false, relocated: true } })); };
        flyFinalRow("sf1", finish);
      };
      const moveAfterNotice = () => {
        changeToRejected(); window.setTimeout(showRejectedCard, 420);
      };
      showNotice(); window.setTimeout(moveAfterNotice, 900);
      return;
    }
    setNegs((m) => ({ ...m, sf1: { ...n, state: "aceptada", round: 5 } }));
    setOver((o) => ({ ...o, sf1: { ...finalAcceptedBuyRow(offer), flash: false, arrival: "accepted", arrivedAt: Date.now() } }));
  };
  // Alto del riel para su sticky (ver .f-src__rail en garaje.css).
  const railRef = useRef<HTMLDivElement>(null);
  useEffect(() => { const el = railRef.current; if (!el) return;
    const ro = new ResizeObserver(() => el.style.setProperty("--rail-h", `${el.offsetHeight}px`)); ro.observe(el); return () => ro.disconnect(); }, []);
  // #neg=rechazada: el vendedor rechazó la propuesta del Mazda 3 (revisión del caso comprador).
  useEffect(() => { if (!/neg=rechazada/.test(location.hash)) return;
    setNegs((m) => (m.sn1 ? { ...m, sn1: { ...m.sn1, state: "rechazada" } } : m));
    setOver((o) => ({ ...o, sn1: { status: "Rechazada", tone: "wait", detail: "Tu propuesta ha sido rechazada.", hideActor: true, dueAt: Date.now() + 864e5 } })); }, []);
  // Pulso Fuente: sin Pendientes; Tu actividad ocupa la columna principal y Wallet + SubasPass van en el riel.
  const activity = (
      <div className="g-activity">
        <div className="g-activity__head">
          <Heading variant={variant} title="Tu actividad" group sub={variant === "concorde" ? "Tus procesos en VMC" : undefined} />
          {/* Filtro junto a lo que filtra: deja solo lo que te necesita, sin pestañas para no esconder nada. */}
          {sober && todo > 0 && !isLoading ? <button type="button" role="switch" aria-checked={filtering} className={`f-only${glass ? " vd-host" : ""}`} onClick={() => smooth(() => setOnlyTodo((x) => !x))}><span className="f-only__track" aria-hidden><i /></span>{glass && PAUSA.bell ? <Vidrio s="alertas" size={28} /> : null}Pendientes <b>{todo}</b></button> : null}
          {variant === "fernando" && !isEmpty && !sober ? <TabSelector options={["Todo", "Comprando", "Vendiendo"]} value={role} onChange={setRole} aria-label="Filtrar por rol" /> : null}
        </div>
        {isEmpty && !isLoading ? <div className="g-firstrun">
          <p><b>Todavía no tienes actividad.</b> Participa en una subasta o publica tu vehículo y aquí verás cada proceso.</p>
          <ProfileButton>Ver subastas de hoy</ProfileButton>
        </div> : null}
        {variant === "fernando"
          ? <LayoutGroup id="mi-garaje-flows"><div className="fa">{shown.map((s) => <FSection key={`${s.id}-${role}-${filtering}`} s={s} loading={isLoading} compact={features.compact} onOpen={openRow} seen={seen} act={sober} glass={glass} vmc={vmc} guideId={demoGuide ? "bp1" : undefined}
            tip={sent && s.id === "negociaciones" ? <FocoInline f={foco} /> : undefined} stageFocus={s.id === "participaciones" ? stageFocus : undefined} />)}</div></LayoutGroup>
          : shown.map((s) => <Section key={`${s.id}-${role}`} s={s} variant={variant} loading={isLoading} f={features} onOpen={openRow} seen={seen} />)}
      </div>
  );
  const subaspass = (
      <aside className="g-subaspass" aria-label="SubasPass">
        <div><b>Compra SubasPass</b><span>¡Dile bye al riesgo alto!</span></div>
        {sober ? <ProfileButton>Comprar ahora</ProfileButton> : <Button variant="outline">Comprar ahora</Button>}
      </aside>
  );
  return <Chrome vmc={vmc}>
    {/* g--vmc = lenguaje visual compartido (jerarquía, filas, radios, contador…); g--wide = Pulso Fuente a todo el ancho (15/10). */}
    <main className={`g-page g--${variant}${vmc ? " g--vmc" : sober ? " g--vmc g--wide" : ""}`} data-rol={rol} data-billetera={bill} data-pill={pill} data-forma={forma} data-etapas={etapas} data-indicio={indicio} data-salida={salida}
      style={{ "--salida-ms": `${salidaMs}ms`, "--salida-espera": `${salidaEspera}ms` } as React.CSSProperties}>
      {flight ? <FlightCue {...flight} /> : null}
      {sober ? <><div className="f-src">
        <div className="f-src__main"><FernandoHead sober risk={risk} pass={pass} withData={withData} />
        {activity}</div>
        <div className="f-src__rail" ref={railRef}><Actions variant={variant} sober glass={glass && PAUSA.actions} vmc={vmc} /><Wallet variant={variant} sober withData={withData} glass={glass} /><Ad banner camp={camp} veh={veh} b={pieza(ban.riel)!} /><Recs withData={withData} /></div>
      </div></> : variant === "fernando" ? <div className="f-grid">
        <FernandoHead sober={sober} />
        <Actions variant={variant} sober={sober} />
        <PendingPanel secs={secs} loading={isLoading} onOpen={openRow} sober={sober} />
        <Wallet variant={variant} sober={sober} withData={!sober || withData} />
      </div> : <header className="g-top">
        <Heading variant={variant} level={1} title="Mi Garaje" sub="Tus vehículos, ofertas y compras." />
        <div className="g-top__actions"><Actions variant={variant} /></div>
      </header>}

      {variant === "fernando" ? null : <div className="g-mobile-only"><AccountLine /></div>}

      {variant !== "fernando" && features.summary ? <SummaryBand secs={secs} loading={isLoading} /> : null}
      {variant !== "fernando" && features.next ? <NextStep secs={secs} loading={isLoading} variant={variant} /> : null}

      {variant === "fernando" ? null : <div className="g-zona">
        <div className="g-desktop-only"><UserProfileCard username="ZAEX5G" riskValue="Muy bajo" points="500 pts" /></div>
        <Wallet variant={variant} />
      </div>}

      {sober ? null : <>{activity}{subaspass}</>}
      <QuickView r={quick && { ...quick, ...over[quick.id] }} onClose={closeQuick} closeSignal={terminalCloseSignal}
        go={(() => { const k = quick && negIdOf(quick.id), n = k ? negs[k] : undefined;
          return chatOpen && quick && n?.state === "aceptada" ? { href: detailHref(quick, n.amount, n.side === "vende" ? "vendedor" : "comprador"), mode: ac.go } : undefined; })()}
        neg={quick && negs[quick.id] ? (() => {
          const ids = peersOf(quick.id), peers = ids.length > 1 ? ids.map((k) => ({ id: k, n: negs[k] })) : undefined, cur = negIdOf(quick.id);
          if (!cur) return <NegList back={back} peers={peers ?? []} onPick={(k) => { setBack(false); setNegs((m) => ({ ...m, [k]: { ...m[k], unread: false } })); setPick((m) => ({ ...m, [quick.id]: k })); }} />;
          return <NegPanel n={negs[cur]} coins={withData ? 1250 : 0} chat={negs[cur].side === "compra" && negs[cur].state === "aceptada" ? chatHref(quick, negs[cur].amount, "comprador") : undefined} autoFee={autoFee} chatReady={Boolean(quick?.chatMessage)} chatMessageText={quick?.chatText} purchaseConfirmed={Boolean(over[quick.id]?.purchaseConfirmed ?? quick.purchaseConfirmed)} onSim={cur ? (k) => simBuyer(quick.id, cur, k) : undefined} onDone={(n, x) => negDone(quick.id, cur, n, x)} onClosed={(n, expired) => finishRejectedNegotiation(quick.id, cur, n, expired)} onFeePaid={() => keepAcceptedInPurchases(quick.id, negs[cur], true)} onPurchaseConfirmed={negs[cur].side === "compra" ? () => registerConfirmedPurchase(quick.id, negs[cur]) : undefined} onCancel={closeQuick} peers={peers} active={cur} onChatOpen={setChatOpen}
            onBack={peers ? () => { setBack(true); setPick((m) => ({ ...m, [quick.id]: "" })); } : undefined} />; /* "" = la lista (si no, la aceptada se reabre sola) */
        })() : undefined} />
      {going ? <div role="status" aria-live="polite" style={{ position: "fixed", inset: 0, zIndex: 100, display: "grid", placeItems: "center", background: "rgba(34,0,92,.55)", color: "#fff", fontSize: 20, fontWeight: 700 }}>
        {going}</div> : null}
      {toast ? <div className="g-toast" role="status" aria-live="polite"><img src={PHOTO[BUY.photo]} alt="" /><p><b>{toast.title}</b><small>{toast.sub}</small></p>
        <span className="g-toast__cta"><Button variant="negotiable" onClick={toast.go}>{toast.act}</Button></span>
        <button type="button" className="g-toast__x" aria-label="Cerrar aviso" onClick={() => setToast(null)}><svg width="14" height="14" viewBox="0 0 20 20" aria-hidden><path d="M5 5l10 10M15 5L5 15" stroke="currentColor" strokeWidth="2" strokeLinecap="round" /></svg></button></div> : null}
      {vmc ? <><WalletLab v={bill} set={pickBill} /><PillLab color={pill} forma={forma} setColor={pickPill} setForma={pickForma} etapas={etapas} setEtapas={pickEtapas} indicio={indicio} setIndicio={pickIndicio} />
        <SalidaLab v={salida} ms={salidaMs} espera={salidaEspera} set={pickSalida} setMs={pickSalidaMs} setEspera={pickSalidaEspera} probar={probarSalida} /></> : null}
      {sent ? <><FocoLayer f={foco} photo={PHOTO[BUY.photo]} car={`${BUY.name} ${BUY.year}`} amount={usd(sent)} /><FocoPanel f={foco} onPick={pickFoco} /></> : null}
      {sent ? <LabPanel title="Demo · Simula comprador" store="mg-simular" className="f-sw--buy f-sw--sim-buy" side="right" defaultOpen>
        <div className="f-sw__g" role="group" aria-label="Flujo de aceptación" data-acts><span className="f-sw__k"><b>Flujo</b> · Vendedor acepta → SubasChat</span>
          <button type="button" disabled={negs.bp1?.state !== "enviada"} onClick={() => reply("acepta")}>Vendedor acepta</button>
          <small className="f-sw__hint">La propuesta aceptada permanece en Compras y desde ahí abre el acceso al chat.</small></div>
        <div className="f-sw__g" role="group" aria-label="Envío del comprador" data-acts><span className="f-sw__k"><b>Envío del comprador</b> · Nissan Sentra</span>
          <button type="button" onClick={sendBuyerProposal}>Propuesta enviada<small>{usd(propuesta ?? 0)} · 1/5</small></button>
          <small className="f-sw__hint">Demo: se resalta la fila enviada arriba. Haz clic en ella para abrir el chat.</small></div>
        <div className="f-sw__g" role="group" aria-label="Llegada posterior" data-acts><span className="f-sw__k"><b>Al volver a Mi Garaje</b> · sin abrir</span>
          <button type="button" onClick={simulatePastSellerRejection}>Vendedor rechazó tu propuesta<small>hace 3 h · sin abrir</small></button>
          <button type="button" onClick={simulatePastBuyerExpiry}>La negociación expiró<small>hace 3 h · sin abrir</small></button>
          <small className="f-sw__hint">La caja, la campana y la fila comunican la novedad. Ábrela desde cualquiera de ellas para ver el cierre y la devolución.</small></div>
        <div className="f-sw__g" role="group" aria-label="Otras respuestas del vendedor" data-acts><span className="f-sw__k"><b>Respuestas del vendedor</b> · simulaciones</span>
          <button type="button" disabled={negs.bp1?.state !== "enviada"} onClick={() => reply("contra")}>Contrapropone{negs.bp1 ? <small>{usd(counterOf(negs.bp1.thread[negs.bp1.thread.length - 1].amount))} · {roundOf(negs.bp1)}/5</small> : null}</button>
          <button type="button" onClick={() => simulateSellerRejection(3)}>Rechaza<small>3/5</small></button>
          <button type="button" onClick={() => simulateSellerRejection(5)}>Rechaza<small>5/5</small></button>
          <button type="button" disabled={negs.sf1?.state !== "enviada"} onClick={() => finalRoundReply("contra")}>Contrapropone<small>Picanto · {usd(FINAL_BUY.counter)}</small></button>
          <button type="button" disabled={negs.sf1?.state !== "enviada"} onClick={() => finalRoundReply("rechaza")}>Rechaza la final<small>Picanto · 5/5</small></button>
          <small className="f-sw__hint">El Nissan Sentra permite revisar el rechazo intermedio (3/5) y el final (5/5); el Picanto conserva la contrapropuesta final.</small></div>
        <div className="f-sw__g" role="group" aria-label="Cómo llega la respuesta"><span className="f-sw__k"><b>Aviso</b> · cómo llega la respuesta</span>
          <button type="button" aria-pressed={!notif} onClick={() => setNotif(false)}>Resaltar fila</button>
          <button type="button" aria-pressed={notif} onClick={() => setNotif(true)}>+ Notificación (propuesta)</button>
          <small className="f-sw__hint">{notif ? "Además del resaltado, un aviso arriba con «Ver respuesta» o «Abrir chat»." : "La fila se resalta donde quedó; si aceptó, permanece en Compras."}</small></div>
        <div className="f-sw__g" role="group" aria-label="Mensaje de SubasChat" data-acts><span className="f-sw__k"><b>SubasChat</b> · vendedor</span>
          <button type="button" onClick={() => receiveSubasChatMessage("compra")}>Mensaje nuevo del vendedor</button>
          <small className="f-sw__hint">Prepara el chat si hace falta; llega en Compras y lo abre al tocarla.</small></div></LabPanel> : null}
      {/* 26/10 (Abraham): espejo para el vendedor; responde como comprador a tu última contrapropuesta del Nivus. */}
      {vmc ? (() => { const tgt = [...peersOf("sn0")].reverse().find((k) => negs[k].state === "enviada");
        return <LabPanel title="Simula vendedor" store="mg-simular-v" className="f-sw--buy f-sw--sim-sell" side="right" defaultOpen>
          <div className="f-sw__g" role="group" aria-label="Respuesta del comprador" data-acts><span className="f-sw__k"><b>Responde</b> · tu contrapropuesta del Volkswagen Nivus{tgt ? ` (${negs[tgt].buyer})` : ""}</span>
            {([["contra-3", "Comprador contrapropone", "3/5"], ["contra-5", "Comprador contrapropone", "5/5"], ["seller-rechaza-3", "Vendedor rechaza", "3/5"], ["seller-rechaza-5", "Vendedor rechaza", "5/5"], ["expira-con-activas", "Expira una propuesta", "quedan activas"], ["expira-ultima", "Expira última propuesta", "se cierra"], ["acepta-pendiente", "Comprador acepta", "pago pendiente"], ["acepta-pagado", "Comprador acepta", "fee pagado"]] as const).map(([k, l, m]) => <button key={k} type="button" onClick={() => launchSellerResponse(k)}>{l}{m ? <small>{m}</small> : null}</button>)}
            <small className="f-sw__hint">{tgt ? "Solo para el lab: en VMC lo envía el comprador." : "Simula una llegada; abre la notificación nueva para ver su historial."}</small></div>
          <div className="f-sw__g" role="group" aria-label="Mensaje de SubasChat" data-acts><span className="f-sw__k"><b>SubasChat</b> · comprador</span>
            <button type="button" onClick={() => receiveSubasChatMessage("vende")}>Mensaje nuevo del comprador</button>
            <small className="f-sw__hint">Prepara el chat si hace falta; llega en Ventas y lo abre al tocarla.</small></div>
          <div className="f-sw__g" role="group" aria-label="Expiración llegada posterior" data-acts><span className="f-sw__k"><b>Expiración</b> · llegó mientras no estabas</span>
            <button type="button" onClick={() => simulatePastSellerExpiry(false)}>Expira una propuesta<small>quedan 2 activas · hace 3 h</small></button>
            <button type="button" onClick={() => simulatePastSellerExpiry(true)}>Expira última propuesta<small>se cierra · hace 3 h</small></button>
            <small className="f-sw__hint">Primero llega a caja, campana y Ventas. Ábrela para ver la animación de cierre.</small></div></LabPanel>; })() : null}
      {/* 26/10 (Abraham): modal de la demo, no del diseño: antes de abrir el chat, elegir cómo se habilitó. */}
      {feeAsk ? <dialog className="lab-ask" aria-labelledby="lab-ask-t" ref={(d) => { if (d && !d.open) d.showModal(); }} onCancel={(e) => { e.preventDefault(); setFeeAsk(null); }}>
        <div className="lab-ask__card"><span className="lab-ask__k">Demo</span>
          <h2 id="lab-ask-t">¿Cómo se habilita el chat?</h2>
          <p>La propuesta fue aceptada. Para abrir el SubasChat, el comprador cubre el fee de habilitación (&gt;S&lt; {DEPOSIT.sc}).</p>
          <button type="button" autoFocus onClick={() => feeAsk(false)}><b>Queda pendiente de pago</b><small>La propuesta queda en Compras hasta que el comprador pague el fee.</small></button>
          <button type="button" onClick={() => feeAsk(true)}><b>Se cobró automáticamente</b><small>Sale de la consignación inicial: animación y chat directo.</small></button>
          <button type="button" className="lab-ask__x" onClick={() => setFeeAsk(null)}>Cancelar</button></div></dialog> : null}
      {vmc ? <CampSwitch lado={ban.lado} riel={ban.riel} set={setBanners} /> : null}
      {vmc ? <PagLab /> : null}
      {vmc ? <PubActionsLab /> : null}
      {vmc ? <AcuerdoLab onTry={() => { launchSellerResponse("acepta-pagado"); const r = secs.flatMap((s) => s.rows).find((x) => x.id === "sn0");
        if (r) window.setTimeout(() => openRow(r), 150); }} /> : null}
      {sideSlot ? createPortal(<Promo key={ban.lado} slot="side" view={side} veh={veh} b={pieza(ban.lado)!} />, sideSlot) : null}
    </main>
  </Chrome>;
}

:root {
  --background: #f7f7fb;
  --foreground: #191c1c;

  /* Tokens de marca Concorde/VMC usados por los componentes en src/concorde/. */
  --vmc-font-display: var(--font-jakarta), "Plus Jakarta Sans", -apple-system, sans-serif;
  --vmc-color-vault-400: #ae8eff;
  --vmc-color-vault-500: #8460e5;
  --vmc-color-vault-600: #5a35c2;
  --vmc-color-vault-700: #3b1782;
  --vmc-color-vault-900: #22005c;
  --vmc-color-orange-400: #fbc47d;
  --vmc-color-orange-600: #ed8936;
  --vmc-color-orange-700: #d46e20;
  --vmc-color-teal-500: #00aeb1;
  --vmc-color-teal-600: #009095;
  --vmc-color-base-white: #ffffff;
  --vmc-color-neutral-700: #99a1af;
  --vmc-color-background-disabled: #e1e3e2;
  --vmc-radius-full: 9999px;
}
:root { --vmc-color-cyan-700:#00a8ab; --vmc-color-vault-100:#f5f0ff; --vmc-color-vault-200:#e8deff; --vmc-color-vault-800:#2e0f70; --vmc-color-orange-100:#fff8f1; --vmc-color-orange-200:#fee9cc; --vmc-font-mono:var(--font-roboto-mono), "Roboto Mono", ui-monospace, monospace; }
*,*::before,*::after { box-sizing:border-box; }
html,body { margin:0; }
body { background:var(--background); color:var(--foreground); font-family:var(--vmc-font-display); }
:focus-visible { outline:2px solid var(--vmc-color-vault-500); outline-offset:2px; }
::selection { background:var(--vmc-color-vault-500); color:#fff; }

/* Layout + piezas propuestas. Solo tokens de DESIGN.md (escalas orange / vault / cyan / neutros). */
.kit-shell { display:grid; grid-template-columns:auto minmax(0,1fr); min-height:100vh; }
.kit-shell__main { min-width:0; }
.kit-shell__sidebar { display:flex; }
.kit-shell__mobile-header { display:none; }
.kit-shell__brand { display:flex; align-items:center; gap:12px; }
/* Maqueta VMC: 1024 px centrados; fuera, el violeta del header de VMC (#2e0f70). */
.kit-shell--vmc { max-width:1024px; margin:0 auto; background:var(--background); }
.kit-shell--vmc { grid-template-columns:229px minmax(0,1fr); transition:grid-template-columns .28s cubic-bezier(.4,0,.2,1); will-change:grid-template-columns; }
.kit-shell--vmc .kit-shell__sidebar { width:229px; background:#2E0F70; transition:width .28s cubic-bezier(.4,0,.2,1); will-change:width; overflow:hidden; }
.kit-shell--vmc.kit-shell--collapsed { grid-template-columns:76px minmax(0,1fr); }
.kit-shell--vmc.kit-shell--collapsed .kit-shell__sidebar { width:76px; }
.kit-shell--vmc.kit-shell--collapsed .sbh-logo { display:none; }
.kit-shell--vmc .kit-shell__desktop-header [data-block="header"] { height:56px !important; }
.kit-shell--vmc .kit-shell__desktop-header { position:relative; }
.kit-shell__collapsed-brand { position:absolute; z-index:1; left:28px; top:9px; height:38px; display:flex; align-items:center; pointer-events:none; }
.kit-shell__collapsed-brand img { display:block; width:90px; height:38px; object-fit:contain; }
html:has(.kit-shell--vmc), body:has(.kit-shell--vmc) { background:#2e0f70; }
@media (prefers-reduced-motion:reduce) { .kit-shell--vmc, .kit-shell--vmc .kit-shell__sidebar { transition:none; } }
@media (max-width:1023px) {
  .kit-shell { display:block; }
  .kit-shell__sidebar, .kit-shell__desktop-header { display:none; }
  .kit-shell__mobile-header { display:block; }
}

.kit-page { max-width:1200px; margin:0 auto; padding:40px 40px 64px; display:grid; gap:40px; }
@media (max-width:767px) { .kit-page { padding:20px 16px 48px; gap:28px; } }

/* Encabezados de sección: tipográficos, sin brackets (el bracket queda para el título de página). */
.kit-h { display:flex; align-items:center; justify-content:space-between; gap:12px; flex-wrap:wrap; }
.kit-h h2 { margin:0; font-size:1.25rem; line-height:1.3; font-weight:700; color:var(--vmc-color-vault-700); letter-spacing:-0.01em; text-wrap:balance; }
.kit-h p { margin:2px 0 0; font-size:.8125rem; color:color-mix(in srgb,#191C1C 66%,#fff); }

/* Superficies: sombra estándar del DS con offset suave para dar dirección de luz. */
.kit-card { background:#fff; border-radius:16px; box-shadow:0 2px 6px rgba(34,0,92,.04), 0 8px 24px rgba(34,0,92,.06); padding:20px; }

.kit-tag { display:inline-flex; align-items:center; gap:6px; width:max-content; padding:3px 10px; border-radius:9999px; font-size:.75rem; font-weight:600; line-height:1rem; font-variant-numeric:tabular-nums; }
.kit-tag--live { background:#FEE9CC; color:#93420A; }
.kit-tag--urgent { background:#FFF8F1; color:#B25614; box-shadow:inset 0 0 0 1px #FDD8A4; }
.kit-tag--negotiable { background:color-mix(in srgb,#00A8AB 11%,#fff); color:#006466; }
.kit-tag--vault { background:#F5F0FF; color:#5A35C2; }
.kit-tag--neutral { background:color-mix(in srgb,#E1E3E2 55%,#fff); color:color-mix(in srgb,#191C1C 82%,#fff); }
.kit-tag__dot { width:6px; height:6px; border-radius:9999px; background:#ED8936; animation:kit-pulse 1.4s ease-in-out infinite; }
@keyframes kit-pulse { 50% { opacity:.3; } }

.kit-newbadge { display:inline-flex; align-items:center; gap:6px; padding:2px 10px 2px 8px; border-radius:9999px; font-size:.75rem; font-weight:700; color:#006466; background:color-mix(in srgb,#00A8AB 11%,#fff); }
.kit-newbadge i { width:7px; height:7px; border-radius:9999px; background:#00A8AB; }

.kit-thumbs { display:inline-flex; align-items:center; }
.kit-thumbs img { width:28px; height:28px; border-radius:9999px; object-fit:cover; box-shadow:0 0 0 2px #fff; }
.kit-thumbs img + img { margin-left:-8px; }
.kit-thumbs b { margin-left:6px; font-size:.75rem; color:#5A35C2; }

.kit-chev { color:#ED8936; flex:none; transition:transform .2s cubic-bezier(.2,.8,.2,1); }
.kit-chev.is-open { transform:rotate(90deg); }

/* Fila de vehículo */
.kit-list { display:grid; }
.kit-row { position:relative; display:grid; grid-template-columns:80px minmax(0,1fr) auto; gap:14px; align-items:center; padding:12px; margin:0 -12px; border-radius:12px; transition:background-color .18s ease-out; }
.kit-row + .kit-row::before { content:""; position:absolute; top:0; left:106px; right:12px; height:1px; background:#E1E3E2; }
.kit-row:hover { background:#F5F0FF; }
.kit-row:hover + .kit-row::before, .kit-row:hover::before { opacity:0; }
.kit-row--new { background:color-mix(in srgb,#00A8AB 6%,#fff); animation:kit-arrive 1.6s cubic-bezier(.16,1,.3,1) both; }
@keyframes kit-arrive { from { background:color-mix(in srgb,#00A8AB 22%,#fff); transform:translateY(-6px); } to { background:color-mix(in srgb,#00A8AB 6%,#fff); transform:none; } }
.kit-row__photo { width:80px; height:60px; object-fit:cover; border-radius:10px; }
.kit-row__body { display:grid; gap:4px; min-width:0; }
.kit-row__title { display:flex; gap:8px; align-items:baseline; }
.kit-row__link { color:var(--vmc-color-vault-700); font-size:.9375rem; font-weight:700; text-decoration:none; }
.kit-row__link::after { content:""; position:absolute; inset:0; border-radius:12px; }
.kit-row__link:focus-visible { outline:none; }
.kit-row__link:focus-visible::after { outline:2px solid #8460E5; outline-offset:0; }
.kit-row__new { font-size:.6875rem; font-weight:700; letter-spacing:.06em; text-transform:uppercase; color:#008688; }
.kit-row__meta { font-size:.8125rem; color:color-mix(in srgb,#191C1C 82%,#fff); font-variant-numeric:tabular-nums; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.kit-row__plate { color:color-mix(in srgb,#191C1C 66%,#fff); }
.kit-row__tags { display:flex; gap:6px; flex-wrap:wrap; margin-top:2px; }
.kit-row__action { position:relative; z-index:1; }
@media (max-width:519px) {
  .kit-row { grid-template-columns:64px minmax(0,1fr); gap:12px; align-items:start; }
  .kit-row + .kit-row::before { left:88px; }
  .kit-row__photo { width:64px; height:52px; }
  .kit-row__meta { white-space:normal; }
  .kit-row__action { grid-column:2; }
}

.kit-body { display:grid; gap:14px; }
.kit-body > .pprofilebtn, .kit-body > a { justify-self:start; }

.kit-empty { display:grid; gap:14px; justify-items:start; padding:4px 0 8px; }
.kit-empty p { margin:0; max-width:52ch; font-size:.875rem; line-height:1.5; color:color-mix(in srgb,#191C1C 82%,#fff); }

.kit-skel { display:grid; gap:14px; }
.kit-skel__row { display:grid; grid-template-columns:80px 1fr; gap:14px; align-items:center; }
.kit-skel__row i, .kit-skel__row b { display:block; border-radius:10px; background:linear-gradient(90deg,color-mix(in srgb,#E1E3E2 55%,#fff) 0%,#F5F0FF 50%,color-mix(in srgb,#E1E3E2 55%,#fff) 100%) 0 0/200% 100%; animation:kit-shimmer 1.4s linear infinite; }
.kit-skel__row i { height:60px; }
.kit-skel__row div { display:grid; gap:8px; }
.kit-skel__row b { height:12px; width:60%; } .kit-skel__row b + b { width:85%; }
@keyframes kit-shimmer { to { background-position:-200% 0; } }

/* Perfil compacto */
.kit-profile { display:grid; gap:14px; background:#fff; border-radius:16px; box-shadow:0 2px 6px rgba(34,0,92,.04), 0 8px 24px rgba(34,0,92,.06); padding:18px 20px; }
.kit-profile__hello { display:flex; align-items:center; gap:10px; color:var(--vmc-color-vault-700); font-size:1rem; }
.kit-profile__stats { display:flex; gap:28px; margin:0; padding-top:14px; border-top:1px solid #E1E3E2; }
.kit-profile__stats > div { display:grid; gap:2px; }
.kit-profile__stats dt { font-size:.6875rem; font-weight:600; color:color-mix(in srgb,#191C1C 66%,#fff); letter-spacing:.04em; text-transform:uppercase; }
.kit-profile__stats dd { margin:0; display:flex; align-items:center; gap:4px; font-size:.875rem; font-weight:700; color:var(--vmc-color-vault-700); }
.kit-profile__risk { color:#D46E20!important; }
.kit-profile__links { display:flex; gap:20px; flex-wrap:wrap; }
.kit-profile--inline { grid-template-columns:auto 1fr auto; align-items:center; gap:24px; }
.kit-profile--inline .kit-profile__stats { border-top:0; padding-top:0; padding-left:24px; border-left:1px solid #E1E3E2; }
@media (max-width:767px) {
  .kit-profile--inline { grid-template-columns:1fr; gap:14px; }
  .kit-profile--inline .kit-profile__stats { border-left:0; padding-left:0; border-top:1px solid #E1E3E2; padding-top:14px; }
}

/* Superficies del navegador */
* { scrollbar-width:thin; scrollbar-color:rgba(153,161,175,.6) transparent; }
::selection { background:#8460E5; color:#fff; }

@media (prefers-reduced-motion:reduce) {
  .kit-tag__dot, .kit-row--new, .kit-skel__row i, .kit-skel__row b { animation:none; }
  .kit-chev, .kit-row { transition:none; }
}

/* Gallery */
.kit-gal { display:grid; gap:8px; }
.kit-gal__main { position:relative; overflow:hidden; background:#100030; }
.kit-gal__main img { width:100%; height:100%; object-fit:cover; display:block; }
.kit-gal__nav { all:unset; cursor:pointer; position:absolute; top:50%; translate:0 -50%; display:grid; place-items:center; width:36px; height:36px; border-radius:9999px; color:#fff; background:rgba(16,0,48,.5); backdrop-filter:blur(6px); transition:background-color .15s; }
.kit-gal__nav:hover { background:rgba(16,0,48,.75); }
.kit-gal__nav:focus-visible { outline:2px solid #fff; outline-offset:2px; }
.kit-gal__nav--prev { left:12px; } .kit-gal__nav--next { right:12px; }
.kit-gal__count { position:absolute; left:12px; bottom:12px; padding:3px 10px; border-radius:9999px; font-size:.75rem; font-weight:700; color:#fff; background:rgba(16,0,48,.55); font-variant-numeric:tabular-nums; }
.kit-gal__thumbs { display:flex; gap:6px; padding:0 24px; }
.kit-gal__thumbs button { all:unset; cursor:pointer; width:64px; height:46px; border-radius:8px; overflow:hidden; opacity:.6; box-shadow:inset 0 0 0 2px transparent; transition:opacity .15s; }
.kit-gal__thumbs button img { width:100%; height:100%; object-fit:cover; display:block; }
.kit-gal__thumbs button:hover { opacity:.9; }
.kit-gal__thumbs button[aria-selected="true"] { opacity:1; outline:2px solid #ED8936; outline-offset:-2px; }
.kit-gal__thumbs button:focus-visible { outline:2px solid #8460E5; outline-offset:2px; }
@media (max-width:767px) { .kit-gal__thumbs { padding:0 16px; } }

/* Override (propuesta para Julio): el SidebarMobile de Concorde cerrado deja asomar su sombra de 40px por el borde izquierdo. */
.sbm-panel:not(.sbm-panel--open) { box-shadow:none; }

"use client";

/**
 * Piezas compartidas por los modelos A/B/C: datos de ejemplo, chrome de navegación
 * (Header + Sidebar de Concorde) y piezas PROPUESTAS que no existen en Concorde
 * (VehicleRow, StatusTag, Thumbs, Chevron, Skeleton). Caso para revisar con Julio.
 */
import { useState } from "react";
import type { JSX, ReactNode } from "react";
import Header from "@/concorde/bloques/header/desktop/Header";
import { NotifBand, NotifFloat, NotifHeader, NotifProvider } from "./Notifs";
import Sidebar, { type SidebarNavItem } from "@/concorde/bloques/sidebar/desktop/Sidebar";
import SidebarMobile, { SidebarMenuButton } from "@/concorde/bloques/sidebar/mobile/SidebarMobile";
import TodayIcon from "@/concorde/components/TodayIcon";
import OfferIcon from "@/concorde/components/OfferIcon";
import CategoryIcon from "@/concorde/components/CategoryIcon";
import BusinessIcon from "@/concorde/components/BusinessIcon";
import AvatarZone from "@/concorde/components/AvatarZone";
import StarIcon from "@/concorde/components/StarIcon";
import InfoIcon from "@/concorde/components/InfoIcon";
import ProfileButton from "@/concorde/components/ProfileButton";
import TabSelector from "@/concorde/components/TabSelector";
import Button from "@/concorde/components/Button";

// ─── Datos de ejemplo ────────────────────────────────────────────────────────
export type Tone = "live" | "negotiable" | "vault" | "neutral" | "urgent";
export type Item = {
  id: string; name: string; year: number; plate: string; photo: string;
  status: string; tone: Tone; detail: string; cta: string; deadline?: string; urgent?: boolean; isNew?: boolean; group?: string;
};
export type SectionId = "negociaciones" | "participaciones" | "compras" | "publicaciones" | "valorizaciones";
export type Section = { id: SectionId; title: string; hint: string; summary: string; empty: string; emptyCta?: string; groups?: string[]; items: Item[] };
export type ModelProps = { withNews: boolean; isEmpty: boolean; isLoading: boolean };

export function sections({ withNews, isEmpty }: ModelProps): Section[] {
  const s: Section[] = [
    { id: "negociaciones", title: "Mis negociaciones", hint: "Ofertas recibidas y enviadas",
      summary: withNews ? "1 por responder · vence hoy" : "2 esperando respuesta",
      empty: "Cuando recibas o envíes una oferta en una publicación negociable, la seguirás aquí.", items: [
      ...(withNews ? [{ id: "n0", name: "Toyota Corolla", year: 2019, plate: "BXT-231", photo: "corolla" as const, status: "Propuesta recibida", tone: "negotiable" as Tone,
        detail: "Te ofrecen US$ 9,800", deadline: "Vence hoy 23:59", cta: "Responder", urgent: true, isNew: true }] : []),
      { id: "n1", name: "Toyota Etios", year: 2020, plate: "AEU-804", photo: "etios", status: "Esperando respuesta", tone: "neutral", detail: "Contraoferta enviada · US$ 7,200", cta: "Ver" },
      { id: "n2", name: "Kia Rio", year: 2021, plate: "CDF-112", photo: "corolla", status: "Esperando respuesta", tone: "neutral", detail: "Propuesta enviada · US$ 8,100", cta: "Ver" },
    ] },
    { id: "participaciones", title: "Mis participaciones", hint: "Subastas en las que consignaste", summary: "1 en vivo ahora",
      empty: "Cuando consignes para participar en una subasta, la verás aquí.", groups: ["En vivo", "Rechazadas"], items: [
      { id: "p1", name: "Hyundai Accent", year: 2018, plate: "F4K-220", photo: "etios", status: "En vivo", tone: "live", detail: "Sala abierta", deadline: "Cierra en 00:42:10", cta: "Ir a la Sala", urgent: true, group: "En vivo" },
      { id: "p2", name: "Nissan Versa", year: 2017, plate: "ABC-901", photo: "corolla", status: "Rechazada", tone: "neutral", detail: "Consignación devuelta a tu Wallet", cta: "Ver", group: "Rechazadas" },
