@media (prefers-reduced-motion:reduce) { .nt-box--arriving { animation:none; } }
.nt-tab { right:max(0px, calc((100vw - 1024px) / 2)); display:grid; place-items:center; width:48px; height:48px; padding:0 0 0 4px; border:2px solid rgba(255,255,255,.7); border-right:0;
  border-radius:24px 0 0 24px; background:var(--nt-primary); color:#fff; cursor:pointer; box-shadow:0 6px 18px rgba(34,0,92,.3); animation:nt-tab .5s cubic-bezier(.34,1.56,.64,1) both; }
