  box-shadow:rgba(255,255,255,.28) 0 1px 0 2px inset, 0 10px 24px rgba(132,96,229,.4), 0 4px 10px rgba(237,137,54,.35); transition:transform .2s cubic-bezier(.25,.8,.25,1); }
.nt-fab:hover { transform:translateY(-2px) scale(1.04); } .nt-fab .nt-badge { top:-2px; right:-2px; box-shadow:0 0 0 2px #fff, 0 2px 8px rgba(255,0,102,.45); }
