.nt-fab-wrap:has(.nt-inbox) .nt-fab__hello { display:none; }
.nt-inbox--fab { position:absolute; top:auto; bottom:calc(100% + 10px); right:0; transform-origin:calc(100% - 28px) 100%; }

/* ── Panel del lab: LabPanel en el dock izquierdo (receta .f-sw de garaje.css); aquí solo lo propio ── */
.nt-sw__now { min-height:30px; padding:0 12px; border:0; border-radius:9999px; background:var(--nt-mag); color:#fff; font:inherit; font-size:.75rem; font-weight:700; cursor:pointer; }
