}
.f-sw__g button:disabled { opacity:.45; cursor:default; }
@media (max-width:600px) {
  /* Simulador del lab en una sola fila al pie, para no tapar Tu actividad. */
  .f-sw--buy { left:16px; right:16px; bottom:16px; max-width:none; padding:8px 12px; gap:4px; }
  .f-sw--buy .f-sw__bar { display:none; }
