"use client";

/**
 * Comprador · paso 1 (21/10, pedido de Julio): el detalle de una oferta Negociable y la primera propuesta.
 * El DetailCard de Concorde se queda tal cual; «Negocia ahora» abre un modal como el de VMC («Modales Negociable.svg»:
 * Propuesta 1/5 · Consignación · Digita el monto · Proponer), pero en un paso: el botón ya confirma el monto.
 * Al enviar → Mi Garaje (/m/vmc?propuesta=…), donde un aviso señala la fila en la que llegará la respuesta del vendedor.
 * Reglas (skill vmc-modelo-negocio): la Negociable no tiene Precio Base ni Reserva, se propone libremente (C. de Ayuda);
 * la consignación la fija cada oferta, en SubasCoins o dólares (T&C IV.6.2.a; C. de Ayuda); 24 h por propuesta (IV.6.2.f),
 * 5 rondas (IV.6.2.e); la respuesta se sigue en Tu actividad, que en Mi Garaje es Mis negociaciones.
 */
import { useEffect, useRef, useState } from "react";
import type { JSX, MouseEvent } from "react";
import Detalle, { type DetalleProps } from "@/concorde/bloques/detalle/desktop/Detalle";
import DetailCard from "@/concorde/components/DetailCard";
import Button from "@/concorde/components/Button";
import InfoIcon from "@/concorde/components/InfoIcon";
import TimerIcon from "@/concorde/components/TimerIcon";
import { Vidrio } from "@/concorde/components/Vidrio";
import { Chrome, photosOf } from "./kit";
import "./subaschat.css";
import "./propuesta.css";

// Oferta de ejemplo (la misma que entra como fila nueva en Mis negociaciones). `list` es el precio que el vendedor
// tiene en mente: lo usa el simulador del vendedor, el comprador no lo ve.
export const BUY = { name: "Nissan Sentra", year: 2020, plate: "BQZ-418", photo: "sentra", list: 15900 };
// ponytail: consignación de ejemplo (la de la captura real «S< 60 ó US$ 180»); en producción viene de la oferta.
export const DEPOSIT = { sc: 50, usd: 180 }; // 23/10 (Abraham): la consignación pasa a >S< 50
const COINS = 1250;
const usd = (n: number) => `US$ ${n.toLocaleString("en-US")}`;

/** Enviada: cuenta atrás de 5 s y, al llegar a 0, a Mi Garaje (el botón salta la espera). */
function useGoGarage(active: boolean, amount: number): [number, () => void] {
  const [left, setLeft] = useState(5);
  const go = () => { location.href = `/blocks/mi-garaje/m/vmc?propuesta=${amount}`; };
  useEffect(() => {
    if (!active) return;
    setLeft(5);
    const t = setInterval(() => setLeft((n) => n - 1), 1000);
    return () => clearInterval(t);
  }, [active]);
  useEffect(() => { if (active && left <= 0) go(); }, [active, left]);
  return [Math.max(left, 0), go];
}

/** Avisos del flujo (23/10, Abraham): los de VMC (FondosInsuficientes, Notification) con el diseño de la propuesta:
 *  ícono esmerilado, cerrar cian y la consignación en cian. Sin «Realizar una recarga»: es lo mismo que adquirir SubasCoins. */
const NOTICES = {
  fondos: { label: "SubasCoins insuficientes", icon: "bolsa", title: "Fondos insuficientes", btn: "Adquiere SubasCoins" },
  cerrada: { label: "Ya no disponible", icon: "aviso", title: "Aviso", msg: "Esta negociación ya no está disponible.", btn: "Aceptar" },
  error: { label: "Imposible procesar", icon: "aviso", title: "Aviso", msg: "Imposible procesar la propuesta.", btn: "Aceptar" },
} as const;
type Notice = keyof typeof NOTICES;

function NoticeDialog({ kind, open, onClose }: { kind: Notice; open: boolean; onClose: () => void }): JSX.Element {
  const ref = useRef<HTMLDialogElement>(null);
  useEffect(() => { const d = ref.current; if (!d) return; if (open && !d.open) d.showModal(); if (!open && d.open) d.close(); }, [open]);
  const n = NOTICES[kind];
  return <dialog ref={ref} className="va vh" aria-labelledby="vn-title" onClose={onClose}>
    <div className="va__card vn">
      <button type="button" className="va__x va__x--neg" aria-label="Cerrar" onClick={onClose} />
      <span className="vd-host vh__icon"><Vidrio s={n.icon} size={40} /></span>
      <h2 id="vn-title">{n.title}</h2>
      {kind === "fondos" ? <>
        {/* 23/10 (Abraham): jerarquía igual a la propuesta: etiqueta gris chica, monto grande en cian. */}
        <p className="vh__fee vn__fee"><span className="vh__fee-label">Consignación</span><b>&gt;S&lt; {DEPOSIT.sc} ó {usd(DEPOSIT.usd)}</b></p>
        <p className="vh__sub">Recuerda: US$ 1 es igual a &gt;S&lt; 1 SubasCoin</p>
      </> : "msg" in n ? <p className="vn__msg">{n.msg}</p> : null}
      {n.btn ? <Button type="button" variant="secondary" className="vh__btn vn__btn" autoFocus onClick={onClose}>{n.btn}</Button> : null}
    </div>
  </dialog>;
}

/** Propuesta (21/10, Abraham: «la híbrida como propuesta»): la identidad del ConfirmModal de VOYAGER (tarjeta 320, cerrar
 *  naranja, campo de vidrio, botón violeta de Concorde, «Propuesta enviada» dentro del modal) con el contenido corregido:
 *  un paso (el monto va en el botón), ronda, sin precio base, y consignación y plazo explicados en su propio bloque.
 *  Ícono esmerilado de «negociaciones» (Vidrio.tsx), el mismo de Mis negociaciones, donde el comprador sigue la respuesta. */
/** `fail` (lab): el aviso que sale al presionar Enviar en Confirma, que es cuando VMC valida saldo y oferta. */
function HybridDialog({ open, origin, onCancel, onSend, fail, onFail }: { open: boolean; origin: { x: number; y: number } | null; onCancel: () => void; onSend: (amount: number) => void; fail?: Notice; onFail?: (n: Notice) => void }): JSX.Element {
  const ref = useRef<HTMLDialogElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const [amountText, setAmountText] = useState("");
  const val = Number(amountText) || 0;
  const formattedAmount = amountText ? (() => {
    const [whole = "", decimals] = amountText.split(".");
    const grouped = (whole || "0").replace(/^0+(?=\d)/, "").replace(/\B(?=(\d{3})+(?!\d))/g, ",");
    return decimals === undefined ? grouped : `${grouped}.${decimals}`;
  })() : "";
  const [step, setStep] = useState<"monto" | "confirma" | "procesa" | "celebra" | "celebra-salida" | "enviada">("monto");
  const sent = step === "enviada";
  const [left, go] = useGoGarage(sent, val);
  useEffect(() => {
    const d = ref.current;
    if (!d) return;
    let timer = 0;
    if (open && !d.open) {
      setAmountText("");
      setStep("monto");
      const x = origin?.x ?? window.innerWidth / 2;
      const y = origin?.y ?? window.innerHeight / 2 + 24;
      d.style.setProperty("--vh-from-x", `${x - window.innerWidth / 2}px`);
      d.style.setProperty("--vh-from-y", `${y - window.innerHeight / 2}px`);
      d.classList.add("is-origin-open");
      d.showModal();
      timer = window.setTimeout(() => d.classList.remove("is-origin-open"), 720);
    }
    if (!open && d.open) d.close();
    return () => window.clearTimeout(timer);
  }, [open, origin]);
  useEffect(() => {
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const next = step === "procesa" ? "celebra" : step === "celebra" ? "celebra-salida" : step === "celebra-salida" ? "enviada" : null;
    if (!next) return;
    const duration = reduced ? 180 : step === "procesa" ? 650 : step === "celebra" ? 1450 : 420;
    const timer = window.setTimeout(() => setStep(next), duration);
    return () => window.clearTimeout(timer);
  }, [step]);
  const setAmount = (next: string) => setAmountText(next.replace(/[^\d.]/g, "").replace(/(\..*)\./g, "$1").slice(0, 10));
  const pressKey = (key: string) => {
    setAmountText((current) => key === "back" ? current.slice(0, -1) : key === "." ? (current.includes(".") ? current : `${current || "0"}.`) : `${current}${key}`.slice(0, 10));
    inputRef.current?.focus();
  };
  const close = <button type="button" className="va__x va__x--neg" aria-label="Cerrar" onClick={sent ? () => onSend(val) : onCancel} />;
  const icon = <span className="vd-host vh__icon"><Vidrio s="negociaciones" size={40} /></span>;
  return <dialog ref={ref} className="va vh" aria-labelledby="vh-title" onClose={sent ? () => onSend(val) : onCancel}>
    {sent ? <div className="va__card vh__sent" role="status">{close}{icon}
      {/* Enviada (22/10, Abraham): UX writing del modal actual de VMC, con el diseño de Confirma. */}
      <h2 id="vh-title">Propuesta enviada</h2>
      <div className="vh__ticket"><p className="vh__amount"><span>US$</span>{val.toLocaleString("en-US")}</p></div>
      <p className="vh__sub vh__confirm">Esperando respuesta, expira en 24 horas</p>
      <Button type="button" variant="negotiable" className="vh__btn" autoFocus onClick={go}>Ir a Mi Garaje ({left})</Button>
    </div> : step === "procesa" ? <div className="va__card vh__processing" role="status" aria-live="polite">{close}
      <div className="vh__loader" aria-hidden><i /><i /><i /></div>
      <h2 id="vh-title">Enviando tu oferta</h2>
      <p className="vh__sub">Estamos registrando tu propuesta…</p>
    </div> : step === "celebra" || step === "celebra-salida" ? <div className={`va__card vh__celebrate${step === "celebra-salida" ? " is-leaving" : ""}`} role="status" aria-live="assertive">{close}
      <div className="vh__celebrate-stage" aria-hidden><i /><i /><i /><i /><i /><i /><i /><i />
        <span className="vh__celebrate-check"><svg width="38" height="38" viewBox="0 0 40 40" fill="none"><path d="M11 20.5l6 6L29.5 14" stroke="currentColor" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round" /></svg></span>
      </div>
      <p className="vh__celebrate-kicker">¡Oferta enviada!</p>
      <h2 id="vh-title" className="vh__celebrate-amount"><span>US$</span>{val.toLocaleString("en-US")}</h2>
      <p className="vh__sub">Estamos registrando tu propuesta…</p>
    </div> : step === "confirma" ? <div className="va__card">{close}{icon}
      {/* Confirma (22/10, Abraham): el contenido y los textos del modal actual de VMC, solo con el diseño de la propuesta. */}
      <h2 id="vh-title">Confirma tu propuesta</h2>
      <div className="vh__ticket"><p className="vh__amount"><span>US$</span>{val.toLocaleString("en-US")}</p></div>
      <p className="vh__sub vh__confirm">Al enviar la propuesta aceptas las condiciones y términos de uso de nuestro servicio.</p>
      <Button type="button" variant="negotiable" className="vh__btn" autoFocus onClick={() => fail && onFail ? onFail(fail) : setStep("procesa")}>Enviar</Button>
      <button type="button" className="vh__back2" onClick={() => setStep("monto")}>Volver</button>
    </div> : <form className="va__card" aria-describedby="vh-sub" onSubmit={(e) => { e.preventDefault(); if (val) setStep("confirma"); }}>{close}{icon}
      <span className="vh__round">Propuesta 1 de 5<i aria-hidden>{[0, 1, 2, 3, 4].map((i) => <b key={i} className={i < 1 ? "is-on" : ""} />)}</i></span>
      <h2 id="vh-title">¿Cuánto ofreces?</h2>
      <p id="vh-sub" className="vh__sub">{BUY.name} {BUY.year}</p>
      <label className="va__input vh__input"><span>US$</span><input ref={inputRef} autoFocus inputMode="decimal" placeholder="0" aria-label="Tu propuesta en US$" value={formattedAmount}
        onChange={(e) => setAmount(e.target.value)} /></label>
      <div className="vh__pinpad" role="group" aria-label="Teclado numérico para propuesta">{["1", "2", "3", "4", "5", "6", "7", "8", "9", ".", "0", "back"].map((key) =>
        <button key={key} type="button" className={key === "back" ? "vh__pinpad-back" : ""} aria-label={key === "back" ? "Borrar último dígito" : key === "." ? "Separador decimal" : key} onClick={() => pressKey(key)}>{key === "back" ? "⌫" : key}</button>)}</div>
      <p className="vh__fee"><span className="vh__fee-label">Consignación<span className="vh__fee-info"><button type="button" aria-label="¿Qué es la consignación?" aria-describedby="vh-fee-tip"><InfoIcon size={16} /></button><span id="vh-fee-tip" role="tooltip">Es una garantía en SubasCoins que respalda tu propuesta. Si no hay acuerdo, se libera la consignación y vuelve a tu billetera.</span></span></span><b>&gt;S&lt; {DEPOSIT.sc}</b></p>
      <Button type="submit" variant="negotiable" className="vh__btn" disabled={!val}>Enviar oferta</Button>
    </form>}
  </dialog>;
}

export default function Propuesta({ modal = "propuesta", disclaimer }: { modal?: string; disclaimer?: string }): JSX.Element {
  // 23/10 (Abraham): sale «Actual VMC»; el panel muestra la propuesta y sus avisos (?modal=fondos|cerrada|error).
  const [kind, setKind] = useState<"propuesta" | Notice>(modal in NOTICES ? modal as Notice : "propuesta");
  const [form, setForm] = useState(false);
  const [notice, setNotice] = useState<Notice | null>(null); // aviso que salió al enviar
  const [origin, setOrigin] = useState<{ x: number; y: number } | null>(null);
  const [going, setGoing] = useState(0);
  const openProposal = (event: MouseEvent<HTMLButtonElement>) => {
    const rect = event.currentTarget.getBoundingClientRect();
    setOrigin({ x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 });
    setForm(true);
  };
  const send = (amount: number) => {
    setForm(false); setGoing(amount);
    setTimeout(() => { location.href = `/blocks/mi-garaje/m/vmc?propuesta=${amount}`; }, 1400);
  };
  const initialSafetyPlacement: NonNullable<DetalleProps["safetyPlacement"]> = disclaimer === "gallery" ? "gallery" : disclaimer === "info" ? "info" : disclaimer === "conditions" ? "conditions" : disclaimer === "banner" ? "banner" : disclaimer === "related" ? "related" : "teaser";
  const [safetyPlacement, setSafetyPlacement] = useState<NonNullable<DetalleProps["safetyPlacement"]>>(initialSafetyPlacement);
  return <Chrome vmc>
    <main className="of-main">
      <Detalle variant="negotiable" safetyPlacement={safetyPlacement} offer={{
        title: `${BUY.name} ${BUY.year}`, subtitle: `Placa ${BUY.plate}`, images: photosOf(BUY.photo), visits: false,
        detailSlot: <DetailCard variant="negotiable" miniBanner={{ src: "/mi-garaje/banners/publica/mini-publica@2x.png", alt: "¿Vendes tu auto? Recibe propuestas y tú eliges.", href: "/blocks/mi-garaje/m/vmc-publica" }} title={"Este vendedor recibe propuestas\nde compra. Aprovecha esta oportunidad\ne inicia una negociación."} ctaLabel="¡Vamos a negociar!" day="VIERNES 30" time="6:00 pm" views={128} likes={23} participants={2} onParticipate={openProposal} />,
        related: [
          { name: "Toyota Corolla", year: 2019, price: "US$ 14,200", imageSrc: photosOf("corolla")[0], variant: "live" },
          { name: "Mazda 3", year: 2020, price: "US$ 13,500", imageSrc: photosOf("mazda3")[0], variant: "live" },
          { name: "Kia Rio", year: 2021, imageSrc: photosOf("rio")[0], variant: "negotiable" },
          { name: "Suzuki Swift", year: 2022, imageSrc: photosOf("swift")[0], variant: "negotiable" },
        ],
      }} />
    </main>
    {/* 23/10 (Abraham): «Ya no disponible» sale al abrir; fondos insuficientes e imposible procesar, al enviar la propuesta. */}
    {kind === "cerrada" ? <NoticeDialog kind={kind} open={form} onClose={() => setForm(false)} />
      : <HybridDialog open={form} origin={origin} onCancel={() => setForm(false)} onSend={send} fail={kind === "propuesta" ? undefined : kind} onFail={(k) => { setForm(false); setNotice(k); }} />}
    {notice ? <NoticeDialog kind={notice} open onClose={() => setNotice(null)} /> : null}
    <div className="f-sw f-sw--buy pp-sw"><div className="f-sw__bar"><b>Modal de propuesta</b></div>
      <div className="f-sw__g" role="group" aria-label="Modal de propuesta">{([["propuesta", "Propuesta"], ...Object.entries(NOTICES).map(([k, v]) => [k, v.label])] as ["propuesta" | Notice, string][]).map(([k, t]) =>
        <button key={k} type="button" aria-pressed={kind === k} onClick={() => setKind(k)}>{t}</button>)}</div></div>
    <div className="f-sw f-sw--buy pp-sw pp-sw--safety"><div className="f-sw__bar"><b>Ubicación del aviso</b></div>
      <div className="f-sw__g" role="group" aria-label="Ubicación del aviso de seguridad">{([
        ["teaser", "Nube informativa"], ["info", "Bajo información"], ["conditions", "Bajo condiciones"], ["banner", "Sobre SubasCoins"], ["related", "Antes de relacionadas"],
      ] as const).map(([placement, label]) => <button key={placement} type="button" aria-pressed={safetyPlacement === placement} onClick={() => setSafetyPlacement(placement)}>{label}</button>)}</div>
    </div>
    {going ? <div className="pp-going" role="status" aria-live="polite"><b>Propuesta enviada · {usd(going)}</b><span>Te llevamos a Mis negociaciones para que sigas la respuesta…</span></div> : null}
  </Chrome>;
}

"use client";

/**
 * Flujo de una publicación (04/11): qué badge tiene en cada momento, qué acciones da el menú ⋯ y a qué badge lleva cada una.
 * Una sola columna (04/11, Julio): cada badge con lo que significa, cuándo llega y qué hace el menú ⋯.
 */
import { useRef, useState } from "react";
import type { JSX } from "react";
import { DropModal } from "./lib/DropModal";
import { PUBLICATION_LABEL, PublicationBadge, PublicationPin, type PublicationStatus } from "@/concorde/components/PublicationBadge";

type Kind = "subasta" | "negociable";
type State = { status: PublicationStatus; note: string };
export type Ask = { title: string; options: { label: string; to: PublicationStatus; note?: string }[] };
/** `drop`: confirma en DropModal y la publicación sale de la lista. `icon`: puede ir como botón en la fila. */
export type Action = { label: string; to?: PublicationStatus; note?: string; ask?: Ask; drop?: boolean; danger?: boolean; icon?: ActionIconName };
export type ActionIconName = "trash" | "reload";
export type PubActions = "menu" | "botones";

// 05/11 (Julio): la dada de baja no tiene badge: se confirma en un modal y sale de la lista con animación.
/** Lo que dice la fila en el instante en que se va. */
export const DROPPED_NOTE = "Publicación dada de baja";

// 05/11 (Julio): No concretada es haber estado en SubasChat sin llegar a nada. La fila dice una de estas dos; el motivo se pregunta pero no se muestra.
export const NO_DEAL_NOTE = "No llegaron a un acuerdo";
export const TIME_OUT_NOTE = "El tiempo de negociación expiró";
const NOT_DONE: Ask = { title: "¿Por qué no se concretó?", options: ["El comprador no se presentó", "No nos pusimos de acuerdo en la inspección", "Problemas con los documentos", "El comprador se arrepintió", "Otro motivo"]
  .map((label) => ({ label, to: "no-concretada" as const, note: NO_DEAL_NOTE })) };

// 05/11 (Julio): Dar de baja solo en Publicada, Desierta y No concretada.
const DROP_ACTION: Action = { label: "Dar de baja", drop: true, danger: true, icon: "trash" };
const REPUBLISH: Action = { label: "Republicar", to: "publicada", note: "Republicada hoy", icon: "reload" };

/** Republicar (05/11, Julio): sin confirmar. Carga, se va el texto de antes y entran el texto y el badge nuevos. En `swap` se cambia el estado. */
export function republishSteps(step: (s: "out" | "swap" | "done") => void): void {
  setTimeout(() => step("out"), 900); setTimeout(() => step("swap"), 1250); setTimeout(() => step("done"), 2000);
}

/** Acciones del menú ⋯ según el estado. */
export function menu(s: PublicationStatus): Action[] {
  switch (s) {
    case "revision": case "negociacion": case "subaschat": return []; // sin menú: VMC la revisa, recibe propuestas o se resuelve en el chat
    case "publicada": return [DROP_ACTION];
    case "desierta": case "no-concretada": return [REPUBLISH, DROP_ACTION];
    case "vendido": return [{ label: "Ver detalle de la venta" }];
  }
}

/** Lo que pasa sin que el vendedor toque nada (VMC o el comprador). */
export function events(s: PublicationStatus, kind: Kind): Action[] {
  switch (s) {
    case "revision": return [{ label: "VMC la aprueba", to: kind === "subasta" ? "publicada" : "negociacion", note: kind === "subasta" ? "Subasta programada" : "Recibiendo propuestas" }];
    case "publicada": return [{ label: "Cierra con ganador", to: "vendido", note: "Vendido en subasta" }, { label: "Cierra sin ofertas", to: "desierta", note: "No se recibió ninguna oferta" }];
    case "negociacion": return [{ label: "Acepta una propuesta", to: "subaschat", note: "Acuerdo por US$ 12,500" }, { label: "Vence sin ofertas", to: "desierta", note: "No se recibió ninguna oferta" }];
    case "subaschat": return [{ label: "Confirman la venta", to: "vendido", note: "Vendido en VMC" }, { label: "No se concreta", ask: NOT_DONE }, { label: "Vence el tiempo de negociación", to: "no-concretada", note: TIME_OUT_NOTE }];
    default: return [];
  }
}

const START: Record<PublicationStatus, string> = {
  revision: "Enviada a revisión",
  publicada: "Subasta programada", negociacion: "Recibiendo propuestas", subaschat: "Acuerdo por US$ 12,500", vendido: "Vendido en VMC",
  "no-concretada": NO_DEAL_NOTE, desierta: "No se recibió ninguna oferta",
};

/** Tacho para dar de baja (sale de la lista) y flecha circular para republicar. */
export const ActionIcon = ({ icon }: { icon: ActionIconName }) => <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
  <path d={icon === "trash" ? "M4 7h16M10 11v6M14 11v6M6 7l1 13h10l1-13M9 7V4h6v3" : "M20 12a8 8 0 1 1-2.6-5.9M20 3v5h-5"} /></svg>;

const Dots = () => <svg width="16" height="16" viewBox="0 0 20 20" aria-hidden><circle cx="4" cy="10" r="1.8" fill="currentColor" /><circle cx="10" cy="10" r="1.8" fill="currentColor" /><circle cx="16" cy="10" r="1.8" fill="currentColor" /></svg>;
const Arrow = () => <svg className="pf-arrow" width="14" height="14" viewBox="0 0 20 20" aria-hidden><path d="M4 10h11M11 5l5 5-5 5" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" /></svg>;

/** Estados en una columna: qué significa, cuándo llega y qué hace el menú ⋯. */
const STATES: [PublicationStatus, string, string][] = [
  ["revision", "VMC revisa la publicación antes de publicarla. Los compradores todavía no la ven.", "Al publicar o republicar"],
  ["publicada", "Subasta publicada, a la espera de su fecha.", "VMC aprueba una subasta o se republica"],
  ["negociacion", "Negociable publicada, recibiendo propuestas. Debajo se ve cuántas tiene.", "VMC aprueba una negociable"],
  ["subaschat", "Se aceptó una propuesta. Comprador y vendedor coordinan en el chat.", "El vendedor acepta una propuesta"],
  ["vendido", "Venta hecha.", "Subasta con ganador o venta confirmada en el chat"],
  ["no-concretada", "Estuvieron en SubasChat pero no llegaron a nada. Debajo dice si no hubo acuerdo o si expiró el tiempo.", "Se marca desde el SubasChat o vence el tiempo de negociación"],
  ["desierta", "No se recibió ninguna oferta. Queda fijada arriba de la lista, con chincheta y en negrita, hasta que el vendedor la republique o la dé de baja.", "Cierra sin recibir ninguna oferta"],
];
function StateList(): JSX.Element {
  return <ol className="pf-states">{STATES.map(([st, what, when]) => {
    const acts = menu(st).filter((a) => a.to || a.ask || a.drop);
    const end = (to: PublicationStatus | null | undefined) => (to ? <PublicationBadge status={to} /> : <em>Sale de la lista</em>);
    return <li key={st}>
      <PublicationBadge status={st} />
      <p>{what}</p>
      <dl>
        <div><dt>Llega cuando</dt><dd>{when}</dd></div>
        <div><dt>Menú ⋯</dt><dd>{acts.length ? acts.map((a) => <span key={a.label} className="pf-act">{a.label}<Arrow />{a.drop ? <><em>Confirma en un modal</em><Arrow />{end(null)}</> : a.ask ? <><em>{a.ask.title}</em><Arrow />{end(a.ask.options[0].to)}</> : end(a.to)}</span>) : "Sin acciones"}</dd></div>
      </dl>
    </li>;
  })}</ol>;
}

/** Fila de Mis publicaciones con el menú ⋯ para probar cada acción. */
function Simulator(): JSX.Element {
  const [kind, setKind] = useState<Kind>("negociable");
  const [state, setState] = useState<State>({ status: "negociacion", note: START.negociacion });
  const [open, setOpen] = useState(false);
  const [ask, setAsk] = useState<Ask | null>(null);
  const [asking, setAsking] = useState(""); // acción que abrió la pregunta (Marcar como vendida, Dar de baja…)
  const [log, setLog] = useState<string[]>([]);
  const [actions, setActions] = useState<PubActions>("menu");
  const [exit, setExit] = useState<"" | "leaving" | "gone">(""); // Dar de baja: la fila se va y sale de la lista
  const [drop, setDrop] = useState(false);
  const [phase, setPhase] = useState<"" | "spin" | "out" | "in">(""); // Republicar
  const repub = useRef(0); // al reiniciar, descarta la transición que siga en curso
  const go = (label: string, to: PublicationStatus | null | undefined, note?: string) => {
    setOpen(false); setAsk(null);
    if (to === undefined) { setLog((l) => [`${label}: sin cambio de badge`, ...l].slice(0, 6)); return; }
    const from = PUBLICATION_LABEL[state.status], step = to === null ? `Dar de baja: ${label}` : asking ? `${asking}: ${label}` : label;
    setLog((l) => [`${from} → ${step} → ${to ? PUBLICATION_LABEL[to] : "Sale de la lista"}`, ...l].slice(0, 6)); setAsking("");
    if (to) setState({ status: to, note: note ?? START[to] });
    else { setState((s) => ({ ...s, note: DROPPED_NOTE })); setExit("leaving"); }
  };
  const republish = (a: Action) => {
    const id = ++repub.current; setOpen(false); setPhase("spin");
    setLog((l) => [`${PUBLICATION_LABEL[state.status]} → ${a.label} → ${PUBLICATION_LABEL[a.to!]}`, ...l].slice(0, 6));
    republishSteps((s) => { if (id !== repub.current) return; if (s === "swap") { setState({ status: a.to!, note: a.note! }); setPhase("in"); } else setPhase(s === "out" ? "out" : ""); });
  };
  const run = (a: Action) => (a.drop ? (setDrop(true), setOpen(false)) : a.icon === "reload" ? republish(a) : a.ask ? (setAsk(a.ask), setAsking(a.label), setOpen(false)) : go(a.label, a.to, a.note));
  const reset = (s: PublicationStatus) => { repub.current++; setPhase(""); setDrop(false); setState({ status: s, note: START[s] }); setOpen(false); setAsk(null); setAsking(""); setLog([]); setExit(""); };
  const starts: PublicationStatus[] = kind === "subasta"
    ? ["revision", "publicada", "desierta", "vendido"]
    : ["revision", "negociacion", "subaschat", "desierta", "no-concretada", "vendido"];
  const ev = exit ? [] : events(state.status, kind);
  const leaving = exit === "leaving", busy = phase === "spin" || phase === "out";
  const acts = menu(state.status), quick = actions === "botones" ? acts.filter((a) => a.icon) : [], rest = acts.filter((a) => !quick.includes(a));
  const runEvent = (a: Action) => (a.ask ? (setAsk(a.ask), setAsking(a.label), setOpen(false)) : go(a.label, a.to, a.note));
  return <div className="pf-sim">
    <div className="pf-sim__controls">
      <div className="pf-seg" role="group" aria-label="Tipo de publicación"><span>Tipo</span>
        {(["negociable", "subasta"] as Kind[]).map((k) => <button key={k} type="button" aria-pressed={kind === k} onClick={() => { setKind(k); reset(k === "subasta" ? "publicada" : "negociacion"); }}>{k === "subasta" ? "Subasta" : "Negociable"}</button>)}</div>
      <div className="pf-seg" role="group" aria-label="Empezar en"><span>Empezar en</span>
        {starts.map((s) => <button key={s} type="button" aria-pressed={state.status === s} onClick={() => reset(s)}><PublicationBadge status={s} /></button>)}</div>
      <div className="pf-seg" role="group" aria-label="Acciones"><span>Acciones</span>
        {([["menu", "Menú ⋯"], ["botones", "Botones"]] as const).map(([id, l]) => <button key={id} type="button" aria-pressed={actions === id} onClick={() => { setActions(id); setOpen(false); setAsk(null); }}>{l}</button>)}</div>
    </div>
    <div className="pf-sim__stage">
      {exit === "gone" ? <p className="pf-gone">La publicación salió de la lista.<button type="button" onClick={() => reset(kind === "subasta" ? "publicada" : "negociacion")}>Volver a empezar</button></p> : <div className={`pf-row${leaving ? " pf-row--leaving" : ""}`} data-repub={phase || undefined} onAnimationEnd={(e) => { if (leaving && e.target === e.currentTarget) setExit("gone"); }}>
        <img src="/mi-garaje/garage-photos/picanto/1.jpg" alt="" />
        <span className="pf-row__main"><b>{state.status === "desierta" ? <PublicationPin /> : null}Kia Picanto 2021</b><small className={`vpb-note${["revision", "publicada", "negociacion"].includes(state.status) && !leaving ? "" : " pf-row__note"}`}>{state.note}</small></span>
        {leaving ? null : <span className="pf-row__side"><PublicationBadge status={state.status} />{state.status === "negociacion" ? <small>Propuestas <b>3</b></small> : null}</span>}
        {busy ? <span className="pf-more"><span className="pf-more__btn vpb-spin" role="status" aria-label="Republicando"><ActionIcon icon="reload" /></span></span> : leaving ? null : <span className="pf-more vpb-actions">
          {quick.map((a) => <button key={a.label} type="button" className={`pf-more__btn${a.danger ? " is-danger" : ""}`} aria-label={a.label} title={a.label} onClick={() => run(a)}><ActionIcon icon={a.icon!} /></button>)}
          {rest.length ? <button type="button" className="pf-more__btn" aria-label="Más acciones" aria-expanded={open} onClick={() => { setOpen((v) => !v); setAsk(null); }}><Dots /></button> : null}
          {open ? <div className="pf-menu" role="menu">{rest.map((a) => <button key={a.label} type="button" role="menuitem" className={a.danger ? "is-danger" : undefined} onClick={() => run(a)}>{a.label}</button>)}</div> : null}
          {ask ? <div className="pf-menu pf-menu--ask" role="dialog" aria-label={ask.title}><b>{ask.title}</b>
            {ask.options.map((o) => <button key={o.label} type="button" onClick={() => go(o.label, o.to, o.note)}>{o.label}</button>)}
            <button type="button" className="pf-menu__cancel" onClick={() => setAsk(null)}>Cancelar</button></div> : null}
        </span>}
      </div>}
      {drop ? <DropModal name="Kia Picanto 2021" photo="/mi-garaje/garage-photos/picanto/1.jpg" note={state.note} onClose={() => setDrop(false)} onConfirm={(reason) => { setDrop(false); go(reason, null); }} /> : null}
      {ev.length ? <div className="pf-events"><span>Lo que pasa sin que el vendedor haga nada</span>
        {ev.map((a) => <button key={a.label} type="button" onClick={() => runEvent(a)}>{a.label}</button>)}</div> : null}
      <p className="pf-hint">El texto bajo el nombre es lo que verá el vendedor en Mis publicaciones. Si la das de baja, la fila sale de la lista.</p>
      {log.length ? <div className="pf-log"><b>Lo que hiciste en esta prueba</b><ol>{log.map((l, i) => <li key={i}>{l}</li>)}</ol></div> : null}
    </div>
  </div>;
}

export default function PublicationFlow(): JSX.Element {
  return <section id="flujo-publicacion" className="cx-sec" aria-labelledby="flujo-publicacion-t">
    <style>{CSS}</style>
    <header className="cx-sec__head"><h2 id="flujo-publicacion-t">Flujo de una publicación</h2><code>⋯</code></header>
    <p className="cx-sum">Qué badge tiene la publicación en cada momento y qué pasa con las acciones del menú ⋯.</p>
    <StateList />
    <h3>Pruébalo</h3>
    <Simulator />
  </section>;
}

