/* Resultado de Valorizar · direcciones «Claro» y «Vidrio» (16/10, PROPUESTA para Julio).
   Mismo sistema que el Campo VMC del formulario: tokens --f-*, tarjeta con anillo de 1 px, radio 16/12,
   jerarquía 40/700 cifra · 20/700 título · 16/700 sección · 14/600 etiqueta · 14/400 texto · 12/400 meta,
   espacios 4 · 8 · 16 · 24 · 32. */
.rv { --rv-ink:var(--f-ink,#3B1782); --rv-text:var(--f-text,#191C1C); --rv-muted:var(--f-muted,#6B6878); --rv-hair:var(--f-hair,#E1E3E2); --rv-tint:var(--f-tint,#F5F0FF);
  container-type:inline-size; display:grid; gap:16px; }
.rv-card { display:grid; gap:16px; align-content:start; padding:24px; border-radius:var(--f-r-card,16px); background:#fff; box-shadow:0 0 0 1px var(--rv-hair), 0 1px 2px rgba(34,0,92,.06); min-width:0; }
.rv-card__head { display:grid; gap:4px; }
.rv-card__head--row { display:flex; justify-content:space-between; align-items:flex-start; gap:16px; }
.rv-card__head--row > div { display:grid; gap:4px; }
.rv-card h2 { margin:0; font-size:1rem; font-weight:700; color:var(--rv-ink); }
.rv-card__head p { margin:0; font-size:.875rem; color:var(--rv-muted); text-wrap:pretty; }
.rv-pair { display:grid; gap:16px; }
@container (min-width:880px) { .rv-pair { grid-template-columns:1fr 1fr; } }

/* Valor: la cifra manda; el mercado la acompaña en la misma tarjeta. */
.rv-hero { gap:8px; padding:32px; }
.rv-hero__top { display:flex; justify-content:space-between; align-items:center; gap:16px; }
.rv-meta { margin:0; font-size:.75rem; color:var(--rv-muted); }
.rv-chip { flex:none; padding:4px 10px; border-radius:9999px; font-size:.75rem; font-weight:700; color:var(--rv-ink); background:var(--rv-tint); }
.rv .rv-hero__h { margin:8px 0 0; font-size:.875rem; font-weight:600; color:var(--rv-ink); outline:none; }
.rv-big { font-size:2.5rem; line-height:1.1; font-weight:700; letter-spacing:-0.02em; color:var(--rv-ink); }
