.rv-stage { position:relative; isolation:isolate; display:grid; gap:16px; padding:16px; border-radius:20px; overflow:hidden;
  background:radial-gradient(55% 40% at 88% 4%, rgba(237,137,54,.55), transparent 70%), radial-gradient(60% 45% at 0% 38%, rgba(132,96,229,.75), transparent 70%),
