"use client";

// Resultado de Valorizar · direcciones «Claro» y «Vidrio» (16/10, PROPUESTA para Julio). Mismos datos y textos AVT que el
// resultado actual; cambia la composición: el valor se lee junto al mercado (tira de publicaciones), recompra y Subastop van
// en un solo eje («escalera») y los gráficos tienen eje real. SVG propio: 0 KB de librerías.
import { useLayoutEffect, useRef, useState } from "react";
import type { JSX, ReactNode, MouseEvent as RME } from "react";
import Signal from "@/concorde/components/Signal";
import "./resultado.css";

export type RData = {
  meta: string; market: number; low: number; high: number; conf: number;
  comps: { v: number; km: number; year: number }[]; recompra: number; subastop: number;
  proj: { v: number; full: string; f: number }[]; bridge: { label: string; note: string; v: number }[]; season: { m: number; f: number; name: string }[]; now: number;
  sig: { signal: { level: number; label: string; sublabel: string; color?: string }; seasonal: { currentMonth: string; currentFactorLabel: string; trend: string; trendArrow: string; nextMonth: string; nextFactor?: number };
    timing: { dailyValueLoss: number; bestMonths: { monthLabel: string; isPeakDemand?: boolean; isHighDemand?: boolean }[] }; copy: { headline?: string; body?: string } };
  // 19/10 · AVT ResultScreen: proyección semanal con km (projectForward) y la lista plana de factores
  msrp?: number; pf?: { v: number; km: number; label: string | null; date: Date }[]; factors?: { label: string; value: string; mult?: number; bold?: boolean }[];
};

const usd = (n: number) => `US$ ${Math.round(n).toLocaleString("en-US")}`;
const k1 = (n: number) => `${(n / 1000).toFixed(1).replace(/\.0$/, "")}K`;
const pct = (n: number) => `${n > 0 ? "+" : n < 0 ? "−" : ""}${Math.abs(Math.round(n))} %`;

// Paleta validada con validate_palette.js (claro y sobre #2E0F70): violeta = tu valor / más demanda, naranja = menos demanda.
export const LIGHT = { a: "#8460E5", b: "#ED8936", ink: "#3B1782", text: "#191C1C", muted: "#6B6878", grid: "#ECEAF2", band: "#F5F0FF", mute: "#A39FB3", surface: "#FFFFFF" };
const GLASS = { a: "#9474F5", b: "#D07A2C", ink: "#FFFFFF", text: "#FFFFFF", muted: "#CFBAFF", grid: "rgba(255,255,255,.14)", band: "rgba(255,255,255,.12)", mute: "rgba(255,255,255,.6)", surface: "#3B1782" };
type Theme = typeof LIGHT;

/** Ancho real del contenedor: el SVG se dibuja a su tamaño para que el texto no se encoja en mobile. */
function useW(): [React.RefObject<HTMLDivElement | null>, number] {
  const ref = useRef<HTMLDivElement>(null); const [w, setW] = useState(640);
  useLayoutEffect(() => { const el = ref.current; if (!el) return; const ro = new ResizeObserver(([e]) => setW(Math.round(e.contentRect.width))); ro.observe(el); return () => ro.disconnect(); }, []);
  return [ref, w];
}

/** Tooltip compartido: el mouse y el foco de teclado muestran lo mismo; nunca es la única forma de leer el dato. */
function useTip() {
  const [tip, setTip] = useState<{ x: number; y: number; body: ReactNode } | null>(null);
  const host = useRef<HTMLDivElement>(null);
  const at = (e: { clientX: number; clientY: number }, body: ReactNode) => { const r = host.current!.getBoundingClientRect(); setTip({ x: e.clientX - r.left, y: e.clientY - r.top, body }); };
  const atEl = (el: Element, body: ReactNode) => { const r = host.current!.getBoundingClientRect(), b = el.getBoundingClientRect(); setTip({ x: b.left + b.width / 2 - r.left, y: b.top - r.top, body }); };
  const hit = (body: ReactNode) => ({ tabIndex: 0, className: "rv-hit", onMouseMove: (e: RME) => at(e, body), onFocus: (e: React.FocusEvent) => atEl(e.currentTarget, body), onBlur: () => setTip(null) });
  const layer = tip ? <div className="rv-tip" style={{ left: tip.x, top: tip.y }} role="status">{tip.body}</div> : null;
  return { host, hit, layer, clear: () => setTip(null) };
}

/** Tira de mercado: rango AVT como banda, publicaciones similares como puntos y tu valor encima. */
function Strip({ d, t: th }: { d: RData; t: Theme }): JSX.Element {
  const [ref, W] = useW(), tip = useTip(), H = 104, P = 12;
  const vals = [...d.comps.map((c) => c.v), d.low, d.high], lo = Math.floor(Math.min(...vals) / 500) * 500, hi = Math.ceil(Math.max(...vals) / 500) * 500;
  const x = (v: number) => P + ((v - lo) / (hi - lo)) * (W - 2 * P), y0 = 66;
  const ticks = Array.from({ length: (hi - lo) / 500 + 1 }, (_, i) => lo + i * 500);
  const lx = Math.max(84, Math.min(W - 84, x(d.market)));
  return <div ref={ref} className="rv-w"><div ref={tip.host} className="rv-plot" onMouseLeave={tip.clear}>
    <svg width={W} height={H} className="rv-svg" role="img" aria-label={`Tu valor ${usd(d.market)} dentro del rango ${usd(d.low)} a ${usd(d.high)}, junto a ${d.comps.length} publicaciones similares`}>
      {ticks.map((v) => <g key={v}><line x1={x(v)} x2={x(v)} y1={34} y2={y0 + 14} stroke={th.grid} /><text x={x(v)} y={H - 4} textAnchor="middle" className="rv-tick" fill={th.muted}>{k1(v)}</text></g>)}
      <rect x={x(d.low)} y={y0 - 14} width={x(d.high) - x(d.low)} height={28} rx={14} fill={th.band} />
      {d.comps.map((c, i) => <g key={i} {...tip.hit(<><b>{usd(c.v)}</b><span>{c.year} · {c.km.toLocaleString("en-US")} km</span></>)}>
        <circle cx={x(c.v)} cy={y0} r={12} fill="transparent" /><circle cx={x(c.v)} cy={y0} r={5} fill={th.mute} stroke={th.surface} strokeWidth={2} /></g>)}
      <line x1={x(d.market)} x2={x(d.market)} y1={28} y2={y0} stroke={th.a} strokeWidth={2} />
      <circle cx={x(d.market)} cy={y0} r={8} fill={th.a} stroke={th.surface} strokeWidth={2} />
      <text x={lx} y={20} textAnchor="middle" className="rv-lab" fill={th.ink}>Tu vehículo · {usd(d.market)}</text>
    </svg>{tip.layer}</div>
    <ul className="rv-legend"><li><i style={{ background: th.a }} />Tu vehículo</li><li><i style={{ background: th.mute }} />Publicaciones similares ({d.comps.length})</li><li><i className="rv-sw-band" style={{ background: th.band }} />Rango AVT {usd(d.low)} – {usd(d.high)}</li></ul>
  </div>;
}

/** Escalera de venta: recompra, mercado y Subastop en un solo eje. */
function Ladder({ d, t: th }: { d: RData; t: Theme }): JSX.Element {
  const [ref, W] = useW(), tip = useTip(), narrow = W < 520, rowH = narrow ? 68 : 48, L = narrow ? 8 : Math.min(168, Math.round(W * 0.34)), R = narrow ? 8 : 92, top = 4;
  const lo = Math.floor(d.recompra / 1000) * 1000, hi = Math.ceil(d.high / 1000) * 1000, x = (v: number) => L + ((v - lo) / (hi - lo)) * (W - L - R);
  const rows = [
    { name: "Valor de recompra", note: "Compra inmediata para dealers", v: d.recompra },
    { name: "Valor de mercado", note: "Rango AVT", v: d.market, band: [d.low, d.high] as [number, number], main: true },
    { name: "Estimación Subastop", note: "Cierre en subasta VMC", v: d.subastop },
  ];
  const H = top + rows.length * rowH + 24;
  const ticks = Array.from({ length: (hi - lo) / 1000 + 1 }, (_, i) => lo + i * 1000);
  return <div ref={ref} className="rv-w"><div ref={tip.host} className="rv-plot" onMouseLeave={tip.clear}>
    <svg width={W} height={H} className="rv-svg" role="img" aria-label={rows.map((r) => `${r.name} ${usd(r.v)}`).join(", ")}>
      {ticks.map((v) => <g key={v}><line x1={x(v)} x2={x(v)} y1={top + (narrow ? 24 : 0)} y2={H - 22} stroke={th.grid} /><text x={x(v)} y={H - 6} textAnchor="middle" className="rv-tick" fill={th.muted}>{k1(v)}</text></g>)}
      {rows.map((r, i) => { const cy = top + i * rowH + (narrow ? 48 : rowH / 2), ty = narrow ? top + i * rowH + 14 : cy - 2;
        return <g key={r.name} {...tip.hit(<><b>{r.name} · {usd(r.v)}</b><span>{r.band ? `Rango ${usd(r.band[0])} – ${usd(r.band[1])}` : r.note}</span></>)}>
          <rect x={0} y={cy - rowH / 2} width={W} height={rowH} fill="transparent" />
          <text x={0} y={ty} className={`rv-lab${r.main ? "" : " rv-lab--n"}`} fill={th.text}>{r.name}{narrow ? <tspan className="rv-val" fill={th.text} dx={8}>{usd(r.v)}</tspan> : null}</text>
          {narrow ? null : <text x={0} y={cy + 14} className="rv-tick" fill={th.muted}>{r.note}</text>}
          <line x1={x(lo)} x2={narrow ? x(hi) : x(r.v)} y1={cy} y2={cy} stroke={th.grid} strokeWidth={2} />
          {r.band ? <rect x={x(r.band[0])} y={cy - 8} width={x(r.band[1]) - x(r.band[0])} height={16} rx={8} fill={th.a} opacity={0.2} /> : null}
          <circle cx={x(r.v)} cy={cy} r={r.main ? 8 : 6} fill={r.main ? th.a : th.mute} stroke={th.surface} strokeWidth={2} />
          {narrow ? null : <text x={x(r.band ? r.band[1] : r.v) + 12} y={cy + 5} className={`rv-val${r.main ? " rv-val--b" : ""}`} fill={th.text}>{usd(r.v)}</text>}
        </g>; })}
    </svg>{tip.layer}</div></div>;
}

/** Proyección: eje real, hitos 1/3/6/12 meses, valor final rotulado; cruz con mouse o ← →. */
// ds (19/10, Revela): línea con el degradado primario de Concorde (ProgressBar: #F4AC59 → #8460E5) y puntos blancos con anillo lila.
export function Projection({ d, t: th, gid, ds }: { d: RData; t: Theme; gid: string; ds?: boolean }): JSX.Element {
  // Con ds y d.pf: curva semanal de AVT (projectForward) y sus hitos rotulados (Hoy · 1M · 3M · 6M · 12M), como ChartSVG de AVT.
  const P: { v: number; full: string; lab: string | null; km?: number }[] = ds && d.pf?.length ? d.pf.map((p) => ({ v: p.v, full: p.label ?? "", lab: p.label, km: p.km })) : d.proj.map((p) => ({ v: p.v, full: p.full, lab: null }));
  const marks = ds && d.pf?.length ? P.flatMap((p, i) => (p.lab ? [i] : [])) : [0, 1, 3, 6, 12];
  const [ref, W] = useW(), narrow = W < 480, H = 200, L = 44, R = narrow ? 12 : 108, T = narrow ? 36 : 12, B = 24, n = P.length;
  const vs = P.map((p) => p.v), lo = Math.floor((Math.min(...vs) - 60) / 200) * 200, hi = Math.ceil((Math.max(...vs) + 40) / 200) * 200;
  const x = (i: number) => L + (i / (n - 1)) * (W - L - R), y = (v: number) => T + (1 - (v - lo) / (hi - lo)) * (H - T - B);
  const [hov, setHov] = useState<number | null>(null);
  const pts = P.map((p, i) => `${x(i)},${y(p.v)}`);
  const ticks = Array.from({ length: (hi - lo) / 200 + 1 }, (_, k) => lo + k * 200);
  const last = P[n - 1], drop = ((1 - last.v / d.market) * 100).toFixed(1), h = hov === null ? null : P[hov];
  const move = (e: RME<SVGSVGElement>) => { const r = e.currentTarget.getBoundingClientRect(); setHov(Math.max(0, Math.min(n - 1, Math.round((e.clientX - r.left - L) / (W - L - R) * (n - 1))))); };
  return <div ref={ref} className="rv-w rv-plot">
    <svg width={W} height={H} className="rv-svg" role="img" tabIndex={0} aria-label={`Proyección: de ${usd(d.market)} hoy a ${usd(last.v)} en 12 meses (−${drop} %)`}
      onMouseMove={move} onMouseLeave={() => setHov(null)} onBlur={() => setHov(null)}
      onKeyDown={(e) => { if (e.key === "ArrowRight") setHov((v) => Math.min(n - 1, (v ?? -1) + 1)); if (e.key === "ArrowLeft") setHov((v) => Math.max(0, (v ?? 1) - 1)); }}>
      <defs><linearGradient id={gid} x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor={th.a} stopOpacity={th.surface === "#FFFFFF" ? 0.16 : 0.4} /><stop offset="1" stopColor={th.a} stopOpacity="0" /></linearGradient>
        {ds ? <linearGradient id={`${gid}l`} gradientUnits="userSpaceOnUse" x1={x(0)} x2={x(n - 1)} y1="0" y2="0"><stop offset="0" stopColor="#F4AC59" /><stop offset=".3" stopColor="#ED8936" /><stop offset="1" stopColor="#8460E5" /></linearGradient> : null}</defs>
      {ticks.map((v) => <g key={v}><line x1={L} x2={W - R} y1={y(v)} y2={y(v)} stroke={th.grid} /><text x={L - 8} y={y(v) + 4} textAnchor="end" className="rv-tick" fill={th.muted}>{k1(v)}</text></g>)}
      {(ds && d.pf?.length ? marks : [0, 3, 6, 9, 12]).filter((i) => i < n).map((i) => <text key={i} x={x(i)} y={H - 4} textAnchor="middle" className="rv-tick" fill={th.muted}>{i === 0 ? "Hoy" : ds && d.pf?.length ? P[i].lab : P[i].full.slice(0, 3)}</text>)}
      <path d={`M${x(0)},${H - B} L${pts.join(" L")} L${x(n - 1)},${H - B} Z`} fill={`url(#${gid})`} />
      <polyline points={pts.join(" ")} fill="none" stroke={ds ? `url(#${gid}l)` : th.a} strokeWidth={ds ? 3 : 2} strokeLinejoin="round" strokeLinecap="round" />
      {(ds && d.pf?.length ? marks.slice(1) : [1, 3, 6, 12]).filter((i) => i < n).map((i) => <circle key={i} cx={x(i)} cy={y(P[i].v)} r={ds ? 5 : 4} fill={ds ? "#fff" : th.a} stroke={ds ? "#8460E5" : th.surface} strokeWidth={2} />)}
      <circle cx={x(0)} cy={y(d.market)} r={ds ? 6 : 5} fill={ds ? "#ED8936" : th.a} stroke={th.surface} strokeWidth={2} />
      <text x={narrow ? x(n - 1) : x(n - 1) + 10} y={narrow ? 14 : y(last.v) - 3} textAnchor={narrow ? "end" : "start"} className="rv-val rv-val--b" fill={th.text}>{usd(last.v)}</text>
      <text x={narrow ? x(n - 1) : x(n - 1) + 10} y={narrow ? 30 : y(last.v) + 13} textAnchor={narrow ? "end" : "start"} className="rv-tick" fill={th.muted}>−{drop}{" "}% · 12 meses</text>
      {h ? <g pointerEvents="none"><line x1={x(hov!)} x2={x(hov!)} y1={T} y2={H - B} stroke={th.muted} strokeOpacity={0.5} /><circle cx={x(hov!)} cy={y(h.v)} r={6} fill={th.a} stroke={th.surface} strokeWidth={2} /></g> : null}
    </svg>
    {h ? <div className="rv-tip" style={{ left: x(hov!), top: y(h.v) }} role="status"><b>{h.full ? `${h.full} · ` : ""}{usd(h.v)}</b><span>{hov ? `−${usd(d.market - h.v)} desde hoy${h.km ? ` · ${(h.km / 1000).toFixed(0)}k km` : ""}` : "Valor de hoy"}</span></div> : null}
  </div>;
}

/** Estacionalidad divergente: arriba más demanda (violeta), abajo menos (naranja); «Hoy» rotulado. */
// ds (19/10, Revela): barras con los degradados de Concorde — más demanda = ConditionPill (#AE8EFF → #5A35C2), menos = EN VIVO (#F4AC59 → #B25614).
export function Season({ d, t: th, ds }: { d: RData; t: Theme; ds?: boolean }): JSX.Element {
  const [ref, W] = useW(), tip = useTip(), H = 168, T = 22, B = 28;
  const max = Math.max(...d.season.map((s) => Math.abs(s.f))), y0 = T + (H - T - B) / 2, sy = (H - T - B) / 2 / max, slot = W / 12, bw = Math.min(22, slot * 0.62);
  const bar = (cx: number, f: number) => { const h = Math.abs(f) * sy, x0 = cx - bw / 2, r = Math.min(4, h), s = f >= 0 ? -1 : 1;
    return `M${x0},${y0} V${y0 + s * (h - r)} Q${x0},${y0 + s * h} ${x0 + r},${y0 + s * h} H${x0 + bw - r} Q${x0 + bw},${y0 + s * h} ${x0 + bw},${y0 + s * (h - r)} V${y0} Z`; };
  return <div ref={ref} className="rv-w"><div ref={tip.host} className="rv-plot" onMouseLeave={tip.clear}>
    <svg width={W} height={H} className="rv-svg" role="img" aria-label={d.season.map((s) => `${s.name} ${pct(s.f)}`).join(", ")}>
      {ds ? <defs><linearGradient id="rvs-up" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor="#AE8EFF" /><stop offset="1" stopColor="#5A35C2" /></linearGradient><linearGradient id="rvs-mid" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor="#CFBAFF" /><stop offset="1" stopColor="#8460E5" /></linearGradient><linearGradient id="rvs-dn" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor="#ED8936" /><stop offset="1" stopColor="#F4AC59" /></linearGradient></defs> : null}
      <line x1={0} x2={W} y1={y0} y2={y0} stroke={th.muted} strokeOpacity={0.5} />
      {d.season.map((s, i) => { const cx = slot * i + slot / 2, now = s.m === d.now;
        return <g key={s.m} {...tip.hit(ds ? <b>{s.name} · {s.f > 0 ? "+" : ""}{s.f}%</b> : <><b>{s.name} · {pct(s.f)} demanda</b><span>{s.f > 0 ? "Sobre el promedio del año" : "Bajo el promedio del año"}</span></>)}>
          <rect x={cx - slot / 2} y={T - 16} width={slot} height={H - T + 16} fill="transparent" />
          {ds && now ? <path d={bar(cx, s.f)} fill="none" stroke={s.f >= 0 ? "#8460E5" : "#ED8936"} strokeOpacity={0.28} strokeWidth={8} strokeLinejoin="round" /> : null}
          <path d={bar(cx, s.f)} fill={ds ? `url(#rvs-${s.f > 10 ? "up" : s.f >= 0 ? "mid" : "dn"})` : s.f >= 0 ? th.a : th.b} opacity={now || ds ? 1 : 0.8} stroke={ds && now ? "#fff" : "none"} strokeWidth={ds && now ? 1.5 : 0} />
          {now ? <text x={cx} y={s.f >= 0 ? y0 - Math.abs(s.f) * sy - 6 : y0 + Math.abs(s.f) * sy + 14} textAnchor="middle" className="rv-val rv-val--b" fill={ds ? "#3B1782" : th.text}>{ds ? `${s.f > 0 ? "+" : ""}${s.f}%` : pct(s.f)}</text> : null}
          <text x={cx} y={H - 6} textAnchor="middle" className={`rv-tick${now ? " rv-tick--now" : ""}`} fill={now ? (ds ? "#3B1782" : th.text) : th.muted}>{now && !ds ? "Hoy" : s.name.slice(0, 3)}</text>
        </g>; })}
    </svg>{tip.layer}</div>
    {ds ? null : <ul className="rv-legend"><li><i style={{ background: th.a }} />Más demanda que el promedio</li><li><i style={{ background: th.b }} />Menos demanda</li></ul>}</div>;
}

/** Puente del valor: del precio de lista al valor de mercado, factor por factor (por qué vale lo que vale). */
function Bridge({ d, t: th }: { d: RData; t: Theme }): JSX.Element {
  const [ref, W] = useW(), tip = useTip(), narrow = W < 520, rowH = narrow ? 56 : 40, L = narrow ? 0 : Math.min(190, Math.round(W * 0.34)), R = narrow ? 0 : 104, top = 4;
  const steps = d.bridge, max = steps[0]?.v ?? 1, x = (v: number) => L + (v / max) * (W - L - R);
  const rows = [...steps, { label: "Valor de mercado", note: "Resultado AVT", v: d.market, total: true }] as { label: string; note: string; v: number; total?: boolean }[];
  let run = 0; const H = top + rows.length * rowH + 24;
  return <div ref={ref} className="rv-w"><div ref={tip.host} className="rv-plot" onMouseLeave={tip.clear}>
    <svg width={W} height={H} className="rv-svg" role="img" aria-label={rows.map((r) => `${r.label} ${r.total || r === rows[0] ? usd(r.v) : (r.v < 0 ? "−" : "+") + usd(Math.abs(r.v))}`).join(", ")}>
      {[0, 0.25, 0.5, 0.75, 1].map((k) => <g key={k}><line x1={x(max * k)} x2={x(max * k)} y1={top} y2={H - 22} stroke={th.grid} /><text x={x(max * k)} y={H - 6} textAnchor={k === 0 ? "start" : k === 1 ? "end" : "middle"} className="rv-tick" fill={th.muted}>{k1(max * k)}</text></g>)}
      {rows.map((r, i) => { const first = i === 0, from = r.total || first ? 0 : run, to = r.total || first ? r.v : run + r.v; if (!r.total) run = first ? r.v : run + r.v;
        const y = top + i * rowH + (narrow ? 24 : 8), bh = narrow ? 18 : 24, x0 = x(Math.min(from, to)), bw = Math.max(2, Math.abs(x(to) - x(from)));
        const fill = r.total ? th.ink === "#fff" || th === GLASS ? "#FFFFFF" : th.ink : first ? th.mute : r.v < 0 ? th.b : th.a;
        const rv10 = Math.round(r.v / 10) * 10, val = r.total || first ? usd(r.v) : rv10 === 0 ? "Sin ajuste" : `${rv10 < 0 ? "−" : "+"}${usd(Math.abs(rv10))}`; // AVT redondea a la decena
        return <g key={r.label} {...tip.hit(<><b>{r.label} · {val}</b><span>{r.note}</span></>)}>
          <rect x={0} y={y - (narrow ? 22 : 8)} width={W} height={rowH} fill="transparent" />
          {narrow ? <text x={0} y={y - 6} className={`rv-lab${r.total ? "" : " rv-lab--n"}`} fill={th.text}>{r.label}<tspan className="rv-val" dx={8} fill={th.muted}>{val}</tspan></text>
            : <><text x={0} y={y + 10} className={`rv-lab${r.total ? "" : " rv-lab--n"}`} fill={th.text}>{r.label}</text><text x={0} y={y + 25} className="rv-tick" fill={th.muted}>{r.note.length > 30 ? r.note.slice(0, 29) + "…" : r.note}</text></>}
          <rect x={x0} y={y} width={bw} height={bh} rx={4} fill={fill} opacity={first ? 0.7 : 1} />
          {!narrow ? <text x={W - R + 12} y={y + bh / 2 + 5} className={`rv-val${r.total ? " rv-val--b" : ""}`} fill={th.text}>{val}</text> : null}
          {!r.total && i < rows.length - 1 ? <line x1={x(run)} x2={x(run)} y1={y + bh} y2={y + rowH} stroke={th.muted} strokeOpacity={0.5} /> : null}
        </g>; })}
    </svg>{tip.layer}</div>
    <ul className="rv-legend"><li><i style={{ background: th.b }} />Resta valor</li><li><i style={{ background: th.a }} />Suma valor</li></ul></div>;
}

/** ¿Cuándo vender?: un solo control une proyección y demanda. Se elige el mes (deslizador nativo o tocando la columna). */
export function WhenToSell({ d, t: th, gid }: { d: RData; t: Theme; gid: string }): JSX.Element {
  const [ref, W] = useW(), [sel, setSel] = useState(0), n = d.proj.length, H = 156, L = 8, R = 8, T = 16, B = 8, cellH = 40;
  const vs = d.proj.map((p) => p.v), lo = Math.min(...vs) - 60, hi = Math.max(...vs) + 40;
  const slot = (W - L - R) / n, x = (i: number) => L + slot * i + slot / 2, y = (v: number) => T + (1 - (v - lo) / (hi - lo)) * (H - T - B);
  const p = d.proj[sel], diff = p.v - d.market, best = new Set(d.sig.timing.bestMonths.map((m) => m.monthLabel));
  const maxF = Math.max(...d.proj.map((q) => Math.abs(q.f)), 1);
  return <div ref={ref} className="rv-w rv-when">
    <div className="rv-when__read" aria-live="polite">
      <span>{sel === 0 ? "Si vendes hoy" : `Si vendes en ${p.full}`}</span>
      <b>{usd(p.v)}</b>
      <small>{sel === 0 ? "Valor de mercado hoy" : `${diff < 0 ? "−" : "+"}${usd(Math.abs(diff))} vs hoy`} · demanda {pct(p.f)}{best.has(p.full) ? " · de los mejores meses" : ""}</small>
    </div>
    <svg width={W} height={H + cellH + 22} className="rv-svg" role="img" aria-label={`Valor y demanda mes a mes. ${p.full}: ${usd(p.v)}, demanda ${pct(p.f)}`}>
      <defs><linearGradient id={gid} x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor={th.a} stopOpacity={th === LIGHT ? 0.14 : 0.36} /><stop offset="1" stopColor={th.a} stopOpacity="0" /></linearGradient></defs>
      <path d={`M${x(0)},${H} L${d.proj.map((q, i) => `${x(i)},${y(q.v)}`).join(" L")} L${x(n - 1)},${H} Z`} fill={`url(#${gid})`} />
      <polyline points={d.proj.map((q, i) => `${x(i)},${y(q.v)}`).join(" ")} fill="none" stroke={th.a} strokeWidth={2} strokeLinejoin="round" />
      <line x1={x(sel)} x2={x(sel)} y1={T - 8} y2={H + cellH} stroke={th.ink === "#fff" ? "#fff" : th.ink} strokeOpacity={0.35} />
      {d.proj.map((q, i) => { const on = i === sel, a = 0.14 + (Math.abs(q.f) / maxF) * 0.5, c = q.f >= 0 ? (th === LIGHT ? "132,96,229" : "148,116,245") : (th === LIGHT ? "237,137,54" : "208,122,44");
        return <g key={i} onClick={() => setSel(i)} style={{ cursor: "pointer" }}>
          <rect x={x(i) - slot / 2} y={0} width={slot} height={H + cellH + 22} fill="transparent" />
          <circle cx={x(i)} cy={y(q.v)} r={on ? 7 : 3.5} fill={th.a} stroke={th.surface} strokeWidth={2} />
          <rect x={x(i) - slot / 2 + 1} y={H + 2} width={slot - 2} height={cellH - 4} rx={6} fill={`rgba(${c},${a})`} stroke={on ? (th === LIGHT ? th.ink : "#fff") : "none"} strokeWidth={2} />
          {slot >= 40 ? <text x={x(i)} y={H + cellH / 2 + 4} textAnchor="middle" className="rv-tick" fill={th.text}>{pct(q.f)}</text> : null}
          {on || slot >= 34 || i % 2 === 0 ? <text x={x(i)} y={H + cellH + 16} textAnchor="middle" className={`rv-tick${on ? " rv-tick--now" : ""}`} fill={on ? th.text : th.muted}>{i === 0 ? "Hoy" : q.full.slice(0, 3)}</text> : null}
        </g>; })}
    </svg>
    <label className="rv-when__range"><span className="rv-sr">Mes de venta</span>
      <input type="range" min={0} max={n - 1} step={1} value={sel} onChange={(e) => setSel(Number(e.target.value))} aria-valuetext={`${p.full}: ${usd(p.v)}`} style={{ marginInline: L + slot / 2 - 10 }} /></label>
    <ul className="rv-legend"><li><i style={{ background: th.a }} />Valor proyectado y más demanda</li><li><i style={{ background: th.b }} />Menos demanda</li><li>Más intenso = más fuerte</li></ul>
  </div>;
}

/** Las cuatro secciones del resultado (valor, dónde vender, proyección, momento de venta). Comparables, detalles y la barra
 *  Guardar · Publicar las pone Flujo, iguales en todas las direcciones. */
export default function Resultado({ d, variant }: { d: RData; variant: "claro" | "vidrio" | "explicado" | "simulador" }): JSX.Element {
  const th = variant === "vidrio" ? GLASS : LIGHT, s = d.sig, last = d.proj[d.proj.length - 1];
  const rangeFirst = variant === "explicado";
  const ladder = <section className="rv-card" aria-labelledby="rv-donde">
      <header className="rv-card__head"><h2 id="rv-donde">¿Dónde conviene venderlo?</h2><p>La subasta VMC estima {usd(d.subastop - d.recompra)} más que la recompra inmediata.</p></header>
      <Ladder d={d} t={th} />
    </section>;
  const hero = <section className="rv-card rv-hero" aria-labelledby="fl-h">
      <header className="rv-hero__top"><p className="rv-meta">{d.meta}</p><span className="rv-chip">Confianza {d.conf}{"\u00a0"}%</span></header>
      <h1 id="fl-h" tabIndex={-1} className="rv-hero__h">Valor de mercado hoy</h1>
      {rangeFirst ? <><b className="rv-big rv-big--range">{usd(d.low)}<span> – </span>{usd(d.high)}</b><p className="rv-likely">Más probable: <b>{usd(d.market)}</b> · según {d.comps.length} publicaciones similares</p></> : <b className="rv-big">{usd(d.market)}</b>}
      <p className="rv-sub">Estimación basada en depreciación real, estacionalidad y kilometraje</p>
      <Strip d={d} t={th} />
      <p className="rv-legal">Valuación estimativa generada por el motor AVT.ai. No constituye oferta comercial. Los valores reales pueden variar según condición específica del vehículo, documentación y condiciones del mercado al momento de la transacción.</p>
    </section>;
  if (variant === "simulador") return <div className="rv rv--claro">{hero}
    <section className="rv-card" aria-labelledby="rv-cuando">
      <header className="rv-card__head rv-card__head--row"><div><h2 id="rv-cuando">¿Cuándo te conviene vender?</h2><p>Mueve el mes: valor proyectado y demanda del mercado, juntos.</p></div>
        <span className="rv-signal"><Signal level={s.signal.level} width={20} title={`Nivel ${s.signal.level} de 5`} />{s.signal.label}</span></header>
      <WhenToSell d={d} t={th} gid="rvw" />
      {s.copy.headline ? <p className="rv-note"><b>{s.copy.headline}</b> {s.copy.body}</p> : null}
    </section>
    {ladder}</div>;
  const body = <>
    {hero}
    {rangeFirst && d.bridge.length ? <section className="rv-card" aria-labelledby="rv-puente">
      <header className="rv-card__head"><h2 id="rv-puente">Cómo llegamos a este valor</h2><p>Del precio de lista al valor de mercado, con las mismas fórmulas de AVT.</p></header>
      <Bridge d={d} t={th} />
    </section> : null}
    {ladder}
    <div className="rv-pair">
      <section className="rv-card" aria-labelledby="rv-proy">
        <header className="rv-card__head"><h2 id="rv-proy">Proyección de valor</h2><p>{usd(last.v)} en 12 meses{s.timing.dailyValueLoss > 0 ? <> · pierde ~{usd(s.timing.dailyValueLoss)} por día</> : null}</p></header>
        <Projection d={d} t={th} gid={`rvp-${variant}`} />
      </section>
      <section className="rv-card" aria-labelledby="rv-mom">
        <header className="rv-card__head rv-card__head--row"><div><h2 id="rv-mom">Momento de venta</h2><p>{s.signal.sublabel}</p></div>
          <span className="rv-signal"><Signal level={s.signal.level} width={20} title={`Nivel ${s.signal.level} de 5`} />{s.signal.label}</span></header>
        <Season d={d} t={th} />
        <p className="rv-note">Demanda en {s.seasonal.currentMonth}: <b>{s.seasonal.currentFactorLabel}</b> · tendencia {s.seasonal.trend} {s.seasonal.trendArrow} {s.seasonal.nextMonth}</p>
        {s.timing.bestMonths.length ? <p className="rv-months"><span>Mejores meses</span>{s.timing.bestMonths.map((m) => <em key={m.monthLabel}>{m.monthLabel}</em>)}</p> : null}
        {s.copy.headline ? <p className="rv-note"><b>{s.copy.headline}</b> {s.copy.body}</p> : null}
      </section>
    </div>
  </>;
  return variant === "vidrio" ? <div className="rv rv--vidrio"><div className="rv-stage">{body}</div></div> : <div className="rv rv--claro">{body}</div>;
}

/* Resultado «Revela» (Revela.tsx), en el orden de AVT. Tokens de la maqueta VMC: vault #3B1782 / #8460E5 / #AE8EFF,
   naranja solo en el CTA y en la señal, un gris #6B6878. */
.rva { display:grid; gap:16px; }

/* Héroe: encabezado · valor · las dos tarjetas de AVT en una franja de vidrio */
.rva-hero { position:relative; overflow:hidden; display:grid; grid-template-columns:minmax(0,1fr) 300px; align-items:center; gap:24px; padding:24px; border-radius:var(--f-r-card,16px); color:#fff;
  background:radial-gradient(90% 120% at 100% 0%, #5A35C2 0%, #3B1782 48%, #22005C 100%); box-shadow:0 12px 32px rgba(34,0,92,.25); }
.rva-left { display:grid; gap:16px; min-width:0; }
.rva-top { display:flex; align-items:baseline; flex-wrap:wrap; gap:4px 12px; }
.rva .rva-car { margin:0; font-size:1rem; font-weight:700; letter-spacing:0; color:#fff; } /* le gana a .fl-result h1 */
.rva-meta { margin:0; font-size:.75rem; color:#CFBAFF; }
.rva-value { display:grid; gap:2px; }
.rva-h { margin:0; font-size:.75rem; font-weight:600; color:#E8DEFF; }
.rva-big { margin:0; font-size:3rem; line-height:1.05; font-weight:700; letter-spacing:-0.03em; font-variant-numeric:tabular-nums; }
.rva-note { margin:4px 0 0; font-size:.75rem; color:#CFBAFF; }
/* Recompra y Estimación Subastop: panel de vidrio a la derecha */
.rva-two { list-style:none; margin:0; padding:0; display:grid; border-radius:12px; background:rgba(255,255,255,.08); box-shadow:inset 0 0 0 1px rgba(255,255,255,.14); }
.rva-two li { display:grid; grid-template-columns:32px 1fr; align-items:center; gap:12px; padding:12px 16px; }
.rva-two li + li { border-top:1px solid rgba(255,255,255,.12); }
.rva-two .vd { width:32px; height:32px; }
.rva-two div { display:grid; gap:0; }
.rva-two small, .rva-two div > span { font-size:.75rem; color:#CFBAFF; }
.rva-two b { font-size:1.125rem; font-weight:700; font-variant-numeric:tabular-nums; }
.rva-two .vd, .rva-hero .vd { --solid:#AE8EFF; --glass:#E8DEFF; }

/* Tarjetas: encabezado con ícono de vidrio */
.rva-head { display:grid; grid-template-columns:36px 1fr auto; align-items:center; gap:12px; }
.rva-head h2 { margin:0; font-size:1rem; font-weight:700; color:var(--rv-ink); }
.rva-head p { margin:2px 0 0; font-size:.875rem; color:var(--rv-muted); }

.rva-miles { margin:0; display:grid; grid-template-columns:repeat(4,1fr); gap:8px; }
.rva-miles > div { display:grid; gap:2px; padding:12px 16px; border-radius:12px; background:var(--rv-tint); }
.rva-miles dt { font-size:.75rem; font-weight:700; color:#8460E5; }
.rva-miles dd { margin:0; display:grid; gap:2px; font-size:.9375rem; font-weight:700; color:var(--rv-ink); font-variant-numeric:tabular-nums; }
.rva-miles small { font-size:.75rem; font-weight:400; color:var(--rv-muted); }
@media (max-width:767px) { .rva-miles { grid-template-columns:1fr 1fr; } }

/* Señal de venta */
.rva-sig { margin:0; display:grid; grid-template-columns:repeat(3, minmax(0,1fr)); gap:8px; }
.rva-sig > div { display:grid; gap:4px; align-content:start; padding:16px; border-radius:12px; background:var(--rv-tint); }
.rva-sig dt { font-size:.75rem; color:var(--rv-muted); }
.rva-sig dd { margin:0; display:grid; gap:2px; }
.rva-sig b { font-size:1rem; font-weight:700; color:var(--rv-ink); }
.rva-sig span { font-size:.75rem; color:var(--rv-text); }
.rva-pills { display:flex !important; flex-wrap:wrap; gap:4px; }
.rva-pills em { font-style:normal; padding:2px 10px; border-radius:9999px; font-size:.75rem; font-weight:600; color:#fff; background:#8460E5; }
.rva-copy { margin:0; padding-top:16px; border-top:1px solid var(--rv-hair); font-size:.875rem; line-height:1.5; color:var(--rv-text); }
.rva-copy b { color:var(--rv-ink); }

/* Vehículos similares: mapa del mercado (claro) + tres datos + lista */
.rva-map { position:relative; height:40px; margin-top:24px; }
.rva-map::before { content:""; position:absolute; left:0; right:0; top:50%; height:2px; margin-top:-1px; border-radius:2px; background:#ECEAF2; }
.rva-band { position:absolute; top:50%; height:16px; margin-top:-8px; border-radius:9999px; background:#E8DEFF; transform-origin:left; }
.rva-comp { position:absolute; top:50%; width:10px; height:10px; border-radius:50%; background:#A39FB3; box-shadow:0 0 0 2px #fff; transform:translate(-50%,-50%); }
.rva-dot { position:absolute; top:50%; z-index:1; width:20px; height:20px; border-radius:50%; background:#8460E5; box-shadow:0 0 0 4px #fff, 0 4px 10px rgba(34,0,92,.25); transform:translate(-50%,-50%); }
.rva-dot em { position:absolute; bottom:calc(100% + 10px); left:50%; transform:translateX(-50%); padding:3px 10px; border-radius:9999px; font-style:normal; font-size:.75rem; font-weight:700; white-space:nowrap; color:#fff; background:#3B1782; }
.rva-dot em::after { content:""; position:absolute; top:100%; left:50%; margin-left:-4px; border:4px solid transparent; border-top-color:#3B1782; }
.rva-legend { list-style:none; margin:0; padding:0; display:flex; flex-wrap:wrap; gap:4px 16px; font-size:.75rem; color:var(--rv-muted); }
.rva-legend li { display:flex; align-items:center; gap:6px; }
.rva-legend i { width:8px; height:8px; border-radius:50%; background:#A39FB3; }
.rva-legend i.is-me { width:10px; height:10px; background:#8460E5; }
.rva-legend i.is-band { width:16px; border-radius:9999px; background:#E8DEFF; }
.rva-stats { margin:0; display:grid; grid-template-columns:repeat(3,1fr); border-radius:12px; box-shadow:inset 0 0 0 1px var(--rv-hair); }
.rva-stats > div { display:grid; gap:2px; padding:12px 16px; }
.rva-stats > div + div { box-shadow:inset 1px 0 0 var(--rv-hair); }
.rva-stats dt { font-size:.75rem; color:var(--rv-muted); }
.rva-stats dd { margin:0; font-size:.9375rem; font-weight:700; color:var(--rv-ink); font-variant-numeric:tabular-nums; }
.rva-list { list-style:none; margin:0; padding:0; display:grid; }
.rva-list li { display:grid; grid-template-columns:120px 1fr auto; align-items:center; gap:16px; padding:12px 0; border-bottom:1px solid var(--rv-hair); font-size:.875rem; }
.rva-list li:last-child { border-bottom:0; }
.rva-list b { font-weight:700; color:var(--rv-ink); font-variant-numeric:tabular-nums; }
.rva-list span { color:var(--rv-muted); }
.rva-list em { font-style:normal; font-size:.75rem; font-weight:600; color:var(--rv-ink); padding:2px 8px; border-radius:9999px; background:var(--rv-tint); }

/* Detalles de tu valuación */
.rva-factors { list-style:none; margin:0; padding:0; display:grid; }
.rva-factors li { display:grid; grid-template-columns:32px 1fr auto; align-items:center; gap:12px; padding:12px 0; border-bottom:1px solid var(--rv-hair); }
.rva-factors li > div { display:grid; gap:2px; min-width:0; }
.rva-factors b { font-size:.875rem; font-weight:600; color:var(--rv-ink); }
.rva-factors small { font-size:.75rem; color:var(--rv-muted); }
.rva-factors strong { padding:4px 10px; border-radius:9999px; font-size:.875rem; font-weight:700; font-variant-numeric:tabular-nums; white-space:nowrap; }
.rva-factors strong.is-base { color:var(--rv-ink); background:#ECEAF2; }
.rva-factors strong.is-up { color:#3B1782; background:#F5F0FF; }
.rva-factors strong.is-down { color:#8A3F0B; background:#FFF8F1; }
.rva-factors li.is-total { border-bottom:0; border-top:2px solid var(--rv-ink); margin-top:-1px; }
.rva-factors li.is-total strong { color:#fff; background:#3B1782; }
.rva-legal { margin:0; font-size:.75rem; color:var(--rv-muted); }

.rva--still, .rva--still * { animation:none !important; } /* resultado guardado: sin reveal */
/* Reveal único (~1,4 s): la cifra sube → las dos tarjetas → las secciones en cascada; en el mapa, la banda y los puntos. */
@media (prefers-reduced-motion: no-preference) {
  .rva-big { animation:rva-in .5s cubic-bezier(.05,.7,.1,1) both; }
  .rva-two li { animation:rva-in .45s calc(.3s + var(--j, 0) * 100ms) cubic-bezier(.2,0,0,1) both; } .rva-two li + li { --j:1; }
  .rva-step { animation:rva-in .45s calc(.7s + var(--i) * 90ms) cubic-bezier(.2,0,0,1) both; }
  .rva-band { animation:rva-draw .5s 1.2s cubic-bezier(.05,.7,.1,1) both; }
  .rva-comp { animation:rva-pop .3s calc(1.3s + var(--i) * 50ms) cubic-bezier(.2,0,0,1) both; }
  .rva-dot { animation:rva-pop .4s 1.7s cubic-bezier(.2,0,0,1) both; }
}
@keyframes rva-draw { from { transform:scaleX(0); } }
@keyframes rva-pop { from { opacity:0; transform:translate(-50%,-50%) scale(0); } }
@keyframes rva-in { from { opacity:0; transform:translateY(12px); } }

@media (max-width:767px) {
  .rva-hero { grid-template-columns:minmax(0,1fr); gap:16px; padding:20px; }
  .rva-big { font-size:2.5rem; }
  .rva-two { grid-template-columns:1fr 1fr; } .rva-two li { grid-template-columns:1fr; gap:6px; padding:12px; align-items:start; align-content:start; } .rva-two li + li { border-top:0; border-left:1px solid rgba(255,255,255,.12); }
  .rva-head { grid-template-columns:36px 1fr; } .rva-level { grid-column:1 / -1; justify-self:start; }
  .rva-sig { grid-template-columns:1fr; }
  .rva-stats { grid-template-columns:1fr 1fr; } .rva-stats > div:nth-child(3) { grid-column:1 / -1; box-shadow:inset 0 1px 0 var(--rv-hair); }
  .rva-list li { grid-template-columns:1fr auto; gap:2px 12px; } .rva-list span { grid-row:2; } .rva-list em { grid-row:1 / 3; grid-column:2; }
}
/* Hitos 1M–12M con el lenguaje del DS: tarjeta blanca, borde degradado (#8460E5 → #FFF8F1) y sombra; el hito como etiqueta violeta. */
.rva-miles > div { background-color:#fff; border:1px solid transparent; border-radius:16px;
  background-image:linear-gradient(#fff,#fff), linear-gradient(330deg, #8460E5 0%, #FFF8F1 100%); background-origin:border-box; background-clip:padding-box, border-box; box-shadow:0 4px 12px rgba(34,0,92,.06); }
.rva-miles dt { justify-self:start; padding:2px 8px; border-radius:9999px; font-size:.6875rem; color:#fff; background:linear-gradient(150deg, #8460E5 0%, #3B1782 100%); }
.rva-miles dd { font-size:1rem; }

/* 19/10 · Señal y tarjetas con piezas de Concorde */
/* Datos de la señal: superficie de AmountOption (blanco, borde degradado lila→crema, sombra suave) en vez de lila plano */
.rva-sig > div { border:1px solid transparent; background:linear-gradient(#fff,#fff) padding-box, linear-gradient(335deg,#8460E5 0%,#FFF8F1 100%) border-box; box-shadow:0 0 16px 4px rgba(0,0,0,.05); }
/* Mejores meses: ConditionPill en chico (relleno lila, brillo y borde degradado); degradado oscurecido para texto blanco ≥ 4.5:1 */
.rva-pills em { display:inline-flex; align-items:center; height:24px; padding:0 10px; border:1px solid transparent;
  background:linear-gradient(180deg,rgba(255,255,255,.2),rgba(255,255,255,0) 55%) padding-box, linear-gradient(135deg,#7B58E0,#4A26B0) padding-box, linear-gradient(135deg,#CFBAFF,#fff 40%,#AE8EFF) border-box;
  box-shadow:0 2px 4px rgba(59,23,130,.18); }

/* 19/10 · Señal (AVT: 5 puntos + etiqueta). Pastilla con la superficie de AmountOption; puntos con el degradado naranja de
   Signal / EN VIVO (#F4AC59 → #ED8936 → #B25614), apagados en el lila del riel. Sin la caja oscura ni el «N de 5» */
.rva-level { display:inline-flex; align-items:center; gap:10px; min-width:0; padding:8px 16px 8px 12px; border-radius:9999px; color:var(--rv-ink);
  border:1px solid transparent; background:linear-gradient(#fff,#fff) padding-box, linear-gradient(335deg,#8460E5 0%,#FFF8F1 100%) border-box; box-shadow:0 0 16px 4px rgba(0,0,0,.05); }
.rva-level > i { display:flex; gap:4px; }
.rva-level > i span { width:10px; height:10px; border-radius:50%; background:#ECEAF2; box-shadow:inset 0 1px 2px rgba(34,0,92,.12); }
.rva-level > i span.is-on { background:linear-gradient(135deg,#F4AC59 0%,#ED8936 50%,#B25614 100%); box-shadow:0 1px 3px rgba(178,86,20,.35); }
.rva-level > b { font-size:.9375rem; font-weight:700; color:var(--rv-ink); white-space:nowrap; }
/* Mejores meses en 3 tonos como AVT (pico · alto · otro) */
.rva-pills em.is-high { background:linear-gradient(180deg,rgba(255,255,255,.2),rgba(255,255,255,0) 55%) padding-box, linear-gradient(135deg,#9B7BEA,#6E4BD8) padding-box, linear-gradient(135deg,#CFBAFF,#fff 40%,#AE8EFF) border-box; }
.rva-pills em:not(.is-peak):not(.is-high) { color:#3B1782; background:linear-gradient(#fff,#fff) padding-box, linear-gradient(135deg,#CFBAFF,#AE8EFF) border-box; box-shadow:none; }
/* Momento óptimo: próximo pico y meses a evitar (AVT) */
.rva-ins { list-style:none; margin:0; padding:0; display:flex; flex-wrap:wrap; gap:8px; }
.rva-ins li { display:inline-flex; align-items:center; gap:6px; padding:8px 12px; border-radius:12px; font-size:.8125rem; color:var(--rv-text); box-shadow:inset 0 0 0 1px var(--rv-hair); }
.rva-ins li::before { content:""; width:8px; height:8px; border-radius:50%; }
.rva-ins li.is-up::before { background:linear-gradient(#AE8EFF,#5A35C2); } .rva-ins li.is-up b { color:#5A35C2; }
.rva-ins li.is-down::before { background:linear-gradient(#F4AC59,#B25614); } .rva-ins li.is-down b { color:#B25614; }
/* Similares: ventana de años, marca de ejemplo y extremos de la banda (AVT) */
.rva-win { margin:0; display:flex; align-items:center; gap:8px; font-size:.75rem; color:var(--rv-muted); }
.rva-demo { padding:1px 8px; border-radius:9999px; font-size:.6875rem; font-weight:600; color:#5A35C2; box-shadow:inset 0 0 0 1px #CFBAFF; }
.rva-map { margin-top:8px; }
.rva-ends { margin:-8px 0 0; display:flex; justify-content:space-between; font-size:.75rem; color:var(--rv-muted); font-variant-numeric:tabular-nums; }
.rva-ends b { color:var(--rv-ink); font-weight:700; }
.rva-list li { grid-template-columns:110px 1fr auto; }
.rva-list em.is-up { color:#5A35C2; } .rva-list em.is-down { color:#B25614; } /* lila = favorable, naranja oscuro = desfavorable (sin teal: solo negociable) */
/* Detalles de tu valuación: lista plana de AVT */
.rva-flist { list-style:none; margin:0; padding:0; display:grid; }
.rva-flist li { display:flex; justify-content:space-between; gap:16px; padding:10px 0; border-bottom:1px solid var(--rv-hair); font-size:.875rem; }
.rva-flist li span { color:var(--rv-muted); }
.rva-flist li b { font-weight:600; color:var(--rv-text); text-align:right; font-variant-numeric:tabular-nums; }
.rva-flist li b.is-up { color:#5A35C2; } .rva-flist li b.is-down { color:#B25614; }
.rva-flist li.is-total { border-bottom:0; border-top:2px solid var(--rv-ink); margin-top:-1px; padding-top:12px; }
.rva-flist li.is-total span, .rva-flist li.is-total b { font-weight:700; color:var(--rv-ink); font-size:.9375rem; }
.rva-legal span { color:#A39FB3; }
/* Similares: neutro sin borde; favorable (< −5 %) y desfavorable (> +5 %) con borde de su tono, como las etiquetas de km */
.rva-list em.is-up { background:#fff; box-shadow:inset 0 0 0 1px #AE8EFF; }
.rva-list em.is-down { background:#fff; box-shadow:inset 0 0 0 1px #F4AC59; }
/* 19/10 · Momento óptimo: avisos con la superficie de AmountOption y los puntos con los degradados de las barras */
.rva-ins li { border:1px solid transparent; background:linear-gradient(#fff,#fff) padding-box, linear-gradient(335deg,#8460E5 0%,#FFF8F1 100%) border-box; box-shadow:0 0 16px 4px rgba(0,0,0,.05); }
.rva-ins li.is-down::before { background:linear-gradient(#ED8936,#F4AC59); }
/* 19/10 · Vehículos similares con piezas de Concorde */
.rva-band { background:linear-gradient(90deg,#E8DEFF 0%,#CFBAFF 50%,#E8DEFF 100%); box-shadow:inset 0 0 0 1px rgba(132,96,229,.25); }
.rva-dot { background:linear-gradient(135deg,#AE8EFF 0%,#5A35C2 100%); box-shadow:0 0 0 3px #fff, 0 0 0 4.5px #CFBAFF, 0 6px 14px rgba(90,53,194,.35); }
.rva-stats { border:1px solid transparent; box-shadow:0 0 16px 4px rgba(0,0,0,.05); background:linear-gradient(#fff,#fff) padding-box, linear-gradient(335deg,#8460E5 0%,#FFF8F1 100%) border-box; }
.rva-stats > div + div { box-shadow:inset 1px 0 0 #ECEAF2; }
/* Diferencia vs AVT: neutra en gris (±5 %), favorable lila y desfavorable naranja con borde de su tono */
.rva-list em { color:#6B6878; background:#fff; box-shadow:inset 0 0 0 1px #E1E3E2; }
@media (max-width:640px) {
  .rva-list li { grid-template-columns:1fr auto; grid-template-areas:"p d" "c c"; gap:2px 12px; }
  .rva-list li > b { grid-area:p; } .rva-list li > em { grid-area:d; justify-self:end; } .rva-list li > span { grid-area:c; font-size:.8125rem; }
  .rva-stats { grid-template-columns:repeat(3,minmax(0,1fr)); }
  .rva-stats > div { padding:10px 12px; } .rva-stats > div + div { box-shadow:inset 1px 0 0 #ECEAF2; }
  .rva-stats dd { font-size:.875rem; }
}
@media (max-width:640px) { .rva-stats > div:nth-child(3) { grid-column:auto; box-shadow:inset 1px 0 0 #ECEAF2; } }

"use client";

// Resultado «Revela» (16/10, PROPUESTA para Julio). Mismo contenido y MISMO ORDEN que la pantalla de resultado de AVT
// (avt-ai src/App.jsx ResultScreen): encabezado → Valor de mercado · Hoy → Recompra · Estimación Subastop → Proyección de valor
// (hitos 1M·3M·6M·12M) → Señal de venta AVT → Momento óptimo de venta → Vehículos similares en el mercado → Detalles de tu valuación.
// Solo cambia el diseño: íconos de vidrio, barras y un reveal único de ~1,4 s (sin animación con «reducir movimiento»).
import { useEffect, useState } from "react";
import type { JSX } from "react";
import { Vidrio } from "@/concorde/components/Vidrio";
import { Projection, Season, LIGHT, type RData } from "./Resultado";
import "./resultado.css";
import "./revela.css";

// AVT ResultScreen (App.jsx): tabla de «Momento óptimo de venta» y nombres de mes.
const SELL_SEASONAL: Record<number, number> = { 1: 13.1, 2: 13.1, 3: 8.1, 4: 8.1, 5: 8.1, 6: -5.1, 7: -5.1, 8: 8.1, 9: 13.1, 10: 8.1, 11: -5.1, 12: -5.1 };
const MO_FULL = ["", "Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio", "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre"];
const usd = (n: number) => `US$ ${Math.round(n).toLocaleString("en-US")}`;

/** Cifra que sube hasta el valor (como el Counter de AVT). Solo visual: el valor real va en texto para lectores de pantalla. */
function Count({ to, delay = 0, still }: { to: number; delay?: number; still?: boolean }): JSX.Element {
  const [v, setV] = useState(to);
  useEffect(() => {
    if (still || matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    let raf = 0; const t0 = performance.now() + delay, from = to * 0.85; setV(from);
    const tick = (t: number) => { const p = Math.max(0, Math.min(1, (t - t0) / 900)); setV(from + (to - from) * (1 - Math.pow(1 - p, 3))); if (p < 1) raf = requestAnimationFrame(tick); };
    raf = requestAnimationFrame(tick); return () => cancelAnimationFrame(raf);
  }, [to, delay]);
  return <><span aria-hidden>{usd(v)}</span><span className="g-sr">{usd(to)}</span></>;
}


/** still: resultado ya guardado (Mis valorizaciones): se muestra quieto, el reveal es solo para el momento de valorizar. */
/** El texto de AVT (sellingSignal.js, copia literal) escribe «$» y deja «pierdes ~$0» cuando no hay pérdida diaria:
 *  aquí se muestra en US$ y sin la frase de $0. Reportado a AVT para corregirlo en su fuente. */
const copyBody = (t = "") => t.replace(/[^.]*~?\$0(\/día)?[^.]*\.\s*/g, "").replace(/~?\$(\d[\d,.]*)/g, (m, n) => `${m.startsWith("~") ? "~" : ""}US$ ${n}`).trim();

// at: fecha del cálculo de una valorización guardada («Valor de mercado al 01/10»); sin ella, «hoy» como en AVT.
export default function Revela({ d, still, at }: { d: RData; still?: boolean; at?: string }): JSX.Element {
  const s = d.sig;
  const [car, ...meta] = d.meta.split(" · ");
  // Vehículos similares (AVT): Promedio · Rango · AVT vs Mkt, y cada publicación con su % frente a AVT.
  const vals = d.comps.map((c) => c.v), avg = Math.round(vals.reduce((a, b) => a + b, 0) / vals.length / 10) * 10;
  const cmin = Math.min(...vals), cmax = Math.max(...vals), vsMkt = Math.round(((d.market - avg) / avg) * 100);
  // Escala de AVT: de mín × 0.9 a máx × 1.1 de las publicaciones.
  const X = (v: number) => `${((v - cmin * 0.9) / (cmax * 1.1 - cmin * 0.9)) * 100}%`;
  const yMin = Math.min(...d.comps.map((c) => c.year)), yMax = Math.max(...d.comps.map((c) => c.year));
  const brandModel = d.factors?.[0]?.value ?? car.replace(/\s\d{4}$/, "");
  // Proyección: hitos de projectForward (AVT); Momento óptimo: SELL_SEASONAL de AVT, próximo pico (> 10) y meses bajo 0.
  const miles = (d.pf ?? []).filter((p) => p.label && p.label !== "Hoy") as { v: number; km: number; label: string }[], m12 = miles.find((m) => m.label === "12M");
  const cur = new Date().getMonth() + 1, ahead = Array.from({ length: 12 }, (_, i) => ((cur - 1 + i + 1) % 12) + 1);
  const nextPeak = ahead.find((m) => SELL_SEASONAL[m] > 10), dips = ahead.filter((m) => SELL_SEASONAL[m] < 0);
  const card = (i: number) => ({ className: "rv-card rva-step", style: { ["--i" as string]: i } });

  return <div className={`rv rv--claro rva${still ? " rva--still" : ""}`}>
    {/* 1-3 · Encabezado · Valor de mercado hoy · Recompra y Estimación Subastop (las dos tarjetas de AVT, aquí al pie del héroe) */}
    <section className="rva-hero" aria-labelledby="fl-h">
      <div className="rva-left">
        <header className="rva-top"><h1 id="fl-h" tabIndex={-1} className="rva-car">{car}</h1><p className="rva-meta">{meta.join(" · ")}</p></header>
        <div className="rva-value">
          <p className="rva-h">Valor de mercado {at ? `al ${at}` : "hoy"}</p>
          <p className="rva-big"><Count to={d.market} still={still} /></p>
          <p className="rva-note">Estimación basada en depreciación real, estacionalidad y kilometraje.</p>
        </div>
      </div>
      <ul className="rva-two">
        <li><Vidrio s="billetera" size={40} /><div><small>Valor de recompra</small><b><Count to={d.recompra} delay={300} still={still} /></b><span>Compra inmediata para dealers.</span></div></li>
        <li><Vidrio s="participaciones" size={40} /><div><small>Estimación Subastop</small><b><Count to={d.subastop} delay={400} still={still} /></b><span>Cierre en subasta VMC.</span></div></li>
      </ul>
    </section>

    {/* 4 · Proyección de valor (AVT ResultScreen: projectForward semanal; hitos 1M · 3M · 6M · 12M con valor, % y km) */}
    <section {...card(1)} aria-labelledby="rva-proy">
      <header className="rva-head"><Vidrio s="fecha" size={36} /><div><h2 id="rva-proy">Proyección de valor</h2><p>{m12 ? `−${(((d.market - m12.v) / d.market) * 100).toFixed(1)}% en 12 meses` : "Próximos 12 meses"}</p></div></header>
      <Projection d={d} t={LIGHT} gid="rva-p" ds />
      <dl className="rva-miles">{miles.map((m) => <div key={m.label}><dt>{m.label}</dt><dd>{usd(m.v)}<small>−{(((d.market - m.v) / d.market) * 100).toFixed(1)}% · {(m.km / 1000).toFixed(0)}k km</small></dd></div>)}</dl>
    </section>

    {/* 5 · Señal de venta AVT: 5 puntos + etiqueta, sublabel, demanda del mes y tendencia, pérdida diaria, mejores meses y el texto dinámico */}
    <section {...card(2)} aria-labelledby="rva-sig">
      <header className="rva-head"><Vidrio s="alertas" size={36} /><div><h2 id="rva-sig">Señal de venta AVT</h2><p>{s.signal.sublabel}</p></div>
        <span className="rva-level" role="img" aria-label={`Señal de venta: ${s.signal.label}, ${s.signal.level} de 5`}>
          <i aria-hidden>{[1, 2, 3, 4, 5].map((n) => <span key={n} className={n <= s.signal.level ? "is-on" : ""} />)}</i><b>{s.signal.label}</b></span></header>
      <dl className="rva-sig">
        <div><dt>Demanda en {s.seasonal.currentMonth}</dt><dd><b>{s.seasonal.currentFactorLabel}</b><span>Tendencia: {s.seasonal.trend} {s.seasonal.trendArrow} → {s.seasonal.nextMonth}{s.seasonal.nextFactor !== undefined ? ` (${s.seasonal.nextFactor > 0 ? "+" : ""}${s.seasonal.nextFactor}%)` : ""}</span></dd></div>
        {s.timing.dailyValueLoss > 0 ? <div><dt>Tu auto pierde</dt><dd><b>~US$ {s.timing.dailyValueLoss}/día</b></dd></div> : null}
        {s.timing.bestMonths.length ? <div><dt>Mejores meses</dt><dd className="rva-pills">{s.timing.bestMonths.map((m) => <em key={m.monthLabel} className={m.isPeakDemand ? "is-peak" : m.isHighDemand ? "is-high" : ""}>{m.monthLabel}</em>)}</dd></div> : null}
      </dl>
      {s.copy.headline ? <p className="rva-copy"><b>{s.copy.headline}</b> {copyBody(s.copy.body)}</p> : null}
    </section>

    {/* 6 · Momento óptimo de venta (AVT: SELL_SEASONAL, 3 tonos, mes actual con su %, próximo pico y meses a evitar) */}
    <section {...card(3)} aria-labelledby="rva-mom">
      <header className="rva-head"><Vidrio s="valorizaciones" size={36} /><div><h2 id="rva-mom">Momento óptimo de venta</h2><p>{s.signal.label} · {MO_FULL[cur]}</p></div></header>
      <Season d={{ ...d, now: cur, season: d.season.map((x) => ({ ...x, f: SELL_SEASONAL[x.m] })) }} t={LIGHT} ds />
      {nextPeak || dips.length ? <ul className="rva-ins">
        {nextPeak && nextPeak !== cur ? <li className="is-up">Próximo pico: <b>{MO_FULL[nextPeak]}</b> (+{SELL_SEASONAL[nextPeak]}%)</li> : null}
        {dips.length ? <li className="is-down">Evitar: <b>{[...new Set(dips.slice(0, 2).map((m) => MO_FULL[m]))].join(" – ")}</b> ({SELL_SEASONAL[dips[0]]}%)</li> : null}
      </ul> : null}
    </section>

    {/* 7 · Vehículos similares en el mercado (AVT: banda mín–máx de las publicaciones, marcador AVT, Promedio · Rango ± · AVT vs Mkt).
         En el lab son publicaciones de ejemplo: en producción vienen de getComparables. */}
    <section {...card(4)} aria-labelledby="rva-comp">
      <header className="rva-head"><Vidrio s="auto" size={36} /><div><h2 id="rva-comp">Vehículos similares en el mercado</h2><p>{d.comps.length} publicaciones encontradas</p></div></header>
      <p className="rva-win">Publicaciones de años cercanos · {yMin === yMax ? yMin : `${yMin}–${yMax}`} <span className="rva-demo">Ejemplo</span></p>
      <div className="rva-map" role="img" aria-label={`Publicaciones entre ${usd(cmin)} y ${usd(cmax)}; AVT ${usd(d.market)}`}>
        <span className="rva-band" style={{ left: X(cmin), width: `calc(${X(cmax)} - ${X(cmin)})` }} />
        <span className="rva-dot" style={{ left: X(d.market) }} />
      </div>
      <p className="rva-ends"><span>{usd(cmin)}</span><b>AVT: {usd(d.market)}</b><span>{usd(cmax)}</span></p>
      <dl className="rva-stats">
        <div><dt>Promedio</dt><dd>{usd(avg)}</dd></div>
        <div><dt>Rango</dt><dd>{d.comps.length <= 1 ? "Datos insuficientes" : `±${usd(Math.round((cmax - cmin) / 2 / 100) * 100)}`}</dd></div>
        <div><dt>AVT vs Mkt</dt><dd>{vsMkt >= 0 ? "+" : ""}{vsMkt}%</dd></div>
      </dl>
      <ul className="rva-list">{[...d.comps].map((c) => ({ ...c, dl: Math.round(((c.v - d.market) / d.market) * 100) })).sort((x, y) => Math.abs(x.dl) - Math.abs(y.dl)).map((c, i) =>
        <li key={i}><b>{usd(c.v)}</b><span>{brandModel} {c.year} · {c.km.toLocaleString("en-US")} km</span><em className={c.dl > 5 ? "is-down" : c.dl < -5 ? "is-up" : ""}>{c.dl >= 0 ? "+" : ""}{c.dl}% vs AVT</em></li>)}</ul>
    </section>

    {/* 8 · Detalles de tu valuación (AVT: lista plana — vehículo, MSRP de referencia, años de uso, cada respuesta con su tag y Valor estimado) */}
    <section {...card(5)} aria-labelledby="rva-det">
      <header className="rva-head"><Vidrio s="publicaciones" size={36} /><div><h2 id="rva-det">Detalles de tu valuación</h2><p>{(d.factors ?? []).length} factores</p></div></header>
      <ul className="rva-flist">{(d.factors ?? []).map((r) => <li key={r.label} className={r.bold ? "is-total" : ""}><span>{r.label}</span>
        <b className={r.mult && r.mult > 1 ? "is-up" : r.mult && r.mult < 1 ? "is-down" : ""}>{r.value}</b></li>)}</ul>
    </section>
    <p className="rv-legal rva-legal">Valuación estimativa generada por el motor AVT.ai. No constituye oferta comercial. Los valores reales pueden variar según condición específica del vehículo, documentación y condiciones del mercado al momento de la transacción. <span>v3.0</span></p>
  </div>;
}

/* SubasChat (models/SubasChat.tsx) + panel de revisión de estados (models/Oferta.tsx). */
:root { --rev-w: 240px; --sc-h: 603px; /* 603: el chat termina a la par de «Información general» (columna izquierda) */ --sc-ease: cubic-bezier(0.3, 0, 0, 1); }

/* ── Chat dentro del DetailCard (311 de ancho; reemplaza banner + cuerpo bajo el header oscuro) ── */
/* Ventana de chat en el lugar del DetailCard: mismo ancho (311), radio y sombra que las cards del bloque. */
/* min(…, 100%): en un contenedor más angosto que 311 (pantallas < 360) el chat se encoge en vez de desbordar */
.sc { position: relative; box-sizing: border-box; width: min(311px, 100%); height: var(--sc-h); display: flex; flex-direction: column; overflow: hidden; text-align: left; background: #fff; border-radius: 8px; box-shadow: rgba(0, 0, 0, 0.1) 0 0 16px 4px; animation: sc-open 0.28s var(--sc-ease); }
@keyframes sc-open { from { opacity: 0; transform: translateY(8px); } }
/* Fluido (móvil / ?chat=solo): todo el ancho y el alto visible. 100vh de respaldo → 100dvh → --sc-vh
   (visualViewport, lo pone SubasChat: se encoge con el teclado también en iOS). Safe-area para notch y barra de inicio. */
.sc--fluid { width: 100%; max-width: 480px; height: 100vh; height: 100dvh; height: var(--sc-vh, 100dvh); border-radius: 0; box-shadow: none; }
.sc--fluid .sc__head { height: auto; min-height: 64px; padding-top: env(safe-area-inset-top); padding-left: max(12px, env(safe-area-inset-left)); padding-right: max(14px, env(safe-area-inset-right)); }
.sc--fluid .sc__compose { padding-left: max(8px, env(safe-area-inset-left)); padding-right: max(8px, env(safe-area-inset-right)); }
.sc--fluid .sc__bubble { max-width: min(84%, 360px); }
.sc__head { display: flex; align-items: center; gap: 10px; height: 64px; padding: 0 14px 0 12px; color: #fff; background: linear-gradient(157deg, #5A35C2 0%, #2e0f70 50%, #100030 100%); } /* = .pdetail__head del DetailCard */
.sc__avatar { flex: none; display: grid; place-items: center; width: 40px; height: 40px; border-radius: 50%; font-size: 14px; font-weight: 800; letter-spacing: 0.02em; color: #3B1782; background: #fff; box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.45); }
.sc__who { flex: 1; min-width: 0; }
.sc__who b { display: block; font-size: 15px; line-height: 1.2; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.sc__who span { display: block; font-size: 12px; opacity: 0.95; }
.sc__deal { flex: none; text-align: right; line-height: 1.2; }
.sc__deal small { display: block; font-size: 12px; opacity: 0.9; }
.sc__deal b { font-size: 16px; }
.sc__note p { flex: 1; margin: 0; }
.sc__note button { flex: none; display: grid; place-items: center; width: 24px; height: 24px; margin-top: -3px; border: 0; border-radius: 50%; color: #00595b; background: transparent; cursor: pointer; }
.sc__note button:hover { background: rgba(0, 89, 91, 0.12); }
.sc__note { display: flex; align-items: flex-start; gap: 6px; padding: 8px 6px 8px 12px; font-size: 12px; line-height: 1.4; color: #00595b; background: #E0F5F5; }

.sc__offline { display: flex; align-items: center; gap: 8px; padding: 7px 12px; font-size: 12px; font-weight: 600; color: #7a4b00; background: #fff6e5; border-bottom: 1px solid #f3e2bf; }
.sc__offline::before { content: ""; flex: none; width: 8px; height: 8px; border-radius: 50%; background: #d98a00; }

/* Cuerpo: la lista con scroll + el chip «↓ N mensajes nuevos» flotando encima (fuera del role="log") */
.sc__body { flex: 1; min-height: 0; position: relative; display: flex; flex-direction: column; }
.sc__jump { position: absolute; left: 0; right: 0; bottom: 10px; width: max-content; margin: 0 auto; padding: 7px 14px; border: 0; border-radius: 999px; font: inherit; font-size: 12px; font-weight: 700; color: #fff; background: #3B1782; box-shadow: 0 4px 12px rgba(34, 0, 92, 0.28); cursor: pointer; animation: sc-in 0.15s ease-out; }
.sc__list { flex: 1; min-height: 0; overflow-y: auto; padding: 10px 10px 8px; display: flex; flex-direction: column; gap: 6px; background: #f7f6fb; }
.sc__day { align-self: center; margin: 4px 0; }
.sc__day span { padding: 3px 10px; border-radius: 999px; font-size: 11px; font-weight: 600; color: #55526b; background: #e7e5f0; } /* ≥ 4.5:1 (AA) */
.sc__row { display: flex; flex-direction: column; align-items: flex-start; animation: sc-in 0.18s ease-out; }
.sc__row.is-mine { align-items: flex-end; }
.sc__row.is-cont { margin-top: -4px; } /* ráfaga: 2px entre burbujas del mismo emisor (gap 6) */
@keyframes sc-in { from { opacity: 0; transform: translateY(6px); } }
.sc__bubble { max-width: 84%; padding: 8px 12px 6px; border-radius: 16px 16px 16px 4px; color: #191C1C; background: #fff; box-shadow: 0 1px 2px rgba(34, 0, 92, 0.08); transition: opacity 0.2s; }
.is-mine > .sc__bubble { border-radius: 16px 16px 4px 16px; color: #fff; background-image: linear-gradient(150deg, #8460e5 0%, #3b1782 100%); box-shadow: rgba(32, 0, 104, 0.16) 0 2px 8px; }
/* Ráfaga: la esquina del lado del emisor se aplana arriba en las que continúan (la de abajo ya va a 4px) */
.is-cont > .sc__bubble { border-top-left-radius: 4px; }
.is-mine.is-cont > .sc__bubble { border-top-left-radius: 16px; border-top-right-radius: 4px; }
.sc__bubble p { margin: 0; font-size: 14px; line-height: 1.4; white-space: pre-wrap; overflow-wrap: anywhere; }
.sc__bubble.has-img { padding: 4px 4px 6px; }
.sc__bubble img { display: block; max-width: 200px; max-height: 180px; border-radius: 12px; }
.sc__bubble.has-img p { padding: 6px 8px 0; }
/* Enviando: se atenúa solo el tick, no el texto (opacity .6 en la burbuja bajaba el blanco de 3:1) */
.sc__bubble.is-sending .sc__tick { opacity: 0.7; }
.sc__bubble.is-failed { opacity: 0.75; outline: 2px solid #d64545; outline-offset: 1px; }
/* Hora: color sólido en vez de opacity .7 (en la burbuja propia no llegaba a AA) */
.sc__meta { display: flex; justify-content: flex-end; gap: 4px; margin-top: 2px; font-size: 11px; color: #6b6880; }
.is-mine > .sc__bubble .sc__meta { color: rgba(255, 255, 255, 0.9); }
.sc__bubble.has-img .sc__meta { padding-right: 6px; }
.sc__tick { font-style: normal; }
.sc__sr { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
.sc__fail { margin-top: 4px; max-width: 90%; font-size: 12px; color: #b42318; text-align: right; }
.sc__fail button { margin-left: 8px; padding: 0; border: 0; font: inherit; font-weight: 700; color: #3B1782; text-decoration: underline; background: none; cursor: pointer; }
.sc__bubble a { color: inherit; font-weight: 600; text-decoration: underline; text-underline-offset: 2px; }
.sc__row:not(.is-mine) .sc__bubble a { color: #3B1782; }

.sc__typing { display: inline-flex; gap: 4px; padding: 12px 14px; border-radius: 16px 16px 16px 4px; background: #fff; box-shadow: 0 1px 2px rgba(34, 0, 92, 0.08); }
.sc__typing i { width: 7px; height: 7px; border-radius: 50%; background: #8460e5; animation: sc-dot 1.1s infinite ease-in-out; }
.sc__typing i:nth-child(2) { animation-delay: 0.15s; }
.sc__typing i:nth-child(3) { animation-delay: 0.3s; }
@keyframes sc-dot { 0%, 60%, 100% { transform: translateY(0); opacity: 0.45; } 30% { transform: translateY(-5px); opacity: 1; } }
.sc__typing-l { margin: 3px 0 0 4px; font-size: 11px; color: #6b6880; }

.sc__skel { display: flex; flex-direction: column; gap: 10px; }
.sc__skel span { height: 38px; width: 62%; border-radius: 16px; background: linear-gradient(90deg, #ebe9f3 25%, #f6f5fa 50%, #ebe9f3 75%); background-size: 200% 100%; animation: sc-shine 1.2s infinite linear; }
.sc__skel .is-r { align-self: flex-end; width: 48%; }
.sc__skel .is-short { width: 36%; }
@keyframes sc-shine { to { background-position: -200% 0; } }

.sc__empty, .sc__locked { margin: auto; display: grid; justify-items: center; gap: 10px; max-width: 260px; text-align: center; color: #6b6880; }
.sc__empty svg, .sc__locked svg { color: #8460e5; }
.sc__empty p, .sc__locked p { margin: 0; font-size: 14px; line-height: 1.45; }
.sc__locked { flex: 1; align-content: center; }
.sc__locked b { font-size: 16px; color: #3B1782; }

/* minmax(0, 1fr): con 1fr la columna no baja del ancho propio del botón (padding por defecto) y las 8 no caben en 311 */
.sc__emojis { display: grid; grid-template-columns: repeat(8, minmax(0, 1fr)); gap: 3px; padding: 6px 8px 0; border-top: 1px solid #ecebf3; animation: sc-in 0.15s ease-out; }
.sc__emojis button { min-width: 0; height: 34px; padding: 0; border: 0; border-radius: 10px; font-size: 18px; line-height: 1; background: #f3f1fa; cursor: pointer; }
.sc__emojis button:hover { background: #e7e2fb; }
.sc__compose { display: flex; align-items: flex-end; gap: 2px; padding: 8px; padding-bottom: max(8px, env(safe-area-inset-bottom)); border-top: 1px solid #ecebf3; }
.sc__emojis + .sc__compose, .sc__hint + .sc__compose, .sc__emojis + .sc__hint { border-top: 0; }
/* Fila sobre el compositor: aviso de imagen (izq.) y contador desde el 90 % del límite (der.) */
.sc__hint { display: flex; align-items: baseline; gap: 8px; padding: 6px 14px 0; font-size: 12px; line-height: 1.35; border-top: 1px solid #ecebf3; }
.sc__notice { color: #b42318; }
.sc__count { margin-left: auto; flex: none; color: #6b6880; font-variant-numeric: tabular-nums; }
.sc__count.is-over { color: #b42318; font-weight: 700; }
.sc__compose textarea[aria-invalid="true"] { border-color: #d64545; }
/* 16px: con menos iOS Safari hace zoom al enfocar. La altura la fija SubasChat según el texto (hasta 120px). */
.sc__compose textarea { flex: 1; min-width: 0; box-sizing: border-box; height: 40px; min-height: 40px; max-height: 120px; padding: 8px 14px; border: 1px solid #c9c5dc; border-radius: 20px; font: inherit; font-size: 16px; line-height: 22px; resize: none; overflow-y: auto; }
.sc__compose textarea:focus { outline: none; border-color: #8460e5; box-shadow: 0 0 0 3px rgba(132, 96, 229, 0.25); }
/* Foco por teclado visible en todos los botones del chat (el anillo por defecto no se ve sobre el violeta) */
.sc button:focus-visible { outline: 2px solid #5A35C2; outline-offset: 2px; }
.sc__tool, .sc__send { flex: none; display: grid; place-items: center; width: 36px; height: 40px; border: 0; border-radius: 50%; font-size: 19px; cursor: pointer; }
.sc__tool { color: #3B1782; background: transparent; }
.sc__tool:hover, .sc__tool[aria-pressed="true"] { background: #f3f1fa; }
.sc__send { width: 40px; margin-left: 4px; color: #fff; background: linear-gradient(135deg, #008a8d, #8460e5); /* #00a8ab daba ~2.9:1 con el icono blanco */ transition: transform 0.12s, opacity 0.2s; }
.sc__send:active { transform: scale(0.92); }
.sc__send:disabled, .sc__tool:disabled { opacity: 0.4; cursor: default; }

/* Confirmación al abrir un enlace de fuera de SubasCars */
.sc__leave { position: absolute; inset: 0; z-index: 5; display: grid; place-items: center; padding: 16px; background: rgba(16, 0, 48, 0.45); animation: sc-fade 0.15s ease-out; }
@keyframes sc-fade { from { opacity: 0; } }
.sc__leave-card { width: 100%; box-sizing: border-box; padding: 18px 16px 14px; border-radius: 12px; background: #fff; box-shadow: 0 12px 32px rgba(34, 0, 92, 0.3); }
.sc__leave-card b { display: block; font-size: 16px; color: #3B1782; }
.sc__leave-card p { margin: 8px 0 14px; font-size: 13px; line-height: 1.45; color: #45425a; }
.sc__host { font-weight: 700; color: #191C1C; overflow-wrap: anywhere; }
.sc__leave-act { display: flex; justify-content: flex-end; gap: 8px; }
.sc__leave-act button, .sc__leave-act a { display: inline-grid; place-items: center; min-height: 40px; padding: 0 16px; border-radius: 999px; font: inherit; font-size: 14px; font-weight: 700; text-decoration: none; cursor: pointer; }
.sc__leave-act button { border: 1px solid #c9c5dc; color: #3B1782; background: #fff; }
.sc__leave-act a { border: 0; color: #fff; background: #3B1782; }
.sc__leave-act a:focus-visible { outline: 2px solid #5A35C2; outline-offset: 2px; }

/* ── Panel de revisión (estados) · fijo a la derecha ────── */
.rev {
  position: fixed; top: 0; right: 0; bottom: 0; z-index: 60; width: var(--rev-w); overflow-y: auto;
  padding: 16px 14px; box-sizing: border-box; background: #fff; border-left: 1px solid #e3e1ec; font-size: 13px;
}
.rev h2 { margin: 0 0 2px; font-size: 13px; letter-spacing: 0.04em; text-transform: uppercase; color: #3B1782; }
.rev > p { margin: 0 0 14px; color: #6b6880; font-size: 12px; }
.rev__group { margin-bottom: 16px; }
.rev__label { display: block; margin-bottom: 6px; font-size: 11px; font-weight: 700; letter-spacing: 0.04em; text-transform: uppercase; color: #8a879c; }
.rev__seg { display: grid; grid-template-columns: 1fr 1fr; gap: 4px; padding: 3px; border-radius: 10px; background: #f3f1fa; }
.rev__seg button { padding: 7px 0; border: 0; border-radius: 8px; font: inherit; font-weight: 600; color: #5b5870; background: transparent; cursor: pointer; }
.rev__seg button[aria-pressed="true"] { color: #3B1782; background: #fff; box-shadow: 0 1px 3px rgba(34, 0, 92, 0.12); }
.rev__opt { display: block; width: 100%; margin-bottom: 4px; padding: 8px 10px; border: 1px solid #e3e1ec; border-radius: 10px; font: inherit; text-align: left; background: #fff; cursor: pointer; }
.rev__opt b { display: block; color: #191C1C; }
.rev__opt small { display: block; margin-top: 2px; font-size: 11.5px; line-height: 1.35; color: #6b6880; }
.rev__opt:hover { border-color: #b9a8ef; }
.rev__opt[aria-pressed="true"] { border-color: #8460e5; background: #f3effd; }
.rev__opt[aria-pressed="true"] b { color: #3B1782; }
.rev__act { width: 100%; padding: 9px 10px; border: 1px dashed #8460e5; border-radius: 10px; font: inherit; font-weight: 600; color: #3B1782; background: #fff; cursor: pointer; }
.rev__act:disabled { opacity: 0.45; cursor: default; }
.rev__act + .rev__act { margin-top: 6px; }
.rev__act[aria-pressed="true"] { border-style: solid; background: #fff6e5; color: #7a4b00; border-color: #d98a00; }
.rev__pend { margin: 0; padding: 10px 10px 10px 26px; border-radius: 10px; color: #7a4b00; background: #fff6e5; font-size: 12px; line-height: 1.4; }
.rev__pend li + li { margin-top: 6px; }
.rev__toggle { display: none; }

/* El contenido deja libre el ancho del panel de revisión */
.of-main { padding: 24px calc(var(--rev-w) + 16px) 24px 16px; display: grid; justify-items: center; overflow-x: auto; }
/* El canvas de detalle tiene 1024px fijos: el panel de revisión queda por fuera
   y no puede restarle ancho a las dos columnas del bloque Detalle. */
/* En VMC el detalle llena la columna principal, como en vmcsubastas.com: sin padding ni fondo gris alrededor.
   El lienzo mide 799 y la columna 795: se ajusta al ancho (las dos columnas internas van con space-between). */
.kit-shell--vmc .of-main { padding: 0; overflow: visible; }
.kit-shell--vmc .of-main > [data-block="detalle"] { width: 100% !important; }

@media (max-width: 1100px) {
  :root { --rev-w: 0px; }
  .of-main { padding-right: 16px; }
  .rev { top: 80px; left: auto; bottom: auto; right: 16px; width: 260px; max-height: 70vh; border: 1px solid #e3e1ec; border-radius: 14px; box-shadow: 0 12px 32px rgba(34, 0, 92, 0.22); }
  .rev:not(.is-open) { width: auto; padding: 0; overflow: hidden; }
  .rev:not(.is-open) > :not(.rev__toggle) { display: none; }
  .rev__toggle { display: block; width: 100%; padding: 10px 14px; border: 0; font: inherit; font-weight: 700; color: #3B1782; background: #fff; cursor: pointer; text-align: left; }
}
/* Táctil: áreas de toque de 44px (en escritorio se quedan en 36–40 para no ensanchar el compositor de 311) */
@media (pointer: coarse) {
  .sc__tool, .sc__send { width: 44px; height: 44px; }
  .sc__compose textarea { min-height: 44px; padding-top: 10px; padding-bottom: 10px; }
  .sc__note button { width: 32px; height: 32px; margin: -6px -4px 0 0; }
  .sc__emojis button { height: 40px; }
  .sc__fail button { padding: 8px 4px; }
}
/* Vista ?chat=solo: el chat centrado a pantalla completa, sin el lienzo del Detalle */
.of-solo { display: flex; justify-content: center; min-height: 100vh; min-height: 100dvh; padding-right: var(--rev-w); background: #ecebf3; }
.rev__seg a { display: block; padding: 7px 0; border-radius: 8px; font-weight: 600; text-align: center; text-decoration: none; color: #5b5870; }
.rev__seg a[aria-current="page"] { color: #3B1782; background: #fff; box-shadow: 0 1px 3px rgba(34, 0, 92, 0.12); }

@media (prefers-reduced-motion: reduce) {
  .sc, .sc__row, .sc__emojis, .sc__jump, .sc__leave { animation: none; }
}
/* Detalle con chat: los acordeones de la izquierda con el mismo radio (8) que las tarjetas de la derecha. */
.of-main [data-block="detalle"] .pacc { border-radius: 8px; overflow: hidden; }
/* Móvil (21/10): el bloque Detalle de Concorde es un lienzo de escritorio (799 de ancho, todo en absoluto) y en 390 px
   cortaba la columna derecha (DetailCard / propuesta / chat). Sin tocar concorde/: se apila en una columna con
   el orden foto → tarjeta de acción → condiciones → acordeones → resto; las piezas ya traen max-width:100%. */
@media (max-width: 767px) {
  .kit-shell--vmc .of-main > [data-block="detalle"] { height: auto !important; padding: 16px 16px 24px; }
  .of-main [data-block="detalle"] > div { position: static !important; display: flex !important; flex-direction: column; gap: 16px; }
  .of-main [data-block="detalle"] > div > div { display: contents !important; } /* columnas izquierda y derecha */
  .of-main [data-block="detalle"] > div > div > * { width: 100% !important; max-width: none; box-sizing: border-box; }
  .of-main [data-block="detalle"] > div > div:first-child > :first-child { order: 1; } /* AuctionStatus + CardViewer */
  .of-main [data-block="detalle"] > div > div:last-child > :first-child { order: 2; } /* DetailCard / propuesta / chat */
  .of-main [data-block="detalle"] > div > div:last-child > :nth-child(2) { order: 3; justify-content: space-evenly !important; } /* condiciones */
  .of-main [data-block="detalle"] > div > div:first-child > * { order: 4; } /* acordeones */
  .of-main [data-block="detalle"] > div > div:last-child > * { order: 5; }
  .of-main [data-block="detalle"] [data-slot="secondary-banner"] { position: static !important; transform: none !important; width: 100% !important; margin-top: 16px; }
  .of-main [data-block="detalle"] .pdetail, .of-main [data-block="detalle"] .pp, .of-main [data-block="detalle"] .sc { width: 100%; }
  .of-main [data-block="detalle"] .pcardv__thumb { flex: 1 1 0; min-width: 0; }
}
/* Comprador (21/10): info breve en el chat recién abierto, misma receta que .pp__how (tarjeta de propuesta). */
.sc__intro { margin: auto 0; display: grid; gap: 12px; padding: 16px; border-radius: 12px; background: color-mix(in srgb, #00A8AB 9%, #fff); box-shadow: inset 0 0 0 1px color-mix(in srgb, #00A8AB 35%, #fff); color: #191C1C; }
.sc__intro > b { font-size: 14px; font-weight: 700; color: #3B1782; }
.sc__intro ol { margin: 0; padding: 0; list-style: none; counter-reset: sc; display: grid; gap: 10px; }
.sc__intro li { counter-increment: sc; display: grid; grid-template-columns: 20px 1fr; gap: 8px; font-size: 12px; line-height: 1.45; }
.sc__intro li::before { content: counter(sc); display: grid; place-items: center; width: 20px; height: 20px; border-radius: 50%; background: #00A8AB; color: #fff; font-size: 12px; font-weight: 700; }
.sc__intro li b { font-weight: 700; color: #006466; }

/* Chat cerrado (3 meses después de concretar, decisión de Julio 21/10): el historial queda, el compositor no. */
.sc__closed { margin: 0; padding: 12px 16px; padding-bottom: max(12px, env(safe-area-inset-bottom)); border-top: 1px solid #ecebf3; font-size: 12px; line-height: 1.4; color: #5F5B6B; text-align: center; }
.sc__note small { display: block; margin-top: 2px; font-size: 11px; opacity: .85; }

/* DS (21/10) · Aviso del acuerdo: receta Negociable (como el aviso tutorial de Mi Garaje), cyan-700 → 900, texto blanco. */
.sc__note { padding:10px 8px 10px 14px; color:#fff; background:linear-gradient(90deg, #00A8AB 0%, #006466 100%); font-size:13px; font-weight:700; }
.sc__note small { font-size:11px; font-weight:400; opacity:.92; }
.sc__note button { color:#fff; } .sc__note button:hover { background:rgba(255,255,255,.18); }
/* Tarjeta «Cómo sigue tu compra»: blanca (sombra del ConfirmModal), CardTitle con corchetes, línea de tiempo con el paso
   actual en cian Negociable y los siguientes en vault-200; ProfileButton al pie. */
.sc__intro { gap:14px; padding:16px; border-radius:16px; background:#fff; box-shadow:0 8px 24px rgba(0,0,0,.08); }
.sc__intro .cardtitle { justify-self:start; }
.sc__intro ol { gap:0; counter-reset:none; }
.sc__intro li { position:relative; display:grid; grid-template-columns:1fr; gap:2px; padding:0 0 14px 22px; font-size:12px; line-height:1.4; }
.sc__intro li::before { content:""; position:absolute; left:3px; top:4px; width:10px; height:10px; border-radius:50%; background:#fff; box-shadow:inset 0 0 0 2px #CFBAFF; }
.sc__intro li::after { content:""; position:absolute; left:7px; top:18px; bottom:2px; width:2px; border-radius:2px; background:#E8DEFF; }
.sc__intro li:last-child { padding-bottom:0; } .sc__intro li:last-child::after { display:none; }
.sc__intro li.is-now::before { background:#00A8AB; box-shadow:0 0 0 3px #E0F7F7; }
.sc__intro li b { font-size:13px; font-weight:700; color:#3B1782; }
.sc__intro li span { color:#5F5B6B; }
.sc__intro > .pprofile, .sc__intro > a { justify-self:start; }
.sc__intro-head { display:flex; align-items:baseline; justify-content:space-between; gap:8px; }
.sc__intro-head b { font-size:16px; font-weight:700; color:#3B1782; }
.sc__intro-head span { flex:none; font-size:12px; font-weight:600; color:#006466; }
.sc__note.is-closed { background:linear-gradient(90deg, #5F5B6B 0%, #3B3846 100%); } /* cerrado: gris, ya no es una invitación a escribir */

/* Aviso del sistema (23/10): como el de WhatsApp al activar los mensajes temporales; centrado, crema, con candado, debajo del día. */
.sc__sys { align-self:center; display:flex; align-items:flex-start; gap:6px; max-width:86%; margin:2px auto 8px; padding:6px 10px; border-radius:8px; background:#FFF5D6; color:#5E4B12;
  font-size:.6875rem; line-height:1.45; text-align:center; box-shadow:0 1px .5px rgba(0,0,0,.08); }
.sc__sys b { font-weight:700; }
.sc__sys svg { flex:none; margin-top:2px; color:#9A7B1E; }
/* Verificación de compra a las dos semanas: una tarjeta de sistema dentro del
   historial, no un modal. Usa la misma jerarquía de etiqueta, título y CTA de Concorde. */
.sc__verify { align-self:center; width:min(92%, 370px); margin:10px auto 14px; padding:16px; box-sizing:border-box; border:1px solid var(--vmc-color-vault-200); border-radius:16px; color:var(--foreground); background:var(--vmc-color-base-white); box-shadow:rgba(0,0,0,.1) 0 0 16px 4px; text-align:left; }
.sc__verify-kicker { display:block; margin-bottom:8px; color:var(--vmc-color-teal-600); font-size:10px; font-weight:700; letter-spacing:.07em; text-transform:uppercase; }
.sc__verify-head { display:flex; align-items:center; gap:8px; }
.sc__verify-mark { display:grid; flex:none; place-items:center; width:28px; height:28px; border-radius:50%; color:var(--vmc-color-base-white); background:var(--vmc-color-teal-500); box-shadow:0 0 0 4px color-mix(in srgb,var(--vmc-color-teal-500) 12%,transparent); }
.sc__verify b { display:block; font-size:14px; color:var(--vmc-color-vault-700); }
.sc__verify p { margin:8px 0 14px; font-size:12px; line-height:1.42; color:#6B6878; }
.sc__verify small { display:block; padding:9px 10px; border-radius:8px; font-size:11.5px; line-height:1.4; color:#6B6878; background:var(--vmc-color-vault-100); }
.sc__verify-actions { display:grid; grid-template-columns:1fr 1fr; gap:8px; }
/* Botones Concorde: preservan el gradiente y el borde definidos por el componente,
   solo se compactan al ancho de este aviso. */
.sc__verify-actions :is(.pneg,.poutline) { width:100%; min-width:0; height:36px; padding:0 8px; font-size:12px; line-height:16px; }

"use client";

/**
 * SubasChat · chat del acuerdo (handoff de Julio, 12-oct). Solo frontend: los datos y la contraparte se
 * simulan en ./chat.ts. En el detalle de un acuerdo aceptado REEMPLAZA al DetailCard (Detalle `detailSlot`):
 * una ventana de chat directa con la contraparte (su código de usuario) y el monto acordado arriba.
 * Burbuja propia con el degradado del chat de los KAM (chatbot-ai-vmc MessageBubble: vault-500 → vault-700).
 */
import { Fragment, useEffect, useId, useRef, useState, useSyncExternalStore } from "react";
import type { JSX, MouseEvent, ReactNode } from "react";
import Button from "@/concorde/components/Button";
import {
  COPY, CHAT_MONTHS, EMOJIS, chatUntil, EMPTY_TEXT, ERROR_TEXT, LOCKED_TEXT, MAX_CHARS, MAX_IMAGE_MB, OFFLINE_TEXT, fakeSend, newId, nowHHMM, replyFor, seed,
  type ChatMode, type ChatRole, type Msg,
} from "./chat";
import "./subaschat.css";

// Ráfaga: mensajes seguidos del mismo emisor con < 5 min entre sí (un fallido corta la ráfaga: lleva su aviso debajo).
const mins = (at: string) => { const [h, m] = at.split(":").map(Number); return h * 60 + m; };
const sameBurst = (a?: Msg, b?: Msg) => !!a && !!b && a.mine === b.mine && a.status !== "failed" && Math.abs(mins(b.at) - mins(a.at)) < 5;

// Red del navegador (online/offline); en el servidor se asume conectado.
const subscribeNet = (cb: () => void) => {
  window.addEventListener("online", cb); window.addEventListener("offline", cb);
  return () => { window.removeEventListener("online", cb); window.removeEventListener("offline", cb); };
};
const scrollBehavior = (): ScrollBehavior => (window.matchMedia("(prefers-reduced-motion: reduce)").matches ? "auto" : "smooth");
const NEAR_BOTTOM = 80; // px: más arriba que esto, el usuario está leyendo historial y no se le arrastra al final
const fmt = (n: number) => n.toLocaleString("es-PE");

// Enlaces: http(s)://… o www.…; la puntuación final («…/informe.») queda fuera del enlace.
const URL_RE = /(https?:\/\/[^\s<]+|www\.[^\s<]+)/gi;
const isInternal = (href: string) => {
  try { const h = new URL(href).hostname; return h === window.location.hostname || h === "subascars.com" || h.endsWith(".subascars.com"); }
  catch { return false; }
};
const hostOf = (href: string) => { try { return new URL(href).hostname; } catch { return href; } };
const withLinks = (text: string, onLink: (e: MouseEvent<HTMLAnchorElement>, href: string) => void): ReactNode[] =>
  text.split(URL_RE).map((part, i) => {
    if (i % 2 === 0) return part;
    const tail = /[.,;:!?)\]]+$/.exec(part)?.[0] ?? "";
    const url = part.slice(0, part.length - tail.length);
    const href = /^https?:/i.test(url) ? url : `https://${url}`;
    return <Fragment key={i}><a href={href} target="_blank" rel="noopener noreferrer nofollow" onClick={(e) => onLink(e, href)}>{url}</a>{tail}</Fragment>;
  });

export default function SubasChat({ role, mode, amount, poke, offline = false, fluid = false, noteHidden, onHideNote, intro, system, before, hideHead = false, initialIncoming, purchaseConfirmed = false, onPurchaseConfirmed }: {
  role: ChatRole; mode: ChatMode; amount: string;
  /** Reemplaza el aviso del acuerdo (p. ej. el comprador que aceptó la contrapropuesta). */
  /** Chat recién abierto: info breve de cómo sigue, en lugar del vacío genérico (desaparece con el primer mensaje). */
  intro?: ReactNode;
  /** Aviso del sistema arriba de la conversación, como el de WhatsApp al activar los mensajes temporales (23/10). */
  system?: ReactNode;
  /** Lo que pasó antes del chat (23/10: la negociación), arriba de todo: subiendo se ve como continuación. */
  before?: ReactNode;
  /** Sin el encabezado fijo (23/10: el panel del vendedor lo pone dentro de la lista, debajo de la negociación). */
  hideHead?: boolean;
  /** Mensaje que disparó la notificación de llegada al SubasChat. */
  initialIncoming?: string;
  /** La compra ya fue confirmada y este chat debe reabrirse solo como historial. */
  purchaseConfirmed?: boolean;
  /** Ambas partes confirmaron que la compra se concretó: el comprador la registra en Mis compras. */
  onPurchaseConfirmed?: () => void;
  /** El aviso «Coordina los siguientes pasos…» se puede cerrar; se recuerda mientras dure la página. */
  noteHidden: boolean; onHideNote: () => void;
  /** Cambia → la contraparte escribe y responde (botón «Simular mensaje entrante» del panel de revisión). */
  poke: number;
  /** Simula la red caída (panel de revisión); también reacciona al offline real del navegador. */
  offline?: boolean;
  /** Móvil / pantalla completa: ancho 100 %, alto del viewport visible (se encoge con el teclado), safe-area. */
  fluid?: boolean;
}): JSX.Element {
  const [msgs, setMsgs] = useState<Msg[]>([]);
  const [loading, setLoading] = useState(false);
  const [typing, setTyping] = useState(false);
  const [text, setText] = useState("");
  const [emojis, setEmojis] = useState(false);
  const [unread, setUnread] = useState(0); // entrantes que llegaron mientras el usuario leía más arriba
  const [notice, setNotice] = useState(""); // aviso del compositor (imagen no válida o repetida)
  const [leaving, setLeaving] = useState<string | null>(null); // enlace externo pendiente de confirmar
  const [verification, setVerification] = useState<"pending" | "yes" | "no" | "confirmed" | "reported">(() => purchaseConfirmed ? "confirmed" : "pending");
  const replies = useRef(0);
  const failedOnce = useRef(new Set<string>()); // en «Error de envío» cada mensaje falla una vez; el reintento pasa
  const queued = useRef(new Set<string>()); // enviados sin red: se entregan solos al reconectar
  const seenIds = useRef(new Set<string>());
  const atBottom = useRef(true);
  const msgsRef = useRef<Msg[]>([]);
  const prevRole = useRef(role);
  const urls = useRef(new Set<string>()); // object URLs de imágenes, para liberarlas
  const linkFrom = useRef<HTMLAnchorElement | null>(null);
  const timers = useRef<number[]>([]);
  const listRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const rootRef = useRef<HTMLElement>(null);
  const leaveId = useId();
  const { other, cuu, deal } = COPY[role];

  const netOnline = useSyncExternalStore(subscribeNet, () => navigator.onLine, () => true);
  const online = netOnline && !offline;
  const onlineRef = useRef(online);

  const later = (ms: number, fn: () => void) => { timers.current.push(window.setTimeout(fn, ms)); };
  const clearTimers = () => { timers.current.forEach(clearTimeout); timers.current = []; };

  useEffect(() => { msgsRef.current = msgs; }, [msgs]);

  // Al abrir o cambiar de estado/rol: historial desde cero (con 0.8 s de carga en «Conversación»).
  // Los propios sin entregar (fallidos o en cola sin red) sobreviven al cambio de estado; cambiar de rol es otro chat.
  useEffect(() => {
    clearTimers(); setTyping(false); setText(""); setEmojis(false); setNotice(""); setUnread(0); setVerification(purchaseConfirmed ? "confirmed" : "pending"); replies.current = 0;
    const sameChat = prevRole.current === role;
    prevRole.current = role;
    const keep = sameChat ? msgsRef.current.filter((m) => m.mine && (m.status === "failed" || queued.current.has(m.id))) : [];
    if (!sameChat) queued.current.clear();
    seenIds.current.clear(); atBottom.current = true;
    setMsgs(keep);
    if (mode === "cargando") { setLoading(true); return; }
    // error (23/10): con historial; solo falla el próximo envío.
    if (mode === "normal" || mode === "error" || mode === "verificar" || mode === "cerrado" || mode === "porcerrar") { setLoading(true); later(800, () => {
      const arrived = initialIncoming ? [{ id: `arrival-${role}-${initialIncoming}`, mine: false, text: initialIncoming, at: nowHHMM(), status: "sent" as const }] : [];
      // El cierre no reemplaza la conversación: queda registrado como dos
      // respuestas reales al final del historial para ambos lados.
      const confirmation = purchaseConfirmed ? role === "comprador"
        ? [{ id: "purchase-confirmed-me", mine: true, text: "Sí, la compra se concretó.", at: "10:40", status: "sent" as const }, { id: "purchase-confirmed-other", mine: false, text: "Sí, confirmo que la compra se concretó.", at: "10:41", status: "sent" as const }]
        : [{ id: "purchase-confirmed-other", mine: false, text: "Sí, la compra se concretó.", at: "10:40", status: "sent" as const }, { id: "purchase-confirmed-me", mine: true, text: "Sí, confirmo que la compra se concretó.", at: "10:41", status: "sent" as const }]
        : [];
      setMsgs((m) => [...seed(role), ...arrived, ...confirmation, ...m]); setLoading(false);
    }); }
    else setLoading(false);
    return clearTimers;
  }, [initialIncoming, mode, purchaseConfirmed, role]);

  // Foco al abrir solo con puntero fino: en táctil abriría el teclado virtual y taparía el chat.
  useEffect(() => { if (mode !== "bloqueado" && window.matchMedia("(pointer: fine)").matches) inputRef.current?.focus(); }, [mode]);

  // Fluido: el alto sigue al viewport visible (iOS no encoge dvh con el teclado; visualViewport sí), así el
  // compositor queda siempre a la vista. Sin visualViewport manda el CSS (100dvh).
  useEffect(() => {
    const vv = window.visualViewport; const el = rootRef.current;
    if (!fluid || !vv || !el) return;
    const fit = () => { el.style.setProperty("--sc-vh", `${vv.height}px`); };
    fit(); vv.addEventListener("resize", fit);
    return () => { vv.removeEventListener("resize", fit); el.style.removeProperty("--sc-vh"); };
  }, [fluid]);

  // Autoscroll solo si el usuario ya está abajo o el mensaje nuevo es suyo; si no, se cuentan para el chip «↓ N nuevos».
  useEffect(() => {
    const el = listRef.current; if (!el) return;
    const added = msgs.filter((m) => !seenIds.current.has(m.id));
    added.forEach((m) => seenIds.current.add(m.id));
    if (atBottom.current || added.some((m) => m.mine)) {
      el.scrollTo({ top: el.scrollHeight, behavior: scrollBehavior() }); atBottom.current = true; setUnread(0);
    } else setUnread((n) => n + added.filter((m) => !m.mine).length);
  }, [msgs, typing]);
  const onScroll = () => {
    const el = listRef.current; if (!el) return;
    atBottom.current = el.scrollHeight - el.scrollTop - el.clientHeight < NEAR_BOTTOM;
    if (atBottom.current) setUnread(0);
  };
  const toBottom = () => {
    const el = listRef.current; if (!el) return;
    el.scrollTo({ top: el.scrollHeight, behavior: scrollBehavior() }); atBottom.current = true; setUnread(0);
  };

  // El textarea crece con el texto hasta el max-height del CSS (120px); +2 = bordes (box-sizing: border-box).
  useEffect(() => { const el = inputRef.current; if (!el) return; el.style.height = "auto"; el.style.height = `${el.scrollHeight + 2}px`; }, [text]);

  useEffect(() => { const set = urls.current; return () => set.forEach((u) => URL.revokeObjectURL(u)); }, []);

  const incoming = () => {
    later(600, () => setTyping(true));
    later(2000, () => {
      setTyping(false);
      setMsgs((m) => [...m, { id: newId(), mine: false, text: replyFor(role, replies.current++), at: nowHHMM(), status: "sent" }]);
    });
  };
  useEffect(() => { if (poke && online && mode !== "bloqueado" && mode !== "cargando" && mode !== "cerrado") incoming(); }, [poke]); // eslint-disable-line react-hooks/exhaustive-deps

  const patch = (id: string, status: Msg["status"]) => setMsgs((m) => m.map((x) => (x.id === id ? { ...x, status } : x)));
  const deliver = async (id: string) => {
    patch(id, "sending");
    if (!onlineRef.current) { queued.current.add(id); return; } // queda en «Enviando» hasta que vuelva la red
    const fail = mode === "error" && !failedOnce.current.has(id);
    try { await fakeSend(fail); patch(id, "sent"); incoming(); }
    catch { failedOnce.current.add(id); patch(id, "failed"); }
  };
  // Al reconectar se entrega lo que quedó en cola, en el orden en que se escribió.
  useEffect(() => {
    onlineRef.current = online;
    if (!online || !queued.current.size) return;
    const ids = [...queued.current]; queued.current.clear();
    ids.forEach((id) => void deliver(id));
  }, [online]); // eslint-disable-line react-hooks/exhaustive-deps

  const send = (body: { text?: string; image?: string; sig?: string }) => {
    const id = newId();
    setMsgs((m) => [...m, { id, mine: true, ...body, at: nowHHMM(), status: "sending" }]);
    void deliver(id);
  };
  const remove = (id: string) => {
    const img = msgs.find((m) => m.id === id)?.image;
    if (img) { URL.revokeObjectURL(img); urls.current.delete(img); }
    queued.current.delete(id);
    setMsgs((m) => m.filter((x) => x.id !== id));
    inputRef.current?.focus();
  };
  const over = text.length - MAX_CHARS;
  const submit = () => { const t = text.trim(); if (!t || over > 0) return; send({ text: t }); setText(""); setEmojis(false); inputRef.current?.focus(); };

  const verifyPurchase = (answer: "yes" | "no") => {
    if (verification !== "pending") return;
    const confirmed = answer === "yes";
    setVerification(answer);
    setMsgs((m) => [...m, { id: newId(), mine: true, text: confirmed ? "Sí, la compra se concretó." : "No, la compra no se concretó.", at: nowHHMM(), status: "sent" }]);
    later(700, () => {
      setMsgs((m) => [...m, { id: newId(), mine: false, text: confirmed ? "Sí, confirmo que la compra se concretó." : "No, confirmo que la compra no se concretó.", at: nowHHMM(), status: "sent" }]);
      setVerification(confirmed ? "confirmed" : "reported");
    });
    // Deja visibles ambas respuestas antes de cerrar el chat y mostrar el viaje a Mis compras.
    if (confirmed) later(2100, () => onPurchaseConfirmed?.());
  };

  const pickImage = (f: File) => {
    if (!f.type.startsWith("image/")) { setNotice("Solo puedes enviar imágenes (JPG, PNG, WebP…)."); return; }
    if (f.size > MAX_IMAGE_MB * 1024 * 1024) { setNotice(`La imagen pesa más de ${MAX_IMAGE_MB} MB. Elige una más liviana.`); return; }
    const sig = `${f.name}·${f.size}·${f.lastModified}`;
    if (msgs.some((m) => m.sig === sig && m.status !== "failed")) { setNotice("Ya enviaste esta imagen."); return; }
    setNotice("");
    const url = URL.createObjectURL(f); urls.current.add(url);
    send({ image: url, sig });
  };

  // Enlaces de fuera de SubasCars piden confirmación antes de abrirse.
  const onLink = (e: MouseEvent<HTMLAnchorElement>, href: string) => {
    if (isInternal(href)) return;
    e.preventDefault(); linkFrom.current = e.currentTarget; setLeaving(href);
  };
  const closeLeave = () => { setLeaving(null); linkFrom.current?.focus(); };

  const locked = mode === "bloqueado";
  const purchaseCompleted = purchaseConfirmed || (mode === "verificar" && verification === "confirmed");
  const empty = !loading && !locked && msgs.length === 0;
  const showCount = text.length >= MAX_CHARS * 0.9;

  return <section ref={rootRef} className={`sc${fluid ? " sc--fluid" : ""}`} aria-label={`SubasChat con ${cuu}`}>
{hideHead ? null :       <header className="sc__head">
        <span className="sc__avatar" aria-hidden>{cuu.slice(0, 2)}</span>
        <div className="sc__who"><b>{cuu}</b><span>{other}</span></div>
        <div className="sc__deal"><small>{deal}</small><b>{amount}</b></div>
      </header>}

      {locked ? <div className="sc__locked">
        <svg width="40" height="40" viewBox="0 0 24 24" aria-hidden fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round"><rect x="5" y="11" width="14" height="10" rx="2" /><path d="M8 11V8a4 4 0 0 1 8 0v3" /></svg>
        <b>Acceso restringido</b><p>{LOCKED_TEXT}</p>
      </div> : <>
        {online ? null : <div className="sc__offline" role="status">{OFFLINE_TEXT}</div>}
        {/* El aviso cambia con el estado (antes decía lo mismo abierto, por cerrar y cerrado). La fecha de cierre solo se
            avisa la última semana: desde el día 1 confundía («cerraste» y «abierto hasta»). */}
        {(noteHidden && mode !== "cerrado") || (mode !== "cerrado" && mode !== "porcerrar") ? null : <div className={`sc__note${mode === "cerrado" ? " is-closed" : ""}`}><p suppressHydrationWarning>{mode === "cerrado" ? <>Este chat se cerró<small>Queda como registro de tu {deal.toLowerCase()}. Ya no se pueden enviar mensajes.</small></>
          : mode === "porcerrar" ? <>Este chat se cierra el {chatUntil()}<small>Después queda como registro de tu {deal.toLowerCase()}.</small></>
          : null}</p>
          {mode === "cerrado" ? null : <button type="button" onClick={onHideNote} aria-label="Quitar aviso">
            <svg width="14" height="14" viewBox="0 0 20 20" aria-hidden><path d="M5 5l10 10M15 5L5 15" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" /></svg>
          </button>}</div>}
        <div className="sc__body">
          <div className="sc__list" ref={listRef} onScroll={onScroll} role="log" aria-label={`Mensajes con ${cuu}`} aria-busy={loading}>
            {loading ? <div className="sc__skel" aria-hidden>
              <span className="is-l" /><span className="is-r" /><span className="is-l is-short" />
            </div> : null}
            {before}
            {!loading && system && !msgs.length ? <div className="sc__sys" role="note">{system}</div> : null}
            {empty && intro ? intro : empty ? <div className="sc__empty">
              <svg width="44" height="44" viewBox="0 0 24 24" aria-hidden fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinejoin="round"><path d="M4 5h16v11H9l-5 4z" /><path d="M8 9.5h8M8 12.5h5" strokeLinecap="round" /></svg>
              <p>{EMPTY_TEXT}</p>
            </div> : null}
            {/* Como WhatsApp: primero el día y debajo el aviso del sistema. */}
            {!loading && msgs.length ? <div className="sc__day"><span>Hoy</span></div> : null}
            {!loading && system && msgs.length ? <div className="sc__sys" role="note">{system}</div> : null}
            {loading ? null : msgs.map((m, i) => {
              const cont = sameBurst(msgs[i - 1], m); // no es el primero de su ráfaga
              const more = sameBurst(m, msgs[i + 1]); // no es el último → sin hora (salvo que siga enviándose)
              return <div key={m.id} className={`sc__row${m.mine ? " is-mine" : ""}${cont ? " is-cont" : ""}${more ? " is-more" : ""}`}>
                <div className={`sc__bubble is-${m.status}${m.image ? " has-img" : ""}`}>
                  <span className="sc__sr">{m.mine ? "Tú" : cuu}: </span>
                  {m.image ? <img src={m.image} alt="Imagen enviada" /> : null}
                  {m.text ? <p>{withLinks(m.text, onLink)}</p> : null}
                  {more && m.status === "sent" ? null : <span className="sc__meta">{m.at}{m.mine ? <>
                    <i className="sc__tick" aria-hidden>{m.status === "sent" ? "✓✓" : m.status === "sending" ? "◷" : "!"}</i>
                    <span className="sc__sr">{m.status === "sent" ? "Enviado" : m.status === "sending" ? "Enviando" : "No enviado"}</span></> : null}</span>}
                </div>
                {m.status === "failed" ? <div className="sc__fail" role="alert">{ERROR_TEXT}
                  <button type="button" onClick={() => void deliver(m.id)}>Reintentar</button>
                  <button type="button" onClick={() => remove(m.id)}>Eliminar</button>
                </div> : null}
              </div>;
            })}
            {!loading && mode === "verificar" ? <div className="sc__verify" role="status">
              <span className="sc__verify-kicker">Confirmación · 2 semanas</span>
              <div className="sc__verify-head"><span className="sc__verify-mark" aria-hidden><svg width="16" height="16" viewBox="0 0 20 20" fill="none"><path d="m5 10 3.1 3.1L15.5 6" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" /></svg></span><b>¿Se concretó la compra?</b></div>
              <p>Confirma el resultado para actualizar el estado de tu compra.</p>
              {verification === "pending" ? <div className="sc__verify-actions"><Button variant="negotiable" className="sc__verify-yes" onClick={() => verifyPurchase("yes")}>Sí, se concretó</Button><Button variant="outline" className="sc__verify-no" onClick={() => verifyPurchase("no")}>No se concretó</Button></div>
                : verification === "confirmed" ? <small>Ambas partes confirmaron la compra. Ya se registró en Mis compras.</small>
                : verification === "reported" ? <small>Ambas partes indicaron que no se concretó. Queda registrado en este chat.</small>
                : <small>Registrando tu respuesta con la contraparte…</small>}
            </div> : null}
            {typing ? <div className="sc__row" role="status"><div className="sc__typing" aria-hidden><i /><i /><i /></div><span className="sc__typing-l">{other} está escribiendo…</span></div> : null}
          </div>
          {unread ? <button type="button" className="sc__jump" onClick={toBottom}>
            ↓ {unread} {unread === 1 ? "mensaje nuevo" : "mensajes nuevos"}
          </button> : null}
        </div>

        {emojis ? <div className="sc__emojis" role="group" aria-label="Emojis">
          {EMOJIS.map((e) => <button key={e} type="button" onClick={() => { setText((t) => t + e); inputRef.current?.focus(); }}>{e}</button>)}
        </div> : null}
        {notice || showCount ? <div className="sc__hint">
          {notice ? <span className="sc__notice" role="alert">{notice}</span> : null}
          {showCount ? <span className={`sc__count${over > 0 ? " is-over" : ""}`} aria-live={over > 0 ? "polite" : "off"}>
            {over > 0 ? `Sobran ${fmt(over)} caracteres` : `${fmt(text.length)} / ${fmt(MAX_CHARS)}`}
          </span> : null}
        </div> : null}
        {mode === "cerrado" || purchaseCompleted ? <p className="sc__closed">{purchaseCompleted ? "Compra confirmada · este chat queda como registro y ya no admite mensajes." : `Solo lectura · el chat dura ${CHAT_MONTHS} meses desde el acuerdo`}</p> : <>
        <form className="sc__compose" onSubmit={(e) => { e.preventDefault(); submit(); }}>
          <button type="button" className="sc__tool" aria-label="Emojis" aria-pressed={emojis} onClick={() => setEmojis((v) => !v)} disabled={loading}>😊</button>
          <button type="button" className="sc__tool" aria-label="Enviar imagen" onClick={() => fileRef.current?.click()} disabled={loading}>
            <svg width="20" height="20" viewBox="0 0 24 24" aria-hidden fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinejoin="round"><rect x="3" y="5" width="18" height="14" rx="2" /><circle cx="9" cy="10" r="1.6" /><path d="M21 16l-5-5-8 8" /></svg>
          </button>
          <input ref={fileRef} type="file" accept="image/*" hidden onChange={(e) => { const f = e.target.files?.[0]; if (f) pickImage(f); e.target.value = ""; }} />
          {/* Sin maxLength: al pegar no se corta en silencio; el contador avisa y Enviar se bloquea si sobra texto. */}
          <textarea ref={inputRef} rows={1} value={text} placeholder="Escribe un mensaje…" disabled={loading}
            aria-label={`Mensaje para ${cuu}`} aria-invalid={over > 0} enterKeyHint="send"
            onChange={(e) => { setText(e.target.value); if (notice) setNotice(""); }}
            onKeyDown={(e) => { if (e.key === "Enter" && !e.shiftKey && !e.nativeEvent.isComposing) { e.preventDefault(); submit(); } }} />
          <button type="submit" className="sc__send" aria-label="Enviar" disabled={loading || !text.trim() || over > 0}>
            <svg width="20" height="20" viewBox="0 0 24 24" aria-hidden><path d="M4 12l16-8-6 16-2-7z" fill="currentColor" /></svg>
          </button>
        </form></>}
      </>}

      {leaving ? <div className="sc__leave" role="alertdialog" aria-modal="true" aria-labelledby={`${leaveId}-t`} aria-describedby={`${leaveId}-d`}
        onKeyDown={(e) => { if (e.key === "Escape") closeLeave(); }}>
        <div className="sc__leave-card">
          <b id={`${leaveId}-t`}>Vas a salir de SubasCars</b>
          <p id={`${leaveId}-d`}>El enlace abre <span className="sc__host">{hostOf(leaving)}</span>. Nunca pagues ni compartas datos personales o bancarios fuera de SubasCars.</p>
          <div className="sc__leave-act">
            <button type="button" onClick={closeLeave} autoFocus>Cancelar</button>
            <a href={leaving} target="_blank" rel="noopener noreferrer nofollow" onClick={() => setLeaving(null)}>Abrir enlace</a>
          </div>
        </div>
      </div> : null}
  </section>;
}

