  const svgStroke = disabled   ? "#e1e3e2"
                  : isActive   ? "none"
                  : "var(--vmc-color-vault-600, #5a35c2)";

  return (
    <>
      <style
        id={`${STYLE_ID}-ssr`}
        suppressHydrationWarning
        dangerouslySetInnerHTML={{ __html: PLIKE_STYLES }}
      />
