  background-clip: padding-box, border-box;
  cursor: pointer;
  padding: 2px;
  position: relative;
  overflow: hidden;
  box-shadow: rgba(132, 96, 229, 0.14) 0px 2px 8px;
  transition:
    transform 0.15s cubic-bezier(0.25, 0.8, 0.25, 1),
    box-shadow 0.2s;
  flex-shrink: 0;
  outline: none;
